window.TADABBUR_ZUKHRUF = {"_meta":{"description":"تدبّر سورة الزخرف (٤٣)، وسورةٌ مكّيّةٌ من الحواميم. تُسمّى الزخرفَ لذكرِ زخرفِ الدنيا فيها. محورُها تعظيمُ القرآنِ العربيّ، والردُّ على المشركين في دعوى البناتِ لله وعبادةِ الملائكة، وقصصُ إبراهيمَ وموسى وعيسى، وأنّ الدنيا متاعٌ زائلٌ لا وزنَ لها عند الله، وأنّ الأخلّاءَ يومَ القيامةِ أعداءٌ إلا المتّقين. فيها «وإنه في أم الكتاب لدينا لعلي حكيم»، و«ولولا أن يكون الناس أمة واحدة لجعلنا لمن يكفر بالرحمن... سقفا من فضة»، و«الأخلاء يومئذ بعضهم لبعض عدو إلا المتقين»، و«يا عباد لا خوف عليكم اليوم ولا أنتم تحزنون».","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":43,"name":"الزخرف","total_ayahs":89,"audio":[1,4,32,36,43,57,64,67,68,84],"passages":[{"title":"تعظيمُ القرآنِ العربيِّ وعلوّه، ودوامُ التذكير، وهلاكُ المستهزئين","range":[1,8],"theme":"القسمُ بالكتابِ المبين، وأنّ الله جعله قرآنًا عربيًّا للتعقّل، وأنه في أمِّ الكتابِ عليٌّ حكيم، وأنّ الله لا يترك تذكيرَ المسرفين رحمةً بهم، وكثرةُ الأنبياءِ في الأوّلين وأنّ المكذّبين استهزؤوا بهم فأهلك الله أشدَّ منهم بطشًا","verses":[{"n":1,"reflection":{"text":"«حم»: حروفٌ مقطّعةٌ افتُتِحت بها السورةُ، من المتشابهِ الذي استأثر الله بعلمه، ويُشار بها إلى إعجازِ القرآن؛ ففي هذا تنبيهٌ على عظمةِ القرآن؛ فسلّم لله فيما استأثر بعلمه، وتدبّر ما بيّنه، فالتسليمُ فيما لم تعلم من صفاتِ الراسخين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لله فيما استأثر بعلمه، والتدبّرُ لما بيّن."},"action":{"text":"اعلم أنّ سورةَ الزخرف افتُتِحت بـ«حم» من الحروفِ المقطّعةِ التي هي من المتشابهِ الذي استأثر الله بعلمِ المرادِ منه «حم»؛ وأصحُّ ما قيل فيها الإشارةُ إلى إعجازِ القرآن المؤلَّفِ من جنسِ هذه الحروف؛ فسلّم لما استأثر الله بعلمه من المتشابه؛ وتدبّر واعمل بما بيّنه لك من المحكم؛ فالراسخون في العلمِ يقولون آمنّا به كلٌّ من عند ربنا؛ فاجعل تسليمك لله فيما لم تعلم علامةَ إيمانك؛ فبالتسليمِ والعملِ تُنال الهداية."}},{"n":2,"reflection":{"text":"«والكتاب المبين»: أقسم الله بالكتابِ الواضحِ البيّنِ (القرآن)؛ ففي هذا تعظيمُ شأنِ القرآنِ وبيانُ وضوحه؛ فعظّم القرآنَ الذي أقسم الله به ووصفه بالبيان، وتدبّر بيانه، فالقرآنُ كتابٌ مبينٌ واضح، فاعتنِ به تلاوةً وتدبّرًا وعملًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ المبينِ والاعتناءُ به تلاوةً وتدبّرًا."},"action":{"text":"تأمّل قسمَ الله بكتابه: والكتابِ المبينِ الواضحِ في ألفاظه ومعانيه، البيّنِ للحقِّ والهدى، المُظهِرِ لكلِّ ما يحتاجه العباد «والكتاب المبين»؛ ففي هذا تعظيمُ شأنِ القرآن، وبيانُ وضوحه وبيانه؛ فأقسم الله به تعظيمًا لشأنه؛ فعظّم القرآنَ الذي أقسم الله به؛ فهو كتابٌ مبينٌ واضحُ الدلالة، بيّنُ الأحكامِ والأخبار؛ فتدبّر بيانه، وتأمّل معانيه؛ واعتنِ به تلاوةً وتدبّرًا وعملًا وتحكيمًا؛ فمن عظّم القرآنَ وأقبل عليه اهتدى به؛ فاجعل للقرآنِ المبينِ في قلبك مكانته اللائقة؛ فبتعظيمِ القرآنِ والعملِ به تُنال الهدايةُ والسعادة."}},{"n":3,"reflection":{"text":"«إنا جعلناه قرآنا عربيا لعلكم تعقلون»: إنا جعلناه قرآنًا عربيًّا بلسانٍ عربيٍّ مبين لعلّكم تعقلون معانيه؛ ففي هذا بيانُ حكمةِ إنزالِ القرآنِ عربيًّا للتعقّل؛ فاعقل معانيَ القرآنِ وتدبّرها، فالقرآنُ أُنزِل عربيًّا لتعقله، فأعمل عقلك في فهمِ القرآنِ والعملِ به، فالغايةُ من نزوله التعقّلُ والتدبّر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إعمالُ العقلِ في فهمِ القرآنِ العربيِّ وتدبّرِه."},"action":{"text":"تأمّل حكمةَ إنزالِ القرآنِ عربيًّا: إنا جعلنا هذا الكتابَ قرآنًا عربيًّا بلسانٍ عربيٍّ مبينٍ واضح، لعلّكم أيها العربُ تعقلون معانيه وتفهمونها وتنتفعون بها «إنا جعلناه قرآنا عربيا لعلكم تعقلون»؛ ففي هذا بيانُ حكمةِ إنزالِ القرآنِ بلسانٍ عربيٍّ مبين، وهي أن يعقله الناسُ ويفهموه؛ فالغايةُ من إنزالِ القرآنِ عربيًّا واضحًا التعقّلُ والتدبّرُ والفهمُ والعمل؛ فاعقل معانيَ القرآنِ وتدبّرها؛ وأعمل عقلك في فهمه والعملِ به؛ فما أُنزِل القرآنُ ليُهجَر أو يُتلى بلا تدبّر؛ بل أُنزِل ليُعقَل ويُفهَم ويُعمَل به؛ أفلا يتدبّرون القرآن؛ كتابٌ أنزلناه إليك مبارك ليدبّروا آياته؛ فلا تكن ممّن يقرأ القرآنَ بلا تعقّلٍ ولا تدبّر؛ بل اقرأه بتعقّلٍ وتأمّلٍ وفهم؛ فمن عقل القرآنَ وتدبّره انتفع به واهتدى؛ فاجعل غايتك من القرآنِ التعقّلَ والتدبّرَ والعمل."}},{"n":4,"reflection":{"text":"«وإنه في أم الكتاب لدينا لعلي حكيم»، وإنّ القرآنَ في اللوحِ المحفوظِ عندنا لعليُّ القدرِ حكيمٌ محكم؛ ففي هذا بيانُ علوِّ منزلةِ القرآنِ وإحكامه؛ فعظّم القرآنَ العليَّ الحكيمَ، فهو في أعلى منزلةٍ عند الله، فاجعل له في قلبك مكانةً تليق بعلوّه، فالقرآنُ عليٌّ حكيمٌ محفوظٌ عند الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ العليِّ الحكيم، وإدراكُ علوِّ منزلته عند الله."},"action":{"text":"تأمّل علوَّ منزلةِ القرآن: وإنّ هذا القرآنَ في أمِّ الكتابِ، اللوحِ المحفوظِ الذي هو أصلُ الكتبِ، لدينا وعندنا، لعليُّ القدرِ والمنزلة، حكيمٌ محكمٌ في آياته وأحكامه، لا يأتيه الباطل «وإنه في أم الكتاب لدينا لعلي حكيم»؛ ففي هذا بيانُ علوِّ منزلةِ القرآنِ عند الله، وإحكامه؛ فالقرآنُ مثبتٌ في اللوحِ المحفوظِ عند الله؛ وهو عليُّ القدرِ رفيعُ المنزلة، حكيمٌ محكمُ الآياتِ والأحكام؛ فعظّم القرآنَ العليَّ الحكيمَ في قلبك؛ واعلم أنه في أعلى منزلةٍ عند الله، محفوظٌ في اللوحِ المحفوظ؛ فاجعل له في قلبك مكانةً تليق بعلوّه وإحكامه؛ فمن عرف علوَّ منزلةِ القرآنِ عند الله عظّمه في قلبه؛ فالقرآنُ كلامُ الله العليُّ الحكيم؛ فلا تستهن به، ولا تهجره، ولا تعرض عنه؛ بل عظّمه، وأقبل عليه، واعمل به؛ فبتعظيمِ القرآنِ العليِّ الحكيمِ يُنتفَع به ويُهتَدى بهديه."}},{"n":5,"reflection":{"text":"«أفنضرب عنكم الذكر صفحا أن كنتم قوما مسرفين»: أفنترك إنزالَ القرآنِ وتذكيركم به إعراضًا عنكم لأنكم قومٌ مسرفون في الكفر؟ لا، بل نستمرّ في تذكيركم؛ ففي هذا بيانُ رحمةِ الله في استمرارِ التذكيرِ رغمَ الإسراف؛ فاعلم أنّ الله لا يترك تذكيرَ عباده رحمةً بهم، فاغتنم تذكيرَ الله ولا تسرف في الإعراض، فمن رحمةِ الله دوامُ التذكير.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اغتنامُ تذكيرِ الله، وإدراكُ رحمتِه في دوامِ التذكير."},"action":{"text":"تأمّل رحمةَ الله في دوامِ التذكير: أفنترك ونصرف عنكم الذكرَ، القرآنَ والتذكيرَ به، صفحًا وإعراضًا، ونمسك عن دعوتكم وتذكيركم، لأنكم قومٌ مسرفون في الكفرِ والإعراض؟ لا، بل نستمرّ في تذكيركم وإنزالِ القرآنِ رحمةً بكم وإقامةً للحجّة «أفنضرب عنكم الذكر صفحا أن كنتم قوما مسرفين»؛ ففي هذا بيانُ رحمةِ الله في استمرارِ التذكيرِ والدعوةِ رغمَ إسرافِ العبادِ في الكفر؛ فلم يترك الله تذكيرهم مع إسرافهم؛ بل استمرّ في دعوتهم رحمةً بهم؛ فاعلم أنّ الله لا يترك تذكيرَ عباده وإن أسرفوا، رحمةً بهم وإقامةً للحجّة؛ فاغتنم تذكيرَ الله ودعوته لك عبر القرآن؛ ولا تسرف في الإعراضِ والكفرِ فتُحرَم بركةَ التذكير؛ فمن رحمةِ الله بك أن يذكّرك ويدعوك مع تقصيرك؛ فقابل تذكيرَ الله بالاستجابةِ والإقبال، لا بالإعراضِ والإسراف؛ فاغتنم كلَّ تذكيرٍ من الله لك؛ فمن اغتنم تذكيرَ الله واتّعظ به نجا، ومن أعرض عنه وأسرف في الكفرِ هلك."}},{"n":6,"reflection":{"text":"«وكم أرسلنا من نبي في الأولين»، وكثيرًا من الأنبياءِ أرسلنا في الأممِ الأولين؛ ففي هذا بيانُ كثرةِ الرسلِ ورحمةِ الله بإرسالهم؛ فاعلم أنّ الله أرسل الرسلَ كثيرين رحمةً بالعباد، فآمن بجميعِ الرسل، واشكر نعمةَ الله بإرسالهم، فإرسالُ الرسلِ من أعظمِ رحمةِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بجميعِ الرسل، وشكرُ نعمةِ الله بإرسالهم."},"action":{"text":"تأمّل كثرةَ الرسلِ ورحمةَ الله: وكم أرسلنا من نبيٍّ في الأممِ الأولين، أرسلناهم رحمةً بالعبادِ وهدايةً لهم «وكم أرسلنا من نبي في الأولين»؛ ففي هذا بيانُ كثرةِ الأنبياءِ الذين أرسلهم الله في الأممِ السابقة؛ فما ترك الله أمّةً بلا نذير؛ وإن من أمّةٍ إلا خلا فيها نذير؛ فاعلم أنّ الله أرسل الرسلَ كثيرين رحمةً بالعبادِ وإقامةً للحجّة؛ فآمن بجميعِ رسلِ الله، من ذُكِر منهم ومن لم يُذكَر؛ واشكر نعمةَ الله بإرسالِ الرسلِ لهدايةِ العباد؛ فإرسالُ الرسلِ من أعظمِ رحمةِ الله بخلقه؛ فبهم عرف الناسُ ربهم ودينهم وطريقَ نجاتهم؛ فاحمد الله أن أرسل إليك خاتمَ الأنبياءِ محمدًا ﷺ؛ واتّبع ما جاء به؛ فمن آمن بالرسلِ واتّبعهم نجا؛ فاجعل الإيمانَ بالرسلِ وشكرَ نعمةِ إرسالهم من إيمانك؛ فهم رحمةُ الله بعباده."}},{"n":7,"reflection":{"text":"«وما يأتيهم من نبي إلا كانوا به يستهزئون»، وما يأتي الأممَ نبيٌّ إلا استهزؤوا به؛ ففي هذا تسليةُ النبيِّ بأنّ الاستهزاءَ بالرسلِ قديم؛ فلا يحزنك استهزاءُ المستهزئين بالحقّ، فقد استُهزِئ بالرسلِ قبلك، فاصبر على أذاهم، فالاستهزاءُ بالحقِّ سنّةُ المكذّبين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على الاستهزاءِ بالحق، وإدراكُ أنه سنّةُ المكذّبين."},"action":{"text":"تأمّل تسليةَ الله لنبيّه: وما يأتي هذه الأممَ من نبيٍّ يدعوهم إلى الحقِّ إلا كانوا به يستهزئون ويسخرون «وما يأتيهم من نبي إلا كانوا به يستهزئون»؛ ففي هذا تسليةٌ للنبيِّ ﷺ، وبيانٌ أنّ الاستهزاءَ بالرسلِ سنّةٌ قديمةٌ في الأممِ المكذّبة؛ فما من نبيٍّ إلا استُهزِئ به؛ يا حسرةً على العباد ما يأتيهم من رسولٍ إلا كانوا به يستهزئون؛ فلا يحزنك يا محمدُ استهزاءُ المستهزئين بك وبالحقّ؛ فقد استُهزِئ بالرسلِ من قبلك فصبروا؛ فتأسَّ بهم في الصبرِ على الاستهزاءِ والأذى؛ ولقد استُهزِئ برسلٍ من قبلك؛ فاصبر على أذى المستهزئين وسخريتهم؛ ولا يصدّنّك ذلك عن الحق؛ فالاستهزاءُ بالحقِّ وأهله سنّةُ المكذّبين في كلِّ زمان؛ فلا يهولنّك ذلك؛ بل امضِ في الحقِّ صابرًا محتسبًا؛ فالعاقبةُ للحقِّ وأهله، والخزيُ للمستهزئين؛ فاصبر، ولا تكترث باستهزائهم؛ فإنّ الله كافيك المستهزئين."}},{"n":8,"reflection":{"text":"«فأهلكنا أشد منهم بطشا ومضى مثل الأولين»: فأهلكنا أممًا أشدَّ من هؤلاء قوّةً وبطشًا، ومضت أمثالُ عقوباتِ الأوّلين؛ ففي هذا وعيدُ المستهزئين بعذابِ من هو أقوى منهم؛ فاحذر الاستهزاءَ والتكذيبَ الذي أهلك الأممَ الأقوى، ولا تغترّ بقوّتك، فالقوّةُ لا تدفع عذابَ الله، فاتّعظ بمن قبلك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ بهلاكِ الأممِ الأقوى، وعدمُ الاغترارِ بالقوّة."},"action":{"text":"تأمّل وعيدَ المستهزئين: فأهلكنا أممًا كانوا أشدَّ من هؤلاء المشركين قوّةً وبطشًا وأخذًا، بسببِ استهزائهم وتكذيبهم؛ ومضى وسبق مثلُ الأوّلين، أي سُنّةُ الله في إهلاكهم، أو صفةُ عقوباتهم، عبرةً للآخرين «فأهلكنا أشد منهم بطشا ومضى مثل الأولين»؛ ففي هذا وعيدُ المستهزئين المكذّبين بعذابِ الأممِ الأقوى قبلهم؛ فإذا كان الله أهلك من هو أشدُّ منهم قوّةً، فكيف بهؤلاء الضعفاء؟ فاحذر الاستهزاءَ بالحقِّ والتكذيبَ الذي أهلك الأممَ الأقوى والأشدَّ بطشًا؛ ولا تغترّ بقوّتك ومالك وجاهك؛ فإنّ القوّةَ والبطشَ لا يدفعان عذابَ الله عمّن استحقّه؛ فكم من أمّةٍ قويّةٍ باطشةٍ أهلكها الله بذنوبها؛ فاتّعظ بمن قبلك من الأممِ الهالكة؛ ولا تسلك سبيلهم في الاستهزاءِ والتكذيب؛ فمن اتّعظ بعاقبةِ المكذّبين سلم، ومن اغترّ بقوّته وكذّب هلك؛ فاجعل من مصارعِ الأممِ الأقوى عبرةً تحملك على الإيمانِ وترْكِ الاستهزاء."}}]},{"title":"إقرارُ المشركين بالخالقِ ونعمُه، وذكرُ النعمةِ عند الركوبِ والرجوعِ إلى الله","range":[9,14],"theme":"إقرارُ المشركين بأنّ العزيزَ العليمَ خلق السماواتِ والأرض، وتعدادُ نعمِه في تمهيدِ الأرضِ وجعلِ السبلِ وإنزالِ الماءِ وإحياءِ الأرضِ دليلًا على البعث، وخلقِ الأزواجِ وتسخيرِ الفلكِ والأنعام، وتعليمُ ذكرِ النعمةِ والتسبيحِ عند الركوبِ وتذكّرِ الرجوعِ إلى الله","verses":[{"n":9,"reflection":{"text":"«ولئن سألتهم من خلق السماوات والأرض ليقولن خلقهن العزيز العليم»، ولئن سألت المشركين من خلق السماواتِ والأرض ليقولنّ: خلقهنّ العزيزُ العليم؛ ففي هذا إقرارُ المشركين بالخالقِ وإلزامهم بتوحيدِ العبادة؛ فاعلم أنّ من أقرّ بأنّ الله الخالقُ يلزمه أن يعبده وحده، فوحّد الخالقَ العزيزَ العليمَ في العبادةِ كما تفرّد بالخلق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ الخالقِ العزيزِ العليمِ في العبادة، كما تفرّد بالخلق."},"action":{"text":"تأمّل إقرارَ المشركين بالخالق: ولئن سألت المشركين من خلق السماواتِ والأرض ليقولنّ مقرّين: خلقهنّ العزيزُ الغالبُ، العليمُ بكلِّ شيء «ولئن سألتهم من خلق السماوات والأرض ليقولن خلقهن العزيز العليم»؛ ففي هذا إقرارُ المشركين بأنّ الله هو الخالقُ، وإلزامهم بتوحيدِ العبادةِ الذي أنكروه؛ فهم يقرّون بأنّ الله الخالقُ الرازقُ المدبّر، ومع ذلك يشركون به في العبادة؛ فاعلم أنّ من أقرّ بأنّ الله هو الخالقُ الرازقُ المدبّر يلزمه أن يعبده وحده؛ فالإقرارُ بالربوبيةِ يستلزم توحيدَ الألوهيةِ والعبادة؛ فوحّد الخالقَ العزيزَ العليمَ في العبادةِ كما تفرّد بالخلقِ والتدبير؛ فأفرده بالعبادةِ كما أفردته بالخلق؛ فكيف تعبد مع الخالقِ غيره؟ وكيف تصرف العبادةَ لمن لم يخلق؟ فاعبد الله الخالقَ وحده؛ ولا تشرك به شيئًا من العبادة؛ فمن أقرّ بأنّ الله الخالقُ ثم أشرك في العبادةِ فقد ناقض نفسه؛ فحقّق التوحيدَ الكامل: توحيدَ الربوبيةِ والألوهية؛ فوحّد الخالقَ في عبادتك، وأخلص له الدين."}},{"n":10,"reflection":{"text":"«الذي جعل لكم الأرض مهدا وجعل لكم فيها سبلا لعلكم تهتدون»: الذي جعل لكم الأرضَ فراشًا ممهّدًا، وجعل لكم فيها طرقًا لتهتدوا في أسفاركم؛ ففي هذا تعدادُ نعمِ الله في الأرض؛ فتأمّل نعمةَ الله في تمهيدِ الأرضِ وجعلِ السبل، واشكرها، فمن مهّد لك الأرضَ وجعل فيها سبلًا يستحقّ العبادةَ والشكر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الله في تمهيدِ الأرضِ وجعلِ السبل، وتوحيدُ المنعم."},"action":{"text":"تأمّل نعمَ الله في الأرض: الله الذي جعل لكم الأرضَ مهدًا وفراشًا ممهّدًا ومستقرًّا تعيشون عليها وتستقرّون؛ وجعل لكم فيها سبلًا وطرقًا بين الجبالِ والأوديةِ والبلدان لعلّكم تهتدون بها في أسفاركم إلى مقاصدكم «الذي جعل لكم الأرض مهدا وجعل لكم فيها سبلا لعلكم تهتدون»؛ ففي هذا تعدادُ نعمِ الله في تمهيدِ الأرضِ وجعلِ السبلِ فيها؛ فمن مهّد لك الأرضَ لتستقرّ عليها؟ ومن جعل فيها الطرقَ لتهتديَ في أسفارك؟ إنه الله؛ فتأمّل نعمةَ الله في تمهيدِ الأرضِ وتيسيرِ العيشِ عليها، وجعلِ السبلِ للاهتداء؛ واشكر الله على هذه النعم؛ فمن مهّد الأرضَ وجعل فيها السبلَ يستحقّ العبادةَ والشكرَ والتوحيد؛ فاستعمل نعمَ الله في طاعته؛ فمن تأمّل نعمَ الله في الأرضِ شكرها ووحّد المنعم؛ فاجعل تأمّلك في نعمِ الله سبيلًا لشكره وعبادته؛ فهو الذي مهّد لك الأرضَ وجعل فيها السبل؛ فاشكره ووحّده."}},{"n":11,"reflection":{"text":"«والذي نزل من السماء ماء بقدر فأنشرنا به بلدة ميتا كذلك تخرجون»، والذي نزّل من السماءِ ماءً بقدرٍ معلوم، فأحيينا به بلدةً ميتة، كذلك تُخرَجون من قبوركم؛ ففي هذا نعمةُ الماءِ والاستدلالُ بإحياءِ الأرضِ على البعث؛ فتأمّل إحياءَ الأرضِ بالماء، فمن أحياها يحييك بعد موتك، فأيقن بالبعثِ واشكر نعمةَ الماء، فالقادرُ على إحياءِ الأرضِ قادرٌ على بعثك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الماء، واليقينُ بالبعثِ استدلالًا بإحياءِ الأرض."},"action":{"text":"تأمّل نعمةَ الماءِ ودلالتَه على البعث: والذي نزّل من السماءِ ماءً، المطر، بقدرٍ معلومٍ لا يزيد فيغرق ولا ينقص فيعطش، بحكمته؛ فأنشرنا وأحيينا به بلدةً ميتةً هامدةً لا نباتَ فيها فأخرجنا نباتها؛ كذلك، كإحياءِ الأرضِ الميتة، تُخرَجون من قبوركم أحياءً يومَ البعث «والذي نزل من السماء ماء بقدر فأنشرنا به بلدة ميتا كذلك تخرجون»؛ ففي هذا نعمةُ إنزالِ الماءِ بقدر، والاستدلالُ بإحياءِ الأرضِ الميتةِ على البعث؛ فتأمّل نعمةَ الله في إنزالِ الماءِ بقدرٍ يصلح به العبادُ والبلاد؛ واشكر هذه النعمةَ العظيمة؛ وتأمّل إحياءَ الأرضِ الميتةِ بالماءِ فتخضرّ وتنبت؛ فمن أحيا الأرضَ الميتةَ قادرٌ على أن يحييك بعد موتك ويخرجك من قبرك؛ فالقادرُ على إحياءِ الأرضِ قادرٌ على البعث؛ فأيقن بالبعثِ الذي هو حق؛ واستعدّ له بالإيمانِ والعملِ الصالح؛ فاجعل من نعمةِ الماءِ وإحياءِ الأرضِ دليلًا على شكرِ الله واليقينِ بالبعث؛ فمن تأمّلهما شكر ووحّد وأيقن بالبعث."}},{"n":12,"reflection":{"text":"«والذي خلق الأزواج كلها وجعل لكم من الفلك والأنعام ما تركبون»، والذي خلق الأصنافَ كلَّها من كلِّ شيء، وجعل لكم من السفنِ والأنعامِ ما تركبون؛ ففي هذا تعدادُ نعمةِ خلقِ الأزواجِ وتسخيرِ المراكب؛ فتأمّل نعمةَ الله في خلقِ الأصنافِ وتسخيرِ ما تركب، واشكرها، فمن خلق الأزواجَ وسخّر المراكبَ يستحقّ العبادةَ والشكر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ خلقِ الأزواجِ وتسخيرِ المراكب، وتوحيدُ الخالق."},"action":{"text":"تأمّل نعمَ الله في الخلقِ والتسخير: والذي خلق الأزواجَ كلَّها، أي الأصنافَ والأنواعَ كلَّها من الحيوانِ والنباتِ وغيرها، أو الذكرَ والأنثى من كلِّ شيء؛ وجعل لكم من الفلكِ، السفن، والأنعامِ، الإبلِ ونحوها، ما تركبون في البرِّ والبحر «والذي خلق الأزواج كلها وجعل لكم من الفلك والأنعام ما تركبون»؛ ففي هذا تعدادُ نعمةِ خلقِ الأزواجِ والأصناف، وتسخيرِ المراكبِ من الفلكِ والأنعام؛ فمن خلق هذه الأصنافَ المتنوّعة؟ ومن سخّر لك السفنَ والأنعامَ لتركبها وتحمل عليها؟ إنه الله؛ فتأمّل نعمةَ الله في خلقِ الأصنافِ المتنوّعة، وتسخيرِ ما تركبه في البرِّ والبحر؛ واشكر هذه النعم؛ فمن خلق الأزواجَ وسخّر المراكبَ يستحقّ العبادةَ والشكرَ والتوحيد؛ سبحان الذي سخّر لنا هذا وما كنّا له مقرنين؛ فاستعمل هذه النعمَ في طاعةِ الله؛ فمن تأمّل نعمَ الله شكرها ووحّد المنعم؛ فاشكر الله على خلقِ الأزواجِ وتسخيرِ المراكب."}},{"n":13,"reflection":{"text":"«لتستووا على ظهوره ثم تذكروا نعمة ربكم إذا استويتم عليه وتقولوا سبحان الذي سخر لنا هذا وما كنا له مقرنين»: لتستقرّوا على ظهورِ المراكب، ثم تذكروا نعمةَ ربّكم إذا استويتم عليها، وتقولوا: سبحان الذي سخّر لنا هذا وما كنّا له مطيقين؛ ففي هذا تعليمُ ذكرِ النعمةِ والتسبيحِ عند الركوب؛ فاذكر نعمةَ الله عند ركوبك، وسبّحه، فمن استعمل النعمةَ في ذكرِ الله فقد شكرها، فقل دعاءَ الركوبِ شكرًا لله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"ذكرُ نعمةِ الله والتسبيحُ عند الركوب، شكرًا لها."},"action":{"text":"تأمّل تعليمَ الله لذكرِ النعمةِ عند الركوب: سخّر لكم هذه المراكبَ لتستووا وتستقرّوا على ظهورها؛ ثم تذكروا نعمةَ ربّكم عليكم بهذا التسخيرِ إذا استويتم واستقررتم عليها؛ وتقولوا: سبحان الذي سخّر لنا هذا المركبَ وذلّله، وما كنّا له مقرنين، أي مطيقين ضابطين لولا تسخيرُ الله «لتستووا على ظهوره ثم تذكروا نعمة ربكم إذا استويتم عليه وتقولوا سبحان الذي سخر لنا هذا وما كنا له مقرنين»؛ ففي هذا تعليمُ ذكرِ نعمةِ الله والتسبيحِ عند الركوب؛ فعلّمنا الله أن نذكر نعمته ونسبّحه عند ركوبِ ما سخّره لنا؛ فاذكر نعمةَ الله عليك عند ركوبك دابّتك أو سيّارتك أو سفينتك أو طائرتك؛ وسبّح الله وقل دعاءَ الركوب: سبحان الذي سخّر لنا هذا وما كنّا له مقرنين وإنا إلى ربنا لمنقلبون؛ فكان النبيُّ ﷺ إذا استوى على دابّته كبّر ثلاثًا ثم قال هذا الدعاء؛ فمن استعمل النعمةَ في ذكرِ الله وتسبيحه فقد شكرها؛ فاجعل ركوبك مذكّرًا بنعمةِ الله، مقرونًا بذكره وتسبيحه؛ فبذكرِ النعمةِ عند استعمالها تُشكَر النعمة، وتدوم البركة."}},{"n":14,"reflection":{"text":"«وإنا إلى ربنا لمنقلبون»، وإنا إلى ربّنا لراجعون بعد الموت؛ ففي هذا تذكيرٌ بالرجوعِ إلى الله في دعاءِ الركوب؛ فتذكّر رجوعك إلى الله عند سفرك وركوبك، فكلُّ سفرٍ يذكّرك بالسفرِ الأكبرِ إلى الله، فاستعدّ للرجوعِ إليه، فإنا إلى ربّنا لمنقلبون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تذكّرُ الرجوعِ إلى الله عند السفر، والاستعدادُ للقاء."},"action":{"text":"تأمّل ختامَ دعاءِ الركوب: وإنا إلى ربّنا لمنقلبون وراجعون بعد الموتِ للحسابِ والجزاء «وإنا إلى ربنا لمنقلبون»؛ ففي هذا تذكيرٌ بالرجوعِ إلى الله في دعاءِ الركوب؛ فختم الله دعاءَ الركوبِ بتذكّرِ الرجوعِ إليه؛ فكما نسافر في الدنيا ونركب المراكب، فإنا مسافرون إلى الله راجعون إليه؛ فتذكّر رجوعك إلى الله عند سفرك وركوبك؛ فكلُّ سفرٍ في الدنيا يذكّرك بالسفرِ الأكبرِ إلى الله والدارِ الآخرة؛ فكما تتزوّد لسفرِ الدنيا، تزوّد لسفرِ الآخرة بالتقوى والعملِ الصالح؛ وتزوّدوا فإنّ خيرَ الزادِ التقوى؛ فاستعدّ للرجوعِ إلى الله والانقلابِ إليه؛ فإليه المصير؛ فمن تذكّر رجوعه إلى الله استعدّ له بالعملِ الصالح؛ فاجعل من ركوبك وسفرك مذكّرًا برجوعك إلى الله؛ فقل: وإنا إلى ربنا لمنقلبون؛ متذكّرًا الآخرةَ والحساب؛ فبتذكّرِ الرجوعِ إلى الله يستقيم العملُ ويحسن الاستعداد؛ فتزوّد لسفرك الأكبرِ إلى ربك."}}]},{"title":"دعوى البناتِ لله وذمُّها، وعبادةُ الملائكةِ والقولُ على الغيبِ بلا علم","range":[15,20],"theme":"جعلُ المشركين لله جزءًا من عباده وأنّ الإنسانَ كفور، وإنكارُ نسبةِ البناتِ إلى الله مع كراهتهم لها حتى يسودّ وجه أحدهم، وجعلُهم الملائكةَ إناثًا بلا علمٍ وأنّ شهادتهم ستُكتَب، واحتجاجُهم بالقدرِ على عبادةِ الملائكةِ وأنه ظنٌّ بلا علم","verses":[{"n":15,"reflection":{"text":"«وجعلوا له من عباده جزءا إن الإنسان لكفور مبين»، وجعل المشركون لله جزءًا من عباده (بزعمهم أنّ الملائكةَ بناتُ الله)، إنّ الإنسانَ لكفورٌ بيّنُ الكفران؛ ففي هذا ذمُّ نسبةِ الولدِ إلى الله وكفرانِ الإنسان؛ فنزّه الله عن الولدِ والجزء، واحذر كفرانَ النعمة، فمن نسب لله ولدًا فقد كفر، فوحّد الله ونزّهه واشكر نعمه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله عن الولد، والحذرُ من كفرانِ الإنسان."},"action":{"text":"تأمّل ذمَّ الله للمشركين: وجعل المشركون لله جزءًا وبعضًا من عباده، بزعمهم أنّ الملائكةَ بناتُ الله، والولدُ جزءٌ من والده؛ إنّ الإنسانَ لكفورٌ بيّنُ الكفران، ظاهرُ الجحودِ لنعمِ الله «وجعلوا له من عباده جزءا إن الإنسان لكفور مبين»؛ ففي هذا ذمُّ نسبةِ الولدِ والجزءِ إلى الله، وبيانُ كفرانِ الإنسانِ الظاهر؛ فنسبتهم الولدَ إلى الله من أعظمِ الكفرانِ والجحود؛ فنزّه الله عن الولدِ والجزءِ والصاحبةِ والشريك؛ فهو الأحدُ الصمدُ الذي لم يلد ولم يولد؛ فكيف يكون له جزءٌ أو ولدٌ من عباده؟ فالكلُّ عبيدٌ له مخلوقون؛ إن كلُّ من في السماواتِ والأرضِ إلا آتي الرحمنِ عبدًا؛ فنزّه الله في قلبك عن كلِّ ما لا يليق به؛ واحذر كفرانَ نعمِ الله وجحودها؛ فالإنسانُ لكفورٌ مبين إن لم يعصمه الله؛ فاشكر نعمَ الله ولا تكفرها؛ ووحّد الله ونزّهه عن الولدِ والجزء؛ فمن وحّد الله ونزّهه وشكر نعمه فقد أدّى حقّه؛ فاجعل قلبك موحّدًا منزّهًا شاكرًا، لا مشركًا كفورًا."}},{"n":16,"reflection":{"text":"«أم اتخذ مما يخلق بنات وأصفاكم بالبنين»: أاتّخذ الله لنفسه البناتِ مما يخلق، وخصّكم بالبنين؟ ففي هذا إنكارُ نسبةِ البناتِ إلى الله؛ فتأمّل تناقضَ المشركين: ينسبون لله ما يكرهون لأنفسهم، فنزّه الله عن الولدِ ذكرًا كان أو أنثى، ولا تنسب إليه ما لا يليق بجلاله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله عن الولد، والحذرُ من نسبةِ ما لا يليق به."},"action":{"text":"تأمّل إنكارَ الله على المشركين: أاتّخذ الله لنفسه من مخلوقاته البناتِ، بزعمهم أنّ الملائكةَ بناتُ الله، وخصّكم واصطفاكم بالبنين الذين تحبّونهم؟ «أم اتخذ مما يخلق بنات وأصفاكم بالبنين»؛ ففي هذا إنكارٌ شديدٌ على نسبةِ البناتِ إلى الله؛ فانظر إلى تناقضِ المشركين وسفهِ عقولهم: ينسبون إلى الله البناتِ اللاتي يكرهونها لأنفسهم، ويجعلون لأنفسهم البنين الذين يحبّونهم؛ فينسبون إلى الله ما يأنفون منه ويكرهونه؛ ألكم الذكرُ وله الأنثى تلك إذًا قسمةٌ ضيزى؛ فنزّه الله عن الولدِ أصلًا، ذكرًا كان أو أنثى؛ فهو الغنيُّ المنزّهُ عن الولدِ والحاجةِ إليه؛ فلا تنسب إلى الله ما لا يليق بجلالِه وكماله؛ فهو المنزّهُ عن مشابهةِ خلقه؛ ليس كمثله شيء؛ فاعرف ربك بأسمائه الحسنى وصفاته العلى؛ ونزّهه عن كلِّ نقصٍ وعيبٍ وولد؛ فمن عرف عظمةَ الله نزّهه عن كلِّ ما لا يليق به؛ فعظّم ربك، ونزّهه، وأخلص له التوحيد."}},{"n":17,"reflection":{"text":"«وإذا بشر أحدهم بما ضرب للرحمن مثلا ظل وجهه مسودا وهو كظيم»، وإذا بُشِّر أحدهم بالأنثى التي نسبها إلى الرحمن، اسودّ وجهه من الغمِّ وامتلأ حزنًا؛ ففي هذا فضحُ تناقضِ المشركين؛ فتأمّل قبحَ من ينسب إلى الله ما يسوءه ويكرهه، فنزّه الله عمّا لا يرضاه لنفسه، ولا تنسب إليه ما تكرهه، فالمشركون يكرهون لأنفسهم ما ينسبونه لله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله عمّا يُكرَه، وإدراكُ تناقضِ من ينسب إليه ما يكرهه."},"action":{"text":"تأمّل فضحَ الله لتناقضِ المشركين: وإذا بُشِّر أحدهم بالأنثى، التي ضربها ونسبها للرحمن، أي البنت، ظلّ وجهه مسودًّا من الغمِّ والكآبة، وهو كظيمٌ ممتلئٌ حزنًا وغيظًا يكظمه؛ فكيف ينسبون إلى الله ما يسوءهم ويسودّ وجوههم إذا بُشِّروا به؟ «وإذا بشر أحدهم بما ضرب للرحمن مثلا ظل وجهه مسودا وهو كظيم»؛ ففي هذا فضحُ تناقضِ المشركين وقبحِ فعلهم؛ فهم يكرهون البناتِ أشدَّ الكراهية، حتى يسودّ وجه أحدهم إذا بُشِّر بها؛ ومع ذلك ينسبونها إلى الله؛ فتأمّل قبحَ من ينسب إلى الله ما يسوءه هو ويكرهه؛ فأيُّ سفهٍ أعظمُ من هذا؟ فنزّه الله عمّا لا يرضاه المشركون لأنفسهم؛ ولا تنسب إلى الله ما تكرهه أنت؛ فالله منزّهٌ عن الولدِ والنقصِ كلِّه؛ فاعرف عظمةَ الله وكماله؛ ونزّهه عن كلِّ نقصٍ وعيب؛ فمن عرف الله عظّمه ونزّهه؛ فلا تكن كهؤلاء المتناقضين الذين ينسبون لله ما يكرهون؛ بل نزّه الله عن كلِّ ما لا يليق به؛ فعظّمه، ونزّهه، ووحّده."}},{"n":18,"reflection":{"text":"«أومن ينشأ في الحلية وهو في الخصام غير مبين»: أينسبون إلى الله من يُربّى في الزينةِ (الأنثى) وهو في الجدالِ عاجزٌ عن البيان؟ ففي هذا بيانُ سفهِ نسبتهم الناقصَ إلى الله؛ فتأمّل سخفَ من ينسب إلى الله ما يعدّه ناقصًا، فنزّه الله عن كلِّ نقص، ولا تحكم على الله بأحكامك الجاهلة، بل نزّهه عن كلِّ ما لا يليق به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله عن كلِّ نقص، وتركُ الحكمِ عليه بالجهل."},"action":{"text":"تأمّل تمامَ فضحِ تناقضهم: أينسبون إلى الله من يُنشَّأ ويُربّى في الحليةِ والزينة، أي الأنثى التي شأنها التزيّن، وهو في الخصامِ والجدالِ غيرُ مبينٍ ولا قادرٍ على إظهارِ حجّته لضعفها؟ فينسبون إلى الله من يعدّونه ناقصًا في زعمهم «أومن ينشأ في الحلية وهو في الخصام غير مبين»؛ ففي هذا بيانُ سفهِ المشركين في نسبتهم إلى الله ما يعدّونه ناقصًا؛ فهم يستنقصون الأنثى، ويعدّونها ضعيفةً في الحجّةِ والبيان، ثم ينسبونها إلى الله؛ فتأمّل سخفَ من ينسب إلى الله ما يعدّه هو ناقصًا وضعيفًا؛ فنزّه الله عن كلِّ نقصٍ وضعف؛ فهو الكاملُ في ذاته وصفاته؛ ولا تحكم على الله بأحكامك الجاهلةِ والباطلة؛ فالله منزّهٌ عن الولدِ والنقصِ كلِّه؛ فاعرف الله بكماله المطلق؛ ونزّهه عن كلِّ ما لا يليق به من النقصِ والعيب؛ فمن عرف كمالَ الله نزّهه عن كلِّ نقص؛ فلا تنسب إلى الله ما لا يليق بجلاله؛ بل أثبت له الكمالَ المطلق، ونزّهه عن كلِّ نقص؛ فعظّم ربك، ونزّهه، ووحّده."}},{"n":19,"reflection":{"text":"«وجعلوا الملائكة الذين هم عباد الرحمن إناثا أشهدوا خلقهم ستكتب شهادتهم ويسألون»، وجعلوا الملائكةَ الذين هم عبادُ الرحمنِ إناثًا، أحضروا خلقهم فعلموا أنهم إناث؟ ستُكتَب شهادتهم الباطلةُ ويُسألون عنها؛ ففي هذا ذمُّ القولِ على الغيبِ بلا علم؛ فاحذر القولَ على الله وفي الغيبِ بلا علم، فإنه مكتوبٌ مسؤولٌ عنه، فلا تقل إلا ما علمت، فالقولُ بلا علمٍ يُكتَب ويُحاسَب عليه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من القولِ على الغيبِ بلا علم، فإنه مكتوبٌ مسؤولٌ عنه."},"action":{"text":"تأمّل ذمَّ الله لقولهم على الغيبِ بلا علم: وجعلوا الملائكةَ الذين هم عبادُ الرحمنِ المكرَّمون إناثًا؛ أشهدوا وحضروا خلقهم فعلموا أنهم إناث؟ لم يشهدوا خلقهم؛ ستُكتَب شهادتهم الباطلةُ عليهم، ويُسألون عنها ويُحاسَبون يومَ القيامة «وجعلوا الملائكة الذين هم عباد الرحمن إناثا أشهدوا خلقهم ستكتب شهادتهم ويسألون»؛ ففي هذا ذمُّ القولِ على الغيبِ بلا علم، وأنه مكتوبٌ مسؤولٌ عنه؛ فوصفوا الملائكةَ بالأنوثةِ بلا علمٍ ولا مشاهدة؛ فاحذر القولَ على الله وفي الغيبِ بلا علم؛ فالقولُ على الله بلا علمٍ من أعظمِ المحرّمات؛ ولا تقف ما ليس لك به علم؛ فلا تقل في الغيبِ ولا في الدينِ إلا ما علمت بدليل؛ واعلم أنّ كلَّ قولٍ تقوله مكتوبٌ عليك، مسؤولٌ عنه؛ ما يلفظ من قولٍ إلا لديه رقيبٌ عتيد؛ فستُكتَب أقوالك وتُسأل عنها؛ فراقب لسانك، ولا تقل إلا حقًّا وعلمًا؛ فلا تخض فيما لا علمَ لك به؛ فمن قال في الغيبِ أو الدينِ بلا علمٍ فقد افترى؛ فالزم العلمَ والدليل؛ واحذر القولَ بلا علم؛ فإنه مكتوبٌ مسؤولٌ عنه يومَ القيامة."}},{"n":20,"reflection":{"text":"«وقالوا لو شاء الرحمن ما عبدناهم ما لهم بذلك من علم إن هم إلا يخرصون»، وقالوا: لو شاء الرحمنُ ما عبدنا الملائكة، ما لهم بذلك من علمٍ، ما هم إلا يكذبون ويظنّون؛ ففي هذا ردُّ احتجاجهم بالقدرِ على الشرك؛ فاحذر الاحتجاجَ بالقدرِ على المعاصي، فإنه حجّةٌ باطلةٌ بلا علم، فأنت مأمورٌ منهيٌّ مخيَّر، فلا تعلّق شركك أو معصيتك على مشيئةِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ الاحتجاجِ بالقدرِ على الشركِ والمعصية."},"action":{"text":"تأمّل ردَّ الله على احتجاجهم بالقدر: وقالوا: لو شاء الرحمنُ ما عبدنا الملائكةَ والأصنام؛ فاحتجّوا بمشيئةِ الله على شركهم؛ فردّ الله عليهم: ما لهم بذلك من علمٍ يصحّح احتجاجهم؛ إن هم إلا يخرصون ويكذبون ويظنّون الظنون «وقالوا لو شاء الرحمن ما عبدناهم ما لهم بذلك من علم إن هم إلا يخرصون»؛ ففي هذا ردُّ احتجاجِ المشركين بالقدرِ على شركهم؛ فاحتجّوا بأنّ الله لو شاء لمنعهم؛ وهذه حجّةٌ باطلةٌ داحضة؛ فإنّ الله وإن كان بمشيئتِه يقع كلُّ شيء، فقد أمر العبادَ ونهاهم وأقام عليهم الحجّةَ بالرسل، وأعطاهم العقلَ والاختيار؛ فاحتجاجهم بالقدرِ على الشركِ باطلٌ؛ فاحذر الاحتجاجَ بالقدرِ على المعاصي والشرك؛ فإنه حجّةٌ باطلةٌ لا علمَ لأصحابها بها؛ فلو صحّ الاحتجاجُ بالقدرِ لما عُذّب أحد؛ سيقول الذين أشركوا لو شاء الله ما أشركنا... قل هل عندكم من علمٍ فتخرجوه لنا إن تتّبعون إلا الظن؛ فأنت مأمورٌ منهيٌّ مخيَّرٌ مكلَّف؛ فلا تعلّق شركك أو معصيتك على مشيئةِ الله؛ بل آمن بالقدر، ولا تحتجّ به على المعاصي؛ فالقدرُ يُؤمَن به ولا يُحتَجّ به على الذنوب؛ فاعمل، ولا تتّكل على القدر."}}]},{"title":"التقليدُ الأعمى للآباءِ وردُّه، وعاقبةُ المكذّبين المعاندين","range":[21,25],"theme":"نفيُ أيِّ مستندٍ للمشركين من كتابٍ في شركهم، وأنّ مستندهم تقليدُ الآباءِ الأعمى، وأنّ هذه حجّةُ المترفين المكذّبين في كلِّ قريةٍ أُرسِل إليها نذير، وأنهم يردّون الحقَّ الأهدى تعصّبًا للتقليد، فكانت عاقبةُ المكذّبين الانتقامَ والهلاك","verses":[{"n":21,"reflection":{"text":"«أم آتيناهم كتابا من قبله فهم به مستمسكون»: أآتيناهم كتابًا من قبلِ القرآنِ يأمرهم بالشركِ فهم به متمسّكون؟ ففي هذا نفيُ أيِّ مستندٍ للمشركين في شركهم؛ فاعلم أنّ الشركَ لا مستندَ له من كتابٍ ولا وحي، فلا تتّبع في دينك إلا ما جاء به الوحي، فمن لا دليلَ عنده من الوحي فدعواه باطلة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ ما جاء به الوحي، وإدراكُ أنّ الشركَ لا مستندَ له."},"action":{"text":"تأمّل نفيَ الله لأيِّ مستندٍ للمشركين: أم آتينا هؤلاء المشركين كتابًا من قبلِ القرآنِ يأمرهم بالشركِ ويأذن لهم به، فهم به مستمسكون ومحتجّون؟ لم يؤتهم الله كتابًا كذلك «أم آتيناهم كتابا من قبله فهم به مستمسكون»؛ ففي هذا نفيُ أيِّ مستندٍ للمشركين في شركهم من كتابٍ أو وحي؛ فليس عندهم كتابٌ من الله يأمرهم بالشرك؛ فشركهم لا مستندَ له إلا الظنَّ والهوى والتقليد؛ فاعلم أنّ الشركَ لا مستندَ له من كتابٍ ولا وحيٍ ولا برهان؛ فما أنزل الله بالشركِ من سلطان؛ فكلُّ ما جاءت به الرسلُ والكتبُ هو التوحيد؛ فلا تتّبع في دينك إلا ما جاء به الوحيُ الصحيح؛ فمن لا دليلَ عنده من الوحيِ على قوله ومعتقده فدعواه باطلةٌ مردودة؛ قل هاتوا برهانكم إن كنتم صادقين؛ فاجعل بناءَ عقيدتك ودينك على الوحي، لا على الظنِّ والهوى والتقليد؛ فمن بنى دينه على الوحيِ ثبت واهتدى، ومن بناه على الظنِّ والهوى ضلّ؛ فالزم ما جاء به الوحي؛ واحذر الشركَ الذي لا مستندَ له."}},{"n":22,"reflection":{"text":"«بل قالوا إنا وجدنا آباءنا على أمة وإنا على آثارهم مهتدون»: بل قالوا: إنا وجدنا آباءنا على دينٍ وطريقة، وإنا على آثارهم مهتدون؛ ففي هذا بيانُ أنّ مستندهم التقليدُ الأعمى للآباء؛ فاحذر التقليدَ الأعمى في الدينِ بلا دليل، فليس اتّباعُ الآباءِ حجّةً على الحقّ، بل زِن ما عليه آباؤك بميزانِ الوحي، فالتقليدُ الأعمى سببُ الضلال.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من التقليدِ الأعمى للآباء، ووزنُ ما عليهم بميزانِ الوحي."},"action":{"text":"تأمّل بيانَ مستندِ المشركين الحقيقي: بل قالوا معتذرين عن شركهم: إنا وجدنا آباءنا على أمّةٍ ودينٍ وطريقة، وإنا على آثارهم وطريقتهم مهتدون، نقتدي بهم «بل قالوا إنا وجدنا آباءنا على أمة وإنا على آثارهم مهتدون»؛ ففي هذا بيانُ أنّ مستندهم في الشركِ ليس دليلًا ولا برهانًا، بل التقليدُ الأعمى للآباء؛ فاعتمدوا على تقليدِ آبائهم لا على الحجّةِ والدليل؛ فاحذر التقليدَ الأعمى في الدينِ والعقيدةِ بلا دليلٍ ولا برهان؛ فليس اتّباعُ الآباءِ والأجدادِ حجّةً على الحقّ؛ أولو كان آباؤهم لا يعقلون شيئًا ولا يهتدون؛ فزِن ما وجدت عليه آباءك ومجتمعك بميزانِ الوحيِ والدليل؛ فما وافق الحقَّ قبلته ولو خالف آباءك، وما خالفه رددته ولو كان عليه آباؤك؛ فلا تجعل تقليدَ الآباءِ ميزانًا للحقِّ والباطل؛ بل اجعل الميزانَ الوحيَ والدليل؛ فالتقليدُ الأعمى للآباءِ من غيرِ نظرٍ في الدليلِ سببُ الضلالِ والهلاك؛ فكم من ضالٍّ ضلّ بتقليدِ آبائه؛ فاتّبع الحقَّ بدليله، ولا تقلّد الآباءَ على الباطل؛ فالحقُّ أحقُّ أن يُتّبَع من تقليدِ الآباء."}},{"n":23,"reflection":{"text":"«وكذلك ما أرسلنا من قبلك في قرية من نذير إلا قال مترفوها إنا وجدنا آباءنا على أمة وإنا على آثارهم مقتدون»، وكذلك ما أرسلنا في قريةٍ من نذيرٍ قبلك إلا قال مترفوها: إنا وجدنا آباءنا على دينٍ وإنا على آثارهم مقتدون؛ ففي هذا أنّ التقليدَ الأعمى حجّةُ المكذّبين في كلِّ زمان؛ فاحذر أن تكون من المقلّدين المكذّبين، فحجّةُ التقليدِ حجّةُ كلِّ مكذّب، فاتّبع الحقَّ بدليله لا بتقليدِ الآباء، فالمترفون أكثرُ الناسِ تعلّقًا بالتقليد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من التقليدِ الأعمى، فهو حجّةُ المكذّبين في كلِّ زمان."},"action":{"text":"تأمّل أنّ التقليدَ حجّةُ المكذّبين في كلِّ زمان: وكذلك، كحالِ مشركي قومك، ما أرسلنا من قبلك في قريةٍ من نذيرٍ يحذّرهم، إلا قال مترفوها، المنعَّمون المتكبّرون منهم: إنا وجدنا آباءنا على أمّةٍ ودينٍ وطريقة، وإنا على آثارهم مقتدون مقلّدون «وكذلك ما أرسلنا من قبلك في قرية من نذير إلا قال مترفوها إنا وجدنا آباءنا على أمة وإنا على آثارهم مقتدون»؛ ففي هذا بيانُ أنّ التقليدَ الأعمى للآباءِ حجّةُ المكذّبين في كلِّ زمانٍ ومكان؛ فما من نذيرٍ إلا واجهه المترفون بهذه الحجّةِ الباطلة: تقليدِ الآباء؛ فاحذر أن تكون من المقلّدين المكذّبين الذين يردّون الحقَّ بحجّةِ تقليدِ الآباء؛ فحجّةُ التقليدِ حجّةُ كلِّ مكذّبٍ معاند؛ ولاحظ أنّ المترفين، المنعَّمين المتكبّرين، هم أكثرُ الناسِ تعلّقًا بالتقليدِ وردًّا للحق؛ لأنّ الحقَّ يهدّد ترفهم وكبرهم؛ فاتّبع الحقَّ بدليله وبرهانه، لا بتقليدِ الآباءِ والأجداد؛ فلا تجعل ما عليه آباؤك ومجتمعك حجّةً على الحق؛ بل زِنه بميزانِ الوحي؛ فمن اتّبع الحقَّ بدليله نجا، ومن قلّد الآباءَ على الباطلِ هلك؛ فتحرّر من ربقةِ التقليدِ الأعمى، واتّبع الحقَّ حيث كان."}},{"n":24,"reflection":{"text":"«قال أولو جئتكم بأهدى مما وجدتم عليه آباءكم قالوا إنا بما أرسلتم به كافرون»: قال النذير: أتتّبعون آباءكم ولو جئتكم بأهدى مما وجدتم عليه آباءكم؟ قالوا: إنا بما أُرسِلتم به كافرون؛ ففي هذا عنادُ المقلّدين ورفضهم الحقَّ ولو كان أهدى؛ فاحذر أن ترفض الحقَّ الأهدى تمسّكًا بالتقليد، بل اقبل الأهدى والأصوب، فمن رفض الحقَّ الأهدى تعصّبًا للتقليد فهو معاند.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ الحقِّ الأهدى، وتركُ التعصّبِ للتقليد."},"action":{"text":"تأمّل عنادَ المقلّدين: قال النذيرُ لهم محتجًّا: أتتّبعون آباءكم ولو جئتكم بدينٍ أهدى وأصوبَ مما وجدتم عليه آباءكم؟ أفلا تتركون تقليدهم لما هو أهدى؟ فأجابوا بعنادٍ وإصرار: إنا بما أُرسِلتم به من الحقِّ كافرون جاحدون «قال أولو جئتكم بأهدى مما وجدتم عليه آباءكم قالوا إنا بما أرسلتم به كافرون»؛ ففي هذا بيانُ عنادِ المقلّدين ورفضهم الحقَّ ولو كان أهدى وأصوبَ من طريقةِ آبائهم؛ فتمسّكوا بالتقليدِ الأعمى حتى ردّوا الحقَّ الأهدى؛ فاحذر أن ترفض الحقَّ الأهدى والأصوبَ تمسّكًا بالتقليدِ والعادةِ والموروث؛ فالعاقلُ يتّبع الأهدى والأصوبَ ولو خالف ما عليه آباؤه؛ فإذا تبيّن لك أنّ الحقَّ أهدى مما أنت عليه فاتّبعه؛ ولا تردّه تعصّبًا للتقليدِ والعادة؛ فمن رفض الحقَّ الأهدى تعصّبًا للتقليدِ فهو معاندٌ مكابر؛ الذين يستمعون القولَ فيتّبعون أحسنه أولئك الذين هداهم الله؛ فاتّبع أحسنَ القولِ وأهداه؛ واقبل الحقَّ الأصوبَ ولو خالف موروثك؛ فمن قبل الأهدى اهتدى، ومن رفضه تعصّبًا ضلّ؛ فكن مع الحقِّ الأهدى، لا مع التقليدِ الأعمى."}},{"n":25,"reflection":{"text":"«فانتقمنا منهم فانظر كيف كان عاقبة المكذبين»: فانتقمنا من المكذّبين المعاندين، فانظر كيف كانت عاقبتهم من الهلاك؛ ففي هذا وعيدُ المكذّبين وعبرةُ عاقبتهم؛ فاعتبر بعاقبةِ المكذّبين المعاندين، واحذر أن تسلك سبيلهم، فمن كذّب الحقَّ وعاند أهلكه الله، فاتّبع الحقَّ لتنجو من عاقبتهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بعاقبةِ المكذّبين المعاندين، واتّباعُ الحقِّ للنجاة."},"action":{"text":"تأمّل عاقبةَ المكذّبين المعاندين: فانتقمنا من المكذّبين المعاندين الذين ردّوا الحقَّ تعصّبًا للتقليد، فأهلكناهم؛ فانظر يا محمدُ ويا أيها الإنسان، كيف كانت عاقبةُ المكذّبين من الهلاكِ والدمار «فانتقمنا منهم فانظر كيف كان عاقبة المكذبين»؛ ففي هذا وعيدُ المكذّبين المعاندين، والدعوةُ للاعتبارِ بعاقبتهم؛ فمن كذّب الحقَّ وعاند وأصرّ انتقم الله منه وأهلكه؛ فاعتبر بعاقبةِ المكذّبين المعاندين للحق؛ واحذر أن تسلك سبيلهم في التكذيبِ والعنادِ والتقليدِ الأعمى؛ فمن كذّب الحقَّ وعاند أهلكه الله كما أهلكهم؛ فسِر في الأرضِ وانظر كيف كان عاقبةُ المكذّبين؛ فاجعل من مصارعهم عبرةً تحملك على الإيمانِ واتّباعِ الحق؛ واتّبع الحقَّ الذي جاءت به الرسلُ لتنجو من عاقبتهم؛ فمن اتّبع الحقَّ نجا، ومن كذّبه وعاند هلك؛ فاختر لنفسك سبيلَ الناجين المتّبعين للحق، لا سبيلَ المكذّبين المعاندين الهالكين؛ فالعاقبةُ للمتّقين، والهلاكُ للمكذّبين."}}]},{"title":"براءةُ إبراهيمَ من الشرك وكلمةُ التوحيدِ الباقية، وعنادُ المكذّبين","range":[26,30],"theme":"إعلانُ إبراهيمَ البراءةَ مما يعبد قومه إلا الذي فطره، وجعلُ الله كلمةَ التوحيدِ باقيةً في ذريّته، وأنّ الله متّع المشركين وآباءهم حتى جاءهم الحقُّ ورسولٌ مبين، ولمّا جاءهم الحقُّ قالوا هذا سحرٌ وإنا به كافرون","verses":[{"n":26,"reflection":{"text":"«وإذ قال إبراهيم لأبيه وقومه إنني براء مما تعبدون»، واذكر إذ قال إبراهيمُ لأبيه وقومه: إنني بريءٌ مما تعبدون من دونِ الله؛ ففي هذا البراءةُ من الشركِ وأهله؛ فتبرّأ من الشركِ وكلِّ معبودٍ سوى الله، فالبراءةُ من الشركِ ركنُ التوحيد، فأعلن براءتك من عبادةِ غيرِ الله كما أعلن إبراهيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"البراءةُ من الشركِ وكلِّ معبودٍ سوى الله، فهي ركنُ التوحيد."},"action":{"text":"تأمّل براءةَ إبراهيمَ من الشرك: واذكر إذ قال إبراهيمُ خليلُ الرحمنِ لأبيه وقومه معلنًا براءته: إنني براءٌ وبريءٌ مما تعبدون من دونِ الله من الأصنامِ والأنداد «وإذ قال إبراهيم لأبيه وقومه إنني براء مما تعبدون»؛ ففي هذا إعلانُ البراءةِ من الشركِ وأهله ومعبوداتهم؛ فالتوحيدُ لا يتمّ إلا بالبراءةِ من الشركِ وأهله؛ فتبرّأ من الشركِ وكلِّ معبودٍ سوى الله؛ فالبراءةُ من الشركِ وأهله ركنٌ من أركانِ التوحيد؛ قد كانت لكم أسوةٌ حسنةٌ في إبراهيمَ والذين معه إذ قالوا لقومهم إنا برآءُ منكم ومما تعبدون من دونِ الله كفرنا بكم؛ فأعلن براءتك من عبادةِ غيرِ الله، ومن الشركِ وأهله، كما أعلن إبراهيم؛ فمن يكفر بالطاغوتِ ويؤمن بالله فقد استمسك بالعروةِ الوثقى؛ فحقّق التوحيدَ بأمرين: البراءةِ من الشرك، والإخلاصِ لله؛ فاتبرّأ من كلِّ ما يُعبَد من دونِ الله؛ وأخلص العبادةَ لله وحده؛ فبالبراءةِ من الشركِ والإخلاصِ لله يكمل توحيدك."}},{"n":27,"reflection":{"text":"«إلا الذي فطرني فإنه سيهدين»: إلا الذي خلقني، فإنه سيهديني إلى الحقّ؛ ففي هذا استثناءُ الخالقِ من البراءةِ وتوحيدُه؛ فوحّد الخالقَ الذي فطرك، وثق بهدايته، فمن فطرك يهديك، فاعبد خالقك وحده وارجُ هدايته، فالبراءةُ من كلِّ معبودٍ إلا الخالق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ الخالقِ الذي فطرك، والثقةُ بهدايته."},"action":{"text":"تأمّل تمامَ كلمةِ إبراهيم: إنني براءٌ مما تعبدون إلا الذي فطرني وخلقني، فإنه سيهديني إلى الحقِّ والصراطِ المستقيم «إلا الذي فطرني فإنه سيهدين»؛ ففي هذا استثناءُ الخالقِ من البراءة، وتوحيدُه بالعبادة، والثقةُ بهدايته؛ فتبرّأ إبراهيمُ من كلِّ معبودٍ إلا الخالقَ الذي فطره؛ فوحّد الخالقَ الذي فطرك وخلقك؛ فهو وحده المستحقُّ للعبادة؛ وثق بهداية الله لك؛ فمن فطرك وخلقك هو الذي يهديك ويوفّقك؛ فاعبد خالقك وحده، وارجُ هدايته وتوفيقه؛ فالبراءةُ من كلِّ معبودٍ إلا الخالق؛ فأخلص العبادةَ للخالقِ الفاطر؛ ولا تعبد ما لا يخلق ولا يهدي؛ فمن وحّد خالقه ووثق بهدايته اهتدى؛ فاطلب الهدايةَ من الله الذي فطرك؛ فهو الذي يهديك إلى الحق؛ فاجعل عبادتك ورجاءك وثقتك بالخالقِ الذي فطرك؛ فبتوحيده والثقةِ بهدايته تُنال السعادة."}},{"n":28,"reflection":{"text":"«وجعلها كلمة باقية في عقبه لعلهم يرجعون»، وجعل الله كلمةَ التوحيدِ باقيةً في ذريةِ إبراهيمَ لعلّهم يرجعون إليها؛ ففي هذا بقاءُ كلمةِ التوحيدِ في ذريّةِ إبراهيم؛ فاحرص على توريثِ التوحيدِ لذريّتك، فكلمةُ التوحيدِ ميراثٌ باقٍ، فاجعل التوحيدَ كلمةً باقيةً في أهلك وذريّتك بالتربيةِ عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توريثُ التوحيدِ للذريّة، وجعلُه كلمةً باقيةً فيهم."},"action":{"text":"تأمّل بقاءَ كلمةِ التوحيد: وجعل الله كلمةَ التوحيدِ، لا إله إلا الله، أو البراءةَ من الشركِ والإخلاصَ لله، كلمةً باقيةً في عقبِ إبراهيمَ وذريّته، يتوارثونها جيلًا بعد جيل، لعلّهم يرجعون إليها إذا انحرفوا «وجعلها كلمة باقية في عقبه لعلهم يرجعون»؛ ففي هذا بيانُ بقاءِ كلمةِ التوحيدِ في ذريّةِ إبراهيم؛ فما زال في ذريّته من يوحّد الله ويدعو إليه؛ فاحرص على توريثِ التوحيدِ والدينِ لذريّتك من بعدك؛ فكلمةُ التوحيدِ أعظمُ ميراثٍ تتركه لذريّتك؛ فاجعل التوحيدَ كلمةً باقيةً في أهلك وذريّتك؛ ورّثهم العقيدةَ الصحيحةَ والتوحيدَ الخالص؛ وربِّهم على التوحيدِ والدين؛ فإذا انحرف بعضهم رجع إلى ما ورثه من التوحيد؛ فاعتنِ بتربيةِ ذريّتك على التوحيدِ والدين؛ كما وصّى إبراهيمُ بنيه ويعقوبُ يا بنيّ إنّ الله اصطفى لكم الدينَ فلا تموتنّ إلا وأنتم مسلمون؛ فمن ورّث ذريّته التوحيدَ فقد ترك لهم أعظمَ ميراث؛ فاجعل همّك توريثَ التوحيدِ والدينِ لأهلك وذريّتك."}},{"n":29,"reflection":{"text":"«بل متعت هؤلاء وآباءهم حتى جاءهم الحق ورسول مبين»: بل متّعتُ هؤلاء المشركين وآباءهم بالدنيا حتى جاءهم الحقُّ (القرآن) ورسولٌ مبين؛ ففي هذا بيانُ أنّ الإمهالَ لا يعني الرضا؛ فلا يغرّنك إمهالُ الله للكافرين بالتمتّع، فالإمهالُ ابتلاءٌ لا إكرام، فاغتنم نعمَ الله في طاعته، ولا تغترّ بالتمتّعِ في المعصية.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترارِ بالإمهالِ والتمتّع، واغتنامُ النعمِ في الطاعة."},"action":{"text":"تأمّل بيانَ الله لحكمةِ الإمهال: بل متّعتُ هؤلاء المشركين وآباءهم بالدنيا ونعيمها، ولم أعاجلهم بالعقوبة، حتى جاءهم الحقُّ، القرآنُ، ورسولٌ مبينٌ يوضّح لهم الحق «بل متعت هؤلاء وآباءهم حتى جاءهم الحق ورسول مبين»؛ ففي هذا بيانُ أنّ إمهالَ الله للكافرين وتمتيعهم بالدنيا ليس رضًا عنهم، بل استدراجٌ وإقامةٌ للحجّة؛ فأمهلهم ومتّعهم حتى جاءهم الحقُّ والرسول؛ فلا يغرّنك إمهالُ الله للكافرين وتمتيعهم بالدنيا؛ ولا تظنّ أنّ ذلك إكرامٌ أو رضًا؛ فالإمهالُ والتمتيعُ ابتلاءٌ واستدراج، لا إكرامٌ ولا رضا؛ ولا يحسبنّ الذين كفروا أنما نملي لهم خيرٌ لأنفسهم إنما نملي لهم ليزدادوا إثمًا؛ فاغتنم نعمَ الله وتمتّعك بالدنيا في طاعته وشكره؛ ولا تغترّ بالتمتّعِ في المعصيةِ والإعراض؛ فكم من ممتَّعٍ في الدنيا مستدرَجٍ إلى الهلاك؛ فاجعل نعمَ الله عونًا على طاعته، لا سببًا للغفلةِ والإعراض؛ فمن اغترّ بالتمتّعِ في المعصيةِ خسر، ومن اغتنم النعمَ في الطاعةِ ربح."}},{"n":30,"reflection":{"text":"«ولما جاءهم الحق قالوا هذا سحر وإنا به كافرون»، ولمّا جاءهم الحقُّ (القرآن) قالوا: هذا سحرٌ وإنا به كافرون؛ ففي هذا عنادُ المشركين ورميهم الحقَّ بالسحر؛ فاحذر ردَّ الحقِّ بالتهمِ الباطلة، فرميُ الحقِّ بالسحرِ من عنادِ المكذّبين، فاقبل الحقَّ بإنصاف، ولا تردّه بالتهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ الحقِّ بإنصاف، وتركُ ردِّه بالتهمِ الباطلة."},"action":{"text":"تأمّل عنادَ المشركين عند مجيءِ الحق: ولمّا جاءهم الحقُّ، القرآنُ الواضحُ المعجز، قالوا رادّين له بلا حجّة: هذا سحرٌ، وإنا به كافرون جاحدون «ولما جاءهم الحق قالوا هذا سحر وإنا به كافرون»؛ ففي هذا بيانُ عنادِ المشركين ورميهم الحقَّ بالسحرِ والكفرِ به؛ فلمّا عجزوا عن معارضته رموه بالسحر؛ فاحذر ردَّ الحقِّ بالتهمِ الباطلةِ والأوصافِ الكاذبة؛ فرميُ الحقِّ بالسحرِ أو الكذبِ أو الجنونِ من عنادِ المكذّبين وطريقتهم؛ كذلك ما أتى الذين من قبلهم من رسولٍ إلا قالوا ساحرٌ أو مجنون؛ فاقبل الحقَّ بإنصافٍ وتجرّد؛ ولا تردّه بالتهمِ والأوصافِ الباطلة؛ فمن ردّ الحقَّ بالتهمةِ فقد أعرض عن الإنصاف؛ فاجعل ميزانك في قبولِ الحقِّ الحجّةَ والدليل، لا التهمَ والدعاوى؛ فمن قبل الحقَّ ببرهانه اهتدى، ومن ردّه بالتهمِ الباطلةِ عاند وضلّ؛ فلا تكن من المعاندين الذين يردّون الحقَّ بالتهم؛ بل كن من المنصفين الذين يقبلونه ببرهانه."}}]},{"title":"اعتراضهم على نزولِ القرآن، وقسمةُ الرزق، وهوانُ زخرفِ الدنيا","range":[31,35],"theme":"اعتراضُ المشركين على نزولِ القرآنِ على غيرِ عظيمِ القريتين، وأنّ الله هو الذي يقسم المعيشةَ ويرفع بعضهم فوق بعضٍ درجاتٍ ورحمتُه خيرٌ مما يجمعون، وأنّ الدنيا هيّنةٌ على الله لولا فتنةُ الناسِ لأعطى الكافرين سقوفًا من فضّةٍ وأبوابًا وسررًا وزخرفًا وأنّ كلَّ ذلك متاعُ الدنيا والآخرةُ للمتّقين","verses":[{"n":31,"reflection":{"text":"«وقالوا لولا نزل هذا القرآن على رجل من القريتين عظيم»، وقالوا: هلّا نُزّل القرآنُ على رجلٍ عظيمٍ من مكّةَ أو الطائف (بالجاهِ والمال)؟ ففي هذا اعتراضهم على اختيارِ الله للرسول بمقاييسِ الدنيا؛ فاحذر أن تزن الفضلَ بمقاييسِ الدنيا (الجاهِ والمال)، فالفضلُ بيدِ الله يؤتيه من يشاء، فلا تعترض على قسمةِ الله، والعبرةُ بالتقوى لا بالمال.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ وزنِ الفضلِ بمقاييسِ الدنيا، والتسليمُ لقسمةِ الله."},"action":{"text":"تأمّل اعتراضَ المشركين على اختيارِ الرسول: وقالوا معترضين: هلّا نُزّل هذا القرآنُ على رجلٍ عظيمِ الجاهِ والمالِ من إحدى القريتين، مكّةَ أو الطائف، بدلًا من محمدٍ اليتيمِ الفقير؟ فوزنوا استحقاقَ النبوّةِ بمقاييسِ الدنيا من الجاهِ والمال «وقالوا لولا نزل هذا القرآن على رجل من القريتين عظيم»؛ ففي هذا اعتراضُ المشركين على اختيارِ الله لرسوله بمقاييسِ الدنيا؛ فظنّوا أنّ النبوّةَ تُنال بالجاهِ والمال، لا بالاصطفاءِ والتقوى؛ فاحذر أن تزن الفضلَ والقدرَ بمقاييسِ الدنيا من الجاهِ والمالِ والمنصب؛ فالفضلُ الحقيقيُّ بيدِ الله يؤتيه من يشاء بحكمته؛ الله أعلمُ حيث يجعل رسالته؛ فليست العبرةُ بالجاهِ والمال، بل بالتقوى والاصطفاء؛ إنّ أكرمكم عند الله أتقاكم؛ فلا تعترض على قسمةِ الله وفضلِه واختياره؛ ولا تحتقر أحدًا لفقره، ولا تعظّم أحدًا لماله؛ فالعبرةُ بالتقوى والإيمان، لا بالدنيا وزخرفها؛ فكم من فقيرٍ خيرٌ عند الله من غنيّ؛ فوزن الأمورَ بميزانِ التقوى، لا بميزانِ الدنيا؛ فمن وزن بمقاييسِ الدنيا ضلّ، ومن وزن بميزانِ التقوى اهتدى."},"qadiyya":{"title":"قضيّةُ ميزان الرجال: اعتراضٌ على النبوّة مبناه أنّ العظمة تُقاس بالمال","question":"اعترض المشركون على نزول القرآن على محمّدٍ ﷺ اعتراضًا لم يكن في نظرهم سفهًا، بل كان عندهم وجيهًا: «**لولا نُزِّل هذا القرآنُ على رجلٍ من القريتين عظيم**».\n**والقريتان: مكّةُ والطائف.** **و«عظيم» عندهم: صاحبُ المال والجاه والرياسة.**\nفهم لم يقولوا: القرآنُ باطل. **قالوا: هذا الكلامُ عظيمٌ، فينبغي أن يُنزَّل على عظيم.** ثمّ أعملوا مقياسَهم في الرجال فلم يجدوا محمّدًا ﷺ في الصدارة.\nفالقضيّة: **أين الخلل في اعتراضهم؟ وهل هو في المقدّمة أم في المقياس؟**","background":"ولا يُفهم هذا حتى نعرف حالَهم من الصفر:\n**كانت مكّةُ والطائفُ مركزَي الثقل في الحجاز**، وفيهما ساداتٌ لهم أموالٌ وأتباعٌ وذكرٌ في العرب.\n**وكان النبيُّ ﷺ من أشرف بيوت قريشٍ نسبًا**، **غير أنّه لم يكن من أهل الثروة والرياسة الظاهرة**؛ وقد كان يتيمًا، ورعى الغنم، وعمل بالتجارة لغيره.\n**فاعتراضُهم إذًا مبنيٌّ على مقدّمةٍ صحيحة ومقياسٍ فاسد**: صحّةُ المقدّمة أنّ الأمر العظيم يُعطى لأهله؛ **وفسادُ المقياس أنّهم جعلوا أهليّةَ الرجل مالَه وجاهه.**","what_happened":"**أمّا جوابُ القرآن فجاء في الآية التي تليها، وهو سؤالٌ قاطع**: ﴿أهم يقسمون رحمةَ ربّك﴾.\nقال السعديُّ في معناه: «**أي: أهم الخزّانُ لرحمة الله، وبيدهم تدبيرُها، فيعطون النبوّةَ والرسالةَ من يشاءون، ويمنعونها ممّن يشاءون؟**».\n**ثمّ ساق اللهُ حجّةً عليهم من واقعهم هم**: ﴿نحن قسمنا بينهم معيشتهم في الحياة الدنيا ورفعنا بعضَهم فوق بعضٍ درجات﴾.\n**وحرّر السعديُّ وجهَ الحجّة تحريرًا محكمًا**: «**فإذا كانت معايشُ العباد وأرزاقُهم الدنيويّة بيد الله تعالى، وهو الذي يقسمها بين عباده... فرحمتُه الدينيّة، التي أعلاها النبوّةُ والرسالة، أولى وأحرى أن تكون بيد الله تعالى، فاللهُ أعلمُ حيث يجعل رسالته**».\n**فتأمّل الحجّة**: هم أنفسُهم يُقرّون أنّ الأرزاق قسمةٌ من الله، **وأنّ الفقيرَ لم يُفقَر باختياره ولا الغنيَّ اغتنى بحوله**. **فإذا كان الأدنى بيد الله فالأعلى أولى.**\n**ثمّ التفت السعديُّ إلى المقياس نفسِه فنقضه**، فقال: «**لو عرفوا حقائقَ الرجال، والصفاتِ التي بها يُعرف علوُّ قدر الرجل، وعِظمُ منزلته عند الله وعند خلقه، لعلموا أنّ محمّد بن عبد الله بن عبد المطّلب صلّى الله عليه وسلّم، هو أعظمُ الرجال قدرًا، وأعلاهم فخرًا، وأكملُهم عقلًا، وأغزرُهم علمًا، وأجلُّهم رأيًا**».\n**فأثبت أنّ الخلل ليس في العين، بل في الميزان.**","the_verdict":"**فالحاصلُ أنّ الاعتراض لم يُردّ بأنّه سوءُ أدب، بل نُقض من جهتين:**\n**الأولى: أنّهم تكلّموا فيما ليس إليهم.** ﴿أهم يقسمون رحمةَ ربّك﴾. **فالرسالةُ اصطفاءٌ لا مكافأة**، والاصطفاءُ لمن اصطفى لا لمن اعترض.\n**والثانية، وهي الألطف: أنّ الحجّة أُخذت من إقرارهم هم.** فهم يرون تفاوتَ الأرزاق في الدنيا ولا ينكرون أنّه قسمةُ الله؛ **فقيل لهم: إن سلّمتم في المال فسلّموا في الوحي، فهو أعلى.** **وهذا من أقوى ضروب المحاجّة: أن تُبنى الحجّةُ على ما يُقرّ به الخصمُ لا على ما تدّعيه أنت.**\n**⭐ وأمّا الخللُ في مقياسهم فهو موضعُ العبرة الباقية.** **فإنّهم لم يخطئوا في النظر، بل في أداة النظر.** **نظروا في الرجال بميزانٍ يزن المالَ والجاه، فأعطاهم الميزانُ جوابًا صادقًا عن سؤالٍ خطأ**: من أغنى الرجال؟ لا: من أعظمُهم؟\n**ولهذا عدّد السعديُّ صفاتٍ أخرى للعظمة**: القدرُ، والعقل، والعلم، والرأي. **وهي أوصافٌ لا تُرى في السوق ولا تُعرف من هيئة الرجل، وإنّما تُعرف بالمخالطة والاختبار.**\n**فالميزانُ الفاسدُ يعطي نتائجَ متّسقةً دائمًا؛ ولذلك يصعب اكتشافُ فساده من داخله.** **ولا يُكشف إلّا بأن يُعرض على ميزانٍ آخر، أو بأن يُسأل: ماذا يزن هذا الميزانُ أصلًا؟**","for_you":"**فأمّا الذي تخرج به فثلاثة:**\n**الأوّل: افحصْ ميزانَك في الرجال.** **إذا دخل عليك رجلان، أحدُهما ذو هيئةٍ ومالٍ ومنصب، والآخرُ دونه، فمن تُقدّم في نفسك قبل أن تسمع كلامَهما؟** **فإنّ الجواب الصادقَ عن هذا يكشف لك ميزانَك الحقيقيّ، لا الذي تقوله.** **وهو ميزانُ أهل مكّةَ نفسُه، وقد أخطأ بهم أعظمَ خطأٍ في التاريخ.**\n**والثاني: تعلّمْ أن تحاجَّ من إقرار خصمك.** فحين قيل لهم ﴿نحن قسمنا بينهم معيشتهم﴾ **أُخذوا بما لا ينكرونه**. **فإذا ناظرتَ فابحث أوّلًا عمّا يُسلّمه صاحبُك، ثمّ ابنِ عليه؛ فإنّ الحجّة المبنيّة على ما يُنكره لا تنقله من موضعه.**\n**والثالث: إذا ضاق صدرُك بقسمةٍ في الرزق أو المنزلة فاذكر ﴿أهم يقسمون رحمةَ ربّك﴾.** **فالذي قسم المعايشَ هو الذي قسم ما هو أعلى منها**، وهو أعلمُ بمن يصلح لماذا. **ومن اطمأنّ إلى أنّ القاسمَ حكيمٌ عليمٌ لم يبقَ في قلبه على أحدٍ حسد؛ فإنّ الحسد في حقيقته اعتراضٌ على القسمة لا على المقسوم له.**","grade":"ma'thur","source":"قولُ السعديّ في ﴿أهم يقسمون رحمة ربك﴾ («أي: أهم الخزان لرحمة الله، وبيدهم تدبيرها، فيعطون النبوة والرسالة من يشاءون، ويمنعونها ممن يشاءون؟»)، وتحريرُه لوجه الحجّة («فإذا كانت معايش العباد وأرزاقهم الدنيوية بيد الله تعالى، وهو الذي يقسمها بين عباده... فرحمته الدينية، التي أعلاها النبوة والرسالة، أولى وأحرى أن تكون بيد الله تعالى، فالله أعلم حيث يجعل رسالته»)، ونقضُه لمقياسهم («لو عرفوا حقائق الرجال، والصفات التي بها يعرف علو قدر الرجل، وعظم منزلته عند الله وعند خلقه، لعلموا أن محمد بن عبد الله بن عبد المطلب صلى الله عليه وسلم، هو أعظم الرجال قدرا، وأعلاهم فخرا، وأكملهم عقلا، وأغزرهم علما، وأجلهم رأيا»): كلُّها بنصّها في تفسير السعديّ (٤٣:٣١).","honesty":"وممّا يجب أن يُقال:\n**تفسيرُ «القريتين» بمكّة والطائف مشهورٌ عند المفسّرين، ولم نسقه بلفظ أحدٍ من الستّة في هذا الموضع.**\n**وأمّا وصفُنا لحال النبيّ ﷺ في التمهيد (اليُتم ورعيُ الغنم والعمل في التجارة) فمعلومٌ من السيرة، ولم ننقله عن أحدٍ من الستّة ها هنا بلفظه.**\n**وأمّا قولُنا إنّ الميزان الفاسد يعطي نتائجَ متّسقةً فلا يُكشف من داخله، فاستنباطٌ منّا لا نصٌّ لإمام**؛ ومن رأى أنّا وسّعنا فليردّه.\n**وأمّا تسميتُنا للجهتين اللتين نُقض بهما الاعتراض فترتيبٌ منّا لكلام السعديّ، والمعاني له.**"}},{"n":32,"reflection":{"text":"«أهم يقسمون رحمت ربك نحن قسمنا بينهم معيشتهم في الحياة الدنيا ورفعنا بعضهم فوق بعض درجات ليتخذ بعضهم بعضا سخريا ورحمت ربك خير مما يجمعون»: أهم يقسمون رحمةَ ربّك (النبوّة)؟ نحن قسمنا بينهم معيشتهم ورفعنا بعضهم فوق بعضٍ درجاتٍ ليسخّر بعضهم بعضًا، ورحمةُ ربّك خيرٌ مما يجمعون؛ ففي هذا أنّ القسمةَ بيدِ الله والتفاوتَ بحكمته؛ فاعلم أنّ الله قسم الأرزاقَ والمنازلَ بحكمته، فارضَ بقسمته، ولا تعترض على تفاوتِ الناس، ورحمةُ الله خيرٌ من كلِّ ما يُجمَع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرضا بقسمةِ الله وتفاوتِ الناس، وطلبُ رحمتِه خيرًا مما يُجمَع."},"action":{"text":"تأمّل ردَّ الله على اعتراضهم: أهم يقسمون رحمةَ ربّك فيضعون النبوّةَ حيث شاؤوا؟ ليس ذلك إليهم؛ نحن قسمنا بينهم معيشتهم وأرزاقهم في الحياةِ الدنيا بحكمتنا؛ ورفعنا بعضهم فوق بعضٍ درجاتٍ في الرزقِ والجاهِ والقوّة، ليتّخذ بعضهم بعضًا سخريًّا يخدم بعضهم بعضًا فتنتظم الحياة؛ ورحمةُ ربّك، الجنّةُ والإيمانُ والنبوّة، خيرٌ مما يجمعون من حطامِ الدنيا «أهم يقسمون رحمت ربك نحن قسمنا بينهم معيشتهم في الحياة الدنيا ورفعنا بعضهم فوق بعض درجات ليتخذ بعضهم بعضا سخريا ورحمت ربك خير مما يجمعون»؛ ففي هذا بيانُ أنّ القسمةَ بيدِ الله، وأنّ التفاوتَ بين الناسِ بحكمته؛ فإذا كانوا لا يملكون قسمةَ أرزاقِ الدنيا، فكيف يقسمون النبوّة؟ فاعلم أنّ الله قسم الأرزاقَ والمنازلَ بين الناسِ بحكمته وعلمه؛ ورفع بعضهم فوق بعضٍ درجاتٍ لحكمةِ انتظامِ الحياةِ وتسخيرِ بعضهم لبعض؛ فارضَ بقسمةِ الله لك من الرزقِ والمنزلة؛ ولا تعترض على تفاوتِ الناسِ في الأرزاقِ والمنازل؛ فهو بحكمةٍ من الله؛ ولا تتمنَّ ما فضّل الله به بعضكم على بعض؛ واعلم أنّ رحمةَ الله، الإيمانَ والجنّةَ، خيرٌ من كلِّ ما يجمعه الناسُ من الدنيا؛ فاطلب رحمةَ الله، فهي خيرٌ مما يجمعون؛ فاجعل همّك رحمةَ الله لا حطامَ الدنيا؛ فمن رضي بقسمةِ الله وطلب رحمته فاز."}},{"n":33,"reflection":{"text":"«ولولا أن يكون الناس أمة واحدة لجعلنا لمن يكفر بالرحمن لبيوتهم سقفا من فضة ومعارج عليها يظهرون»، ولولا أن يجتمع الناسُ على الكفرِ لهوانِ الدنيا لجعلنا لبيوتِ الكافرين سقوفًا من فضّةٍ ومصاعدَ يصعدون عليها؛ ففي هذا بيانُ هوانِ الدنيا على الله؛ فاعلم أنّ الدنيا هيّنةٌ على الله يعطيها الكافر، فلا تغترّ بها ولا تجعلها غايتك، فالدنيا لا وزنَ لها عند الله يعطيها من يحبّ ومن لا يحبّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ هوانِ الدنيا على الله، وعدمُ الاغترارِ بها."},"action":{"text":"تأمّل بيانَ هوانِ الدنيا على الله: ولولا أن يكون الناسُ أمّةً واحدةً على الكفرِ، لو رأوا الكافرَ يُعطى الدنيا فيميلون كلُّهم إلى الكفرِ طلبًا لها، لجعلنا لمن يكفر بالرحمنِ لبيوتهم سقوفًا من فضّة، ومعارجَ ومصاعدَ من فضّةٍ يصعدون عليها إلى غرفهم «ولولا أن يكون الناس أمة واحدة لجعلنا لمن يكفر بالرحمن لبيوتهم سقفا من فضة ومعارج عليها يظهرون»؛ ففي هذا بيانُ هوانِ الدنيا على الله؛ فلولا خشيةُ فتنةِ الناسِ لأعطى الكفّارَ من زخرفِ الدنيا ما شاء؛ فالدنيا هيّنةٌ حقيرةٌ على الله، يعطيها الكافرَ الذي يبغضه؛ فاعلم أنّ الدنيا لا وزنَ لها عند الله؛ لو كانت الدنيا تعدل عند الله جناحَ بعوضةٍ ما سقى كافرًا منها شربةَ ماء؛ فلا تغترّ بالدنيا وزخرفها؛ ولا تجعلها غايتك ومطلبك الأكبر؛ فالدنيا يعطيها الله من يحبّ ومن لا يحبّ، ولا يعطي الدينَ والإيمانَ إلا من يحبّ؛ فمن أُعطي الدنيا فليس ذلك دليلَ محبّةِ الله له؛ بل قد يكون استدراجًا؛ فاطلب ما يدلّ على محبّةِ الله: الإيمانَ والتقوى والدينَ؛ ولا تجعل همّك الدنيا الهيّنةَ على الله؛ فمن جعل الدنيا أكبرَ همّه هان على الله."}},{"n":34,"reflection":{"text":"«ولبيوتهم أبوابا وسررا عليها يتكئون»، ولجعلنا لبيوتِ الكافرين أبوابًا من فضّةٍ وسررًا يتّكئون عليها؛ ففي هذا تمامُ بيانِ هوانِ الدنيا؛ فاعلم أنّ متاعَ الدنيا كلَّه هيّنٌ على الله، فلا تحرص على زخرفِ الدنيا، بل اطلب نعيمَ الآخرةِ الباقي، فالدنيا زائلةٌ والآخرةُ خيرٌ وأبقى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ الحرصِ على زخرفِ الدنيا، وطلبُ نعيمِ الآخرة."},"action":{"text":"تأمّل تمامَ بيانِ هوانِ الدنيا: ولجعلنا لبيوتِ الكافرين أبوابًا من فضّة، وسررًا وأسرّةً من فضّةٍ يتّكئون عليها متنعّمين «ولبيوتهم أبوابا وسررا عليها يتكئون»؛ ففي هذا تمامُ بيانِ هوانِ الدنيا على الله؛ فلو شاء لأعطى الكفّارَ القصورَ والأبوابَ والأسرّةَ من الفضّة؛ فمتاعُ الدنيا كلُّه هيّنٌ حقيرٌ على الله؛ فاعلم أنّ زخرفَ الدنيا ومتاعها كلَّه هيّنٌ على الله؛ فلا تحرص على زخرفِ الدنيا وزينتها؛ ولا تجعلها أكبرَ همّك؛ فالدنيا زائلةٌ فانية؛ وما الحياةُ الدنيا إلا متاعُ الغرور؛ بل اطلب نعيمَ الآخرةِ الباقي؛ فما عند الله خيرٌ وأبقى؛ والآخرةُ خيرٌ وأبقى؛ فاجعل حرصك على الآخرةِ لا على الدنيا؛ فمن حرص على زخرفِ الدنيا وجعلها غايته خسر الآخرة؛ ومن زهد في زخرفها وطلب الآخرةَ ربح؛ فلا تنظر إلى ما متّع الله به الكافرين من زخرفِ الدنيا؛ ولا تمدّنّ عينيك إلى ما متّعنا به أزواجًا منهم زهرةَ الحياةِ الدنيا؛ فاطلب النعيمَ الباقي، ولا تغترّ بالزخرفِ الفاني."}},{"n":35,"reflection":{"text":"«وزخرفا وإن كل ذلك لما متاع الحياة الدنيا والآخرة عند ربك للمتقين»، وزينةً وذهبًا، وما كلُّ ذلك إلا متاعُ الحياةِ الدنيا، والآخرةُ عند ربّك للمتّقين؛ ففي هذا حصرُ الزخرفِ في متاعِ الدنيا وتخصيصُ الآخرةِ للمتّقين؛ فاطلب الآخرةَ بالتقوى، فهي خيرٌ من زخرفِ الدنيا، فالزخرفُ متاعٌ زائل، والآخرةُ للمتّقين، فاعمل للآخرةِ بالتقوى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الآخرةِ بالتقوى، فهي خيرٌ من زخرفِ الدنيا الزائل."},"action":{"text":"تأمّل حصرَ زخرفِ الدنيا وتخصيصَ الآخرةِ للمتّقين: ولجعلنا لهم زخرفًا، زينةً وذهبًا وأثاثًا؛ وما كلُّ ذلك الزخرفِ والمتاعِ إلا متاعُ الحياةِ الدنيا الزائلُ الحقير؛ والآخرةُ ونعيمها الباقي عند ربّك خالصةٌ للمتّقين «وزخرفا وإن كل ذلك لما متاع الحياة الدنيا والآخرة عند ربك للمتقين»؛ ففي هذا حصرُ زخرفِ الدنيا في كونه متاعًا زائلًا، وتخصيصُ الآخرةِ للمتّقين؛ فزخرفُ الدنيا كلُّه متاعٌ قليلٌ زائل، لا وزنَ له عند الله؛ والآخرةُ ونعيمها الباقي للمتّقين خاصّة؛ فاطلب الآخرةَ بالتقوى؛ فهي خيرٌ وأبقى من زخرفِ الدنيا؛ فالزخرفُ متاعٌ زائلٌ يعطيه الله البرَّ والفاجر؛ والآخرةُ نعيمٌ باقٍ لا يناله إلا المتّقون؛ فاجعل التقوى زادك إلى الآخرة؛ ولا تؤثر زخرفَ الدنيا الزائلَ على نعيمِ الآخرةِ الباقي؛ فالعاقلُ يعمل للآخرةِ الباقيةِ بالتقوى، لا للدنيا الفانيةِ بالزخرف؛ فمن اتّقى الله نال الآخرة، ومن آثر الزخرفَ خسرها؛ فاطلب الآخرةَ بالتقوى؛ فهي للمتّقين؛ فاعمل عملَ المتّقين لتنالها؛ فالتقوى سبيلُ الآخرة، والزخرفُ متاعٌ زائل."}}]},{"title":"قرينُ السوءِ للمعرض، وتسليةُ النبيّ، والاستمساكُ بالوحي، ووحدةُ دعوةِ الرسل","range":[36,45],"theme":"أنّ من يعرض عن ذكرِ الرحمنِ يُقيَّض له شيطانٌ قرينٌ يصدّه ويحسب أنه مهتد ثم يندم عليه يومَ القيامة، وأنّ اشتراكهم في العذابِ لا ينفعهم، وتسليةُ النبيِّ بأنه لا يُسمِع الصمَّ وأنّ الله منتقمٌ من المكذّبين مقتدرٌ عليهم، والأمرُ بالاستمساكِ بالوحيِ فهو الصراطُ المستقيمُ وذكرٌ يُسأل عنه، وأنّ الرسلَ كلَّهم دعوا إلى التوحيد","verses":[{"n":36,"reflection":{"text":"«ومن يعش عن ذكر الرحمن نقيض له شيطانا فهو له قرين»، ومن يُعرِض ويتعامَ عن ذكرِ الرحمنِ (القرآنِ) نسبّب له شيطانًا يكون قرينًا له؛ ففي هذا بيانُ عقوبةِ الإعراضِ عن الذكرِ بتسليطِ الشيطان؛ فاحذر الإعراضَ عن ذكرِ الله وقرآنه، فإنه يسلّط عليك شيطانًا، فالزم ذكرَ الله لتُعصَم من الشيطان، فالغفلةُ عن الذكرِ تجلب قرينَ السوء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ ذكرِ الله، فالإعراضُ عنه يسلّط قرينَ السوءِ من الشياطين."},"action":{"text":"تأمّل عقوبةَ الإعراضِ عن الذكر: ومن يعشُ ويُعرِض ويتعامَ عن ذكرِ الرحمنِ، القرآنِ والإيمانِ والطاعة، نقيّض ونسبّب له شيطانًا يلازمه، فهو له قرينٌ يزيّن له الباطلَ ويصدّه عن الحق «ومن يعش عن ذكر الرحمن نقيض له شيطانا فهو له قرين»؛ ففي هذا بيانُ أنّ الإعراضَ عن ذكرِ الله عقوبتُه تسليطُ الشيطانِ قرينًا؛ فمن أعرض عن ذكرِ الله سلّط الله عليه شيطانًا يقارنه ويضلّه؛ فاحذر الإعراضَ عن ذكرِ الله وقرآنه وطاعته؛ فإنّ الإعراضَ عن الذكرِ يسلّط عليك شيطانًا قرينًا يزيّن لك الباطلَ ويصدّك عن الحق؛ فالزم ذكرَ الله وقراءةَ القرآنِ والطاعة؛ فبذكرِ الله تُعصَم من الشيطان؛ فالذكرُ حصنٌ من الشيطان؛ ومن قرأ آيةَ الكرسيِّ لم يزل عليه من الله حافظٌ ولا يقربه شيطان؛ فالغفلةُ عن ذكرِ الله تجلب قرينَ السوءِ من الشياطين؛ فاعمر قلبك ولسانك بذكرِ الله؛ واحرص على الأذكارِ والتعوّذات؛ فبها تُحصَّن من الشيطان؛ فمن ذكر الله عُصِم، ومن أعرض عنه سُلّط عليه الشيطان؛ فالزم الذكرَ لتنجو من قرينِ السوء."},"qadiyya":{"title":"قضيّةُ جهلٍ مصدرُه الإعراض","question":"قال الله: ﴿وإنّهم ليصدّونهم عن السبيل ويحسبون أنّهم مهتدون﴾.\nفوصفهم بأمرين مجتمعين: صدٌّ عن السبيل، وحسبانٌ أنّهم على هدى؛ **والحسبانُ ظنٌّ، وصاحبُ الظنّ لا يرى نفسه مخالفًا.**\nفالقضيّة: أيكون ظنُّ الاهتداء عذرًا لصاحبه؟ ثمّ: إن لم يكن عذرًا، فبأيّ وصفٍ رُفع العذرُ عن هؤلاء بأعيانهم؟ ثمّ: وقد قُيّض لهم شيطانٌ يزيّن لهم الباطل، فأين تقع تبعةُ التزيين؟","background":"وقبل الجواب يحسن أن يُنظر في الجهل من جهتين.\nفمن جهة نفسه هو انتفاءُ العلم، ولا يتبيّن به المعذورُ من غيره.\nومن جهة مصدره يختلف؛ فمنه ما يرد على الرجل ولا حيلة له في دفعه، ومنه ما يصنعه الرجلُ بيده حين يُدعى إلى العلم فيُعرض عنه وهو قادر.\nوحالُ المخاطَبين ها هنا مبيّنةٌ في الآية قبلها؛ فهم قومٌ جاءهم ذكرُ الرحمن فأعرضوا عنه، لا قومٌ لم يبلغهم شيء.","what_happened":"بدأ ببيان السبيل الذي يُصدّون عنه، فقال: «أي: الصراط المستقيم، والدين القويم».\nثمّ بيّن من أين جاءهم الحسبان، فقال: «بسبب تزيين الشيطان للباطل وتحسينه له، وإعراضهم عن الحق، فاجتمع هذا وهذا».\n⭐ ثمّ أورد الإشكال على نفسه صريحًا: «فإن قيل: فهل لهذا من عذر، من حيث إنه ظن أنه مهتد، وليس كذلك؟».\nثمّ أجاب: «قيل: لا عذر لهذا وأمثاله، الذين مصدر جهلهم الإعراض عن ذكر اللّه، مع تمكنهم على الاهتداء، فزهدوا في الهدى مع القدرة عليه، ورغبوا في الباطل، فالذنب ذنبهم، والجرم جرمهم».\nثمّ ختم الموضع بقوله: «فهذه حالة هذا المعرض عن ذكر اللّه في الدنيا، مع قرينه، وهو الضلال والغيّ، وانقلاب الحقائق».","the_verdict":"فالحاصلُ أنّ الجواب لم يُبنَ على الظنّ ولا على صدق صاحبه فيه، بل على الطريق التي أُتي منها.\n⭐ فانظر إلى وصف من حكم عليهم: «مصدر جهلهم الإعراض عن ذكر اللّه»، ثمّ «مع تمكنهم على الاهتداء»؛ **فالحكمُ معلّقٌ بمصدرٍ ومكنة، لا بمجرّد وقوع الجهل.**\nفمتى كان الجهلُ ثمرةَ فعلٍ اختاره صاحبُه لم يصلح أن يُدفع به عن صاحبه؛ ولهذا قال: «فالذنب ذنبهم، والجرم جرمهم».\nوأمّا التزيينُ فقد جمعه مع الإعراض ولم يجعله بدلًا منه: «فاجتمع هذا وهذا». وقد نصّ في الآية قبلها على أنّ تقييض القرين نفسَه عقوبةٌ من الله على الإعراض، فقال: «يخبر تعالى عن عقوبته البليغة، لمن أعرض عن ذكره». فلا يُدفع بالتزيين عن المعرض شيءٌ من تبعته. وليس في هذا تبرئةٌ للقرين؛ فقد نصّ فيما بعدُ على اشتراكهم جميعًا في العقوبة: «ولا ينفعكم يوم القيامة اشتراككم في العذاب، أنتم وقرناؤكم وأخلاؤكم، وذلك لأنكم اشتركتم في الظلم، فاشتركتم في عقابه وعذابه».\n⭐ وأمّا موضعُ الغلط فمن جهتين متقابلتين.\nالأولى أن يُجعل الظنُّ عذرًا مطلقًا، فلا يبقى مخطئٌ إلّا وله عذر؛ إذ ليس في الناس من يعمل بما يعتقد أنّه ضلال.\nوالثانية أن يُرفع العذرُ عن كلّ جاهل، وهذا لم يقله؛ وإنّما حكم على «هذا وأمثاله» موصوفين بما وصفهم به.\nوفي قوله «انقلاب الحقائق» تمامُ المعنى؛ فالعقوبةُ وقعت في الميزان الذي يزن به قبل أن تقع في مصيره، فمن أعرض أُفسد عليه تمييزُه حتّى صار يرى الباطلَ هدًى. فليس حسبانُهم الاهتداءَ حالًا طرأت بلا سبب، بل هو ثمرةُ التزيين والإعراض مجتمعين كما قال، والإعراضُ منهم.\nوالمكنةُ التي رُفع بها العذرُ إنّما تُعتبر حين بلغهم الذكرُ وهم قادرون فأعرضوا؛ فأمّا فسادُ التمييز بعد ذلك فمن العقوبة لا من العذر، إذ هو أثرُ فعلهم لا سابقٌ عليه.","for_you":"فأمّا الذي تخرج به فثلاثة:\nالأوّل: لا تحتجّ باطمئنانك. سمِّ عملًا واحدًا تداوم عليه ولم تسأل قطُّ عن دليله، ثمّ اسأل عنه أهلَ العلم هذا الأسبوع.\nوالثاني: احصر ما تقدر عليه ولا تفعله. اكتب مسألةً واحدة تلزمك في صلاتك أو كسبك أو بيتك، أنت جاهلٌ بها ومن تسأله قريبٌ منك، ثمّ اقضِ جهلَك بها قبل انقضاء الشهر.\nوالثالث: أنقص ما يحسّن لك الباطل. عيّن مجلسًا أو صاحبًا أو حسابًا يحسّن لك ما تعلم أنّه باطل، ثمّ أنقص نصيبه من وقتك اليوم لا غدًا. **فأنت لا تملك أن تمنع التزيين، وتملك أن تدع الإعراض، وبه فُتح البابُ ها هنا.**","grade":"ma'thur","source":"إيرادُه الإشكال («فإن قيل: فهل لهذا من عذر») وجوابُه عنه («قيل: لا عذر لهذا وأمثاله»)، وتفسيرُه السبيل («أي: الصراط المستقيم»)، وبيانُه سبب الحسبان («بسبب تزيين الشيطان للباطل»)، وختمُه الموضع («فهذه حالة هذا المعرض عن ذكر اللّه»): كلُّها بنصّها في تفسير السعديّ (٤٣:٣٦). وقولُه في تقييض القرين («يخبر تعالى عن عقوبته البليغة») في (٤٣:٣٥)، وقولُه في اشتراك القرناء («أنتم وقرناؤكم وأخلاؤكم») في (٤٣:٣٨).","honesty":"وممّا يجب أن يُقال:\nالتفريقُ في التمهيد بين الجهل من جهة نفسه ومن جهة مصدره تمهيدٌ منّا نبني عليه، مأخوذٌ من قوله «مصدر جهلهم»، وليس تقسيمًا نصّ عليه.\nوتسميتُنا الوصفين في جوابه قيدين، مصدرًا ومكنةً، ترتيبٌ منّا على كلامه المجموع؛ وهو حكمٌ على من وصفهم، لا ضابطٌ عامٌّ ادّعيناه في الباب.\nوقولُنا إنّ الجهل صار من كسبهم استنباطٌ منّا من قوله «فالذنب ذنبهم، والجرم جرمهم».\nوأمّا تقسيمُنا موضعَ الغلط إلى جهتين، وقولُنا إنّه لو كان الظنُّ عذرًا لما بقي مخطئٌ إلّا معذورًا، فإلزامٌ منّا نحتجّ به، ليس في كلامه؛ وإنّما الذي في كلامه نفيُ العذر عن «هذا وأمثاله» موصوفين.\nوربطُنا بين موضع القرين وموضع الإعراض مبنيٌّ على نصّه أنّ التقييض عقوبة، وأمّا صوغُ الربط فمنّا؛ واقتصارُنا على تبعة المعرض لأنّ الكلام فيه، وقد نصّ هو على مشاركة القرناء في العذاب في موضعه.\nوقولُنا إنّ العقوبة وقعت في ميزان التمييز قبل المصير استنباطٌ منّا من قوله «انقلاب الحقائق»، وكذلك ترتيبُنا المكنةَ قبل فساد التمييز في الزمان.\nوالأمثلةُ الثلاثة في ما تخرج به منّا، وتنزيلُ التزيين على المجالس والصحبة والحسابات منّا، ليس في كلامه شيءٌ منه.\nولم يتكلّم في هذا الموضع على تفصيل مسائل العذر بالجهل، وإنّما حكم على من وصفهم بما وصفهم به، فلا يُحمَّل كلامُه غيرَ ذلك. ومن رأى أنّا وسّعنا فليردّه."}},{"n":37,"reflection":{"text":"«وإنهم ليصدونهم عن السبيل ويحسبون أنهم مهتدون»، وإنّ الشياطينَ ليصدّون المعرضين عن سبيلِ الحقّ، والمعرضون يحسبون أنهم مهتدون؛ ففي هذا خطرُ الاغترارِ بالضلالِ وحسبانِه هدى؛ فاحذر أن تُصَدَّ عن الحقِّ وأنت تحسب أنك مهتد، فراقب عملك بميزانِ الوحي، فأخطرُ الضلالِ ما يحسبه صاحبه هدى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الضلالِ الذي يُحسَب هدى، ووزنُ العملِ بميزانِ الوحي."},"action":{"text":"تأمّل خطرَ قرينِ السوءِ من الشياطين: وإنّ الشياطينَ القرناءَ ليصدّون المعرضين عن ذكرِ الله عن سبيلِ الحقِّ والهدى، ويزيّنون لهم الباطل؛ والمعرضون مع ذلك يحسبون ويظنّون أنهم مهتدون على الحق «وإنهم ليصدونهم عن السبيل ويحسبون أنهم مهتدون»؛ ففي هذا بيانُ خطرِ قرينِ السوء، وخطرِ الاغترارِ بالضلالِ وحسبانِه هدى؛ فالشياطينُ تصدّ عن الحقِّ وتزيّن الباطل، حتى يظنّ الضالُّ أنه مهتد؛ فاحذر أن تُصَدَّ عن الحقِّ وأنت تحسب أنك مهتد؛ فأخطرُ الضلالِ ما يحسبه صاحبه هدى؛ قل هل ننبّئكم بالأخسرين أعمالًا الذين ضلّ سعيهم في الحياةِ الدنيا وهم يحسبون أنهم يحسنون صنعًا؛ فراقب عملك واعتقادك بميزانِ الوحيِ والسنّة، لا بظنّك وهواك؛ فقد يزيّن الشيطانُ الباطلَ فيحسبه صاحبه حقًّا؛ فمن اغترّ بعمله وظنّه هدًى وهو ضلالٌ فهو أخسرُ الناس؛ فاطلب من الله أن يريك الحقَّ حقًّا ويرزقك اتّباعه، والباطلَ باطلًا ويرزقك اجتنابه؛ ولا تغترّ بعملك؛ بل زِنه بميزانِ الوحي؛ فمن وزن عمله بالوحيِ نجا من الاغترار، ومن اتّبع ظنّه وهواه ضلّ وهو يحسب أنه مهتد."}},{"n":38,"reflection":{"text":"«حتى إذا جاءنا قال يا ليت بيني وبينك بعد المشرقين فبئس القرين»: حتى إذا جاءنا المعرضُ مع قرينِه يومَ القيامة قال: يا ليت بيني وبينك بُعدَ المشرقِ والمغرب، فبئس القرينُ أنت؛ ففي هذا ندمُ المعرضِ على قرينِ السوء؛ فاحذر قرينَ السوءِ الذي تندم على صحبته يومَ القيامة، فاختر القرينَ الصالح، فقرينُ السوءِ ندامةٌ يومَ القيامة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من قرينِ السوء، واختيارُ القرينِ الصالح."},"action":{"text":"تأمّل ندمَ المعرضِ على قرينه: حتى إذا جاءنا هذا المعرضُ عن ذكرِ الله يومَ القيامةِ مع قرينِه من الشياطين، قال متحسّرًا نادمًا: يا ليت بيني وبينك بُعدَ المشرقين، المشرقِ والمغرب، فبئس القرينُ أنت الذي أضللتني «حتى إذا جاءنا قال يا ليت بيني وبينك بعد المشرقين فبئس القرين»؛ ففي هذا بيانُ ندمِ المعرضِ على مقارنةِ قرينِ السوءِ يومَ القيامة؛ فيتمنّى لو لم يكن قد قارنه؛ فاحذر قرينَ السوءِ الذي يضلّك ويصدّك عن الحق، فتندم على صحبته يومَ القيامة؛ فقرينُ السوءِ، من الإنسِ أو الجن، يجرّ صاحبه إلى الهلاك؛ ويوم يعضّ الظالمُ على يديه يقول يا ليتني اتّخذت مع الرسولِ سبيلا يا ويلتى ليتني لم أتّخذ فلانًا خليلا؛ فاختر القرينَ الصالحَ الذي يعينك على الخيرِ ويذكّرك بالله؛ فالمرءُ على دينِ خليله؛ فلينظر أحدكم من يخالل؛ فمثلُ الجليسِ الصالحِ كحاملِ المسك، وجليسِ السوءِ كنافخِ الكير؛ فاحرص على صحبةِ الأخيار؛ واحذر صحبةَ الأشرار؛ فقرينُ الخيرِ يدلّك على الجنّة، وقرينُ السوءِ يوردك النار؛ فمن صاحب الأخيارَ سعد، ومن صاحب الأشرارَ ندم؛ فاختر قرينك بعناية."}},{"n":39,"reflection":{"text":"«ولن ينفعكم اليوم إذ ظلمتم أنكم في العذاب مشتركون»، ولن ينفعكم اليومَ اشتراككم في العذابِ مع قرنائكم، لأنكم ظلمتم؛ ففي هذا أنّ اشتراكَ أهلِ العذابِ لا يخفّفه؛ فاعلم أنّ الاشتراكَ في العذابِ لا يخفّفه ولا ينفع، فلا تتّبع أحدًا في الظلمِ ظنًّا أنّ الاشتراكَ يخفّف، فالعذابُ لا يخفّفه اشتراكٌ ولا كثرة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ الاشتراكَ في العذابِ لا يخفّفه، فلا يُتّبَع أحدٌ في الظلم."},"action":{"text":"تأمّل بيانَ أنّ الاشتراكَ في العذابِ لا ينفع: ولن ينفعكم اليومَ، يومَ القيامة، إذ ظلمتم أنفسكم بالكفرِ والمعاصي، أنكم مشتركون في العذابِ أنتم وقرناؤكم؛ فاشتراككم في العذابِ لا يخفّفه عنكم «ولن ينفعكم اليوم إذ ظلمتم أنكم في العذاب مشتركون»؛ ففي هذا بيانُ أنّ اشتراكَ أهلِ العذابِ في العذابِ لا يخفّفه عنهم؛ فقد يظنّ بعضهم أنّ اشتراكهم في العذابِ يخفّفه، كما يُخفَّف المصابُ إذا كثر المصابون في الدنيا؛ لكن عذابَ الآخرةِ لا يخفّفه اشتراكٌ ولا كثرة؛ فلكلٍّ نصيبه الكاملُ من العذاب؛ فاعلم أنّ الاشتراكَ في العذابِ لا يخفّفه ولا ينفع صاحبه؛ فلا تتّبع أحدًا في الظلمِ والمعصيةِ ظنًّا أنّ الاشتراكَ يخفّف العذاب؛ ولا تقل: أفعل ما يفعله الناس، وأُعذَّب كما يُعذَّبون؛ فإنّ العذابَ لا يخفّفه اشتراكٌ ولا كثرة؛ بل كلٌّ يُعذَّب بذنبه عذابًا كاملًا؛ فلا يغرّنك كثرةُ العصاة؛ ولا تتّبعهم في الظلمِ ظنًّا أنّ الكثرةَ تخفّف؛ فكلٌّ يحمل وزره كاملًا؛ فاحذر الظلمَ والمعصية، ولو اشترك فيها الكثيرون؛ فالنجاةُ في الطاعةِ لا في مشاركةِ العصاة."}},{"n":40,"reflection":{"text":"«أفأنت تسمع الصم أو تهدي العمي ومن كان في ضلال مبين»: أفأنت يا محمدُ تُسمِع الصمَّ أو تهدي العميَ ومن كان في ضلالٍ مبين؟ ففي هذا تسليةُ النبيِّ وبيانُ أنّ الهدايةَ بيدِ الله؛ فاعلم أنّ من أعرض عن الحقِّ كالأصمِّ الأعمى لا تملك هدايته، فابذل الدعوةَ ولا تحزن على من لم يهتدِ، فالهدايةُ بيدِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ الهدايةَ بيدِ الله، وبذلُ الدعوةِ دون حزن."},"action":{"text":"تأمّل تسليةَ الله لنبيّه: أفأنت يا محمدُ تقدر أن تُسمِع الصمَّ الذين لا يسمعون الحقَّ سماعَ قبول؟ أو تهدي العميَ الذين لا يبصرون الحقّ؟ أو تهدي من كان في ضلالٍ واضحٍ بيّن؟ لست بقادرٍ على ذلك، إنما عليك البلاغ «أفأنت تسمع الصم أو تهدي العمي ومن كان في ضلال مبين»؛ ففي هذا تسليةُ النبيِّ ﷺ على إعراضِ المكذّبين، وبيانُ أنّ الهدايةَ بيدِ الله؛ فمن أعرض عن الحقِّ وأصرّ على الضلالِ فهو كالأصمِّ الذي لا يسمع، والأعمى الذي لا يبصر؛ فلا تملك هدايته؛ فالهدايةُ، هدايةُ التوفيقِ والقبول، بيدِ الله وحده؛ إنك لا تهدي من أحببت ولكنّ الله يهدي من يشاء؛ فابذل الدعوةَ والنصحَ والبيانَ لمن حولك؛ ثم لا تحزن على من لم يهتدِ بعد بلوغِ الحجّة؛ فليس عليك هداهم؛ إنما عليك البلاغ، وعلى الله الهداية؛ فلا تذهب نفسك عليهم حسرات؛ فما أنت عليهم بمسيطر؛ فأدِّ ما عليك من الدعوة، ووكِّل أمرَ الهدايةِ إلى الله؛ فمن كتب الله له الهدايةَ اهتدى، ومن أصرّ على الضلالِ فهو كالأصمِّ الأعمى؛ فاجتهد في الدعوة، ولا تحمل نفسك ما لا تطيق."}},{"n":41,"reflection":{"text":"«فإما نذهبن بك فإنا منهم منتقمون»: فإما نذهبنّ بك يا محمدُ (بالموت) فإنا منهم منتقمون؛ ففي هذا وعدُ الله بالانتقامِ من المكذّبين؛ فاعلم أنّ الله منتقمٌ من المكذّبين لا محالة، سواءٌ في حياةِ الرسولِ أم بعده، فاثبت على الحقِّ واثقًا بنصرِ الله وانتقامِه من أعدائه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بانتقامِ الله من المكذّبين، والثباتُ على الحق."},"action":{"text":"تأمّل وعدَ الله بالانتقامِ من المكذّبين: فإما نذهبنّ بك يا محمدُ بالموتِ قبل أن نريك عذابهم، فإنا منهم منتقمون لا محالة «فإما نذهبن بك فإنا منهم منتقمون»؛ ففي هذا وعدُ الله بالانتقامِ من المكذّبين المعاندين؛ فسواءٌ توفّى الله نبيَّه قبل نزولِ العذابِ بهم، أو أراه ذلك في حياته، فإنّ الله منتقمٌ منهم لا محالة؛ فاعلم أنّ الله منتقمٌ من المكذّبين المعاندين للحق؛ فوعده بالانتقامِ منهم حقٌّ لا يتخلّف؛ فاثبت على الحقِّ واثقًا بنصرِ الله وانتقامِه من أعدائه؛ فلا يهولنّك تسلّطُ أهلِ الباطلِ حينًا؛ فإنّ الله منتقمٌ منهم؛ فالعاقبةُ للحقِّ وأهله، والانتقامُ من المكذّبين؛ فاصبر على أذاهم، وثق بوعدِ الله؛ فإنّ الله لا يترك المكذّبين المعاندين بلا انتقام؛ فمن كذّب الحقَّ وعاند انتقم الله منه؛ فاثبت على الحق، واصبر، وانتظر انتقامَ الله من أعدائه؛ فالنصرُ للحقِّ، والانتقامُ من المكذّبين، ولو بعد حين."}},{"n":42,"reflection":{"text":"«أو نرينك الذي وعدناهم فإنا عليهم مقتدرون»: أو نرينّك الذي وعدناهم من العذاب في حياتك، فإنا عليهم مقتدرون؛ ففي هذا بيانُ قدرةِ الله على المكذّبين؛ فاعلم أنّ الله مقتدرٌ على المكذّبين، فلا يعجزونه، فاثبت على الحقِّ واثقًا بقدرةِ الله على أعدائه، فالمكذّبون تحت قدرةِ الله لا يفوتونه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بقدرةِ الله على المكذّبين، والثباتُ على الحق."},"action":{"text":"تأمّل بيانَ قدرةِ الله على المكذّبين: أو نرينّك يا محمدُ في حياتك الذي وعدناهم من العذابِ والنكال، فتقرّ عينك بذلك، فإنا عليهم مقتدرون قادرون لا يعجزوننا «أو نرينك الذي وعدناهم فإنا عليهم مقتدرون»؛ ففي هذا بيانُ قدرةِ الله التامّةِ على المكذّبين؛ فهم تحت قدرةِ الله، لا يفوتونه ولا يعجزونه؛ فاعلم أنّ الله مقتدرٌ على المكذّبين المعاندين؛ فلا يعجزونه ولا يفوتونه؛ وما هم بمعجزين؛ فاثبت على الحقِّ واثقًا بقدرةِ الله على أعدائه؛ فلا يهولنّك تسلّطهم؛ فإنهم تحت قدرةِ الله، يأخذهم متى شاء؛ فالله قادرٌ على إهلاكهم والانتقامِ منهم في أيِّ وقتٍ شاء؛ فاصبر، وثق بقدرةِ الله؛ فإنّ المكذّبين مهما تجبّروا فهم تحت قهرِ الله وقدرته؛ فمن ثبت على الحقِّ واثقًا بقدرةِ الله نصره الله؛ فاجعل ثقتك بقدرةِ الله على أعدائه؛ فهو المقتدرُ عليهم، لا يفوتونه؛ فالعاقبةُ للحقِّ، والله مقتدرٌ على المكذّبين."}},{"n":43,"reflection":{"text":"«فاستمسك بالذي أوحي إليك إنك على صراط مستقيم»: فتمسّك بالذي أُوحِي إليك (القرآن)، إنك على صراطٍ مستقيم؛ ففي هذا الأمرُ بالتمسّكِ بالوحيِ والثباتِ عليه؛ فتمسّك بالقرآنِ واعمل به، فمن تمسّك بالوحيِ فهو على صراطٍ مستقيم، فاجعل القرآنَ إمامك ودليلك، فالتمسّكُ به عصمةٌ من الضلال.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التمسّكُ بالوحيِ والعملُ به، فهو الصراطُ المستقيم."},"action":{"text":"تأمّل الأمرَ بالتمسّكِ بالوحي: فاستمسك يا محمدُ بالذي أُوحِي إليك من القرآنِ والدين، وتمسّك به واعمل به وادعُ إليه، إنك على صراطٍ مستقيمٍ موصلٍ إلى الله وإلى جنّته «فاستمسك بالذي أوحي إليك إنك على صراط مستقيم»؛ ففي هذا الأمرُ بالتمسّكِ بالوحيِ والثباتِ عليه، وبيانُ أنّ من تمسّك به على صراطٍ مستقيم؛ فالوحيُ، القرآنُ والسنّة، هو الصراطُ المستقيم؛ فتمسّك بالقرآنِ والوحيِ واعمل به؛ فاعتصموا بحبلِ الله جميعًا؛ ومن يعتصم بالله فقد هُدي إلى صراطٍ مستقيم؛ فمن تمسّك بالوحيِ وعمل به فهو على صراطٍ مستقيمٍ لا يضلّ؛ فاجعل القرآنَ والسنّةَ إمامك ودليلك؛ ولا تلتمس الهدى في غيرهما؛ فالتمسّكُ بالوحيِ عصمةٌ من الضلال؛ تركت فيكم ما إن تمسّكتم به لن تضلّوا: كتابَ الله وسنّةَ رسوله؛ فمن تمسّك بالوحيِ اهتدى، ومن أعرض عنه ضلّ؛ فاستمسك بالقرآنِ والسنّة؛ واعمل بهما، وادعُ إليهما؛ فبالتمسّكِ بالوحيِ تسلك الصراطَ المستقيم؛ فهو حبلُ الله المتين، وصراطُه المستقيم."}},{"n":44,"reflection":{"text":"«وإنه لذكر لك ولقومك وسوف تسألون»، وإنّ القرآنَ لشرفٌ لك ولقومك، وسوف تُسألون عنه؛ ففي هذا بيانُ شرفِ القرآنِ ومسؤوليةِ حمله؛ فاعلم أنّ القرآنَ شرفٌ لمن حمله وعمل به، وأنك مسؤولٌ عنه، فاحمل القرآنَ واعمل به وأدِّ حقّه، فالقرآنُ شرفٌ ومسؤولية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ شرفِ القرآنِ ومسؤوليةِ حمله، والقيامُ بحقّه."},"action":{"text":"تأمّل بيانَ شرفِ القرآنِ ومسؤوليته: وإنّ هذا القرآنَ لذكرٌ وشرفٌ ورفعةٌ لك يا محمدُ ولقومك، العربِ خاصّةً والمسلمين عامّةً؛ وسوف تُسألون عنه يومَ القيامة: هل قمتم بحقّه من الإيمانِ والعملِ والتبليغ؟ «وإنه لذكر لك ولقومك وسوف تسألون»؛ ففي هذا بيانُ شرفِ القرآنِ لحملته، ومسؤوليتهم عنه؛ فالقرآنُ شرفٌ ورفعةٌ لمن حمله وعمل به وبلّغه؛ لقد أنزلنا إليكم كتابًا فيه ذكركم؛ فاعلم أنّ القرآنَ شرفٌ عظيمٌ لمن حمله وعمل به؛ وأنك مسؤولٌ عنه يومَ القيامة؛ فاحمل القرآنَ حقَّ الحمل: بالإيمانِ به، والعملِ بمقتضاه، وتلاوته، وتدبّره، وتبليغه؛ وأدِّ حقّه؛ فالقرآنُ أمانةٌ ومسؤولية؛ وسوف تُسأل عنه: أقمت بحقّه أم ضيّعته؟ فمن قام بحقِّ القرآنِ نال شرفه، ومن ضيّعه خسر؛ فاجعل القرآنَ شرفك بالعملِ به؛ واستعدّ للسؤالِ عنه بالقيامِ بحقّه؛ فالقرآنُ شرفٌ لمن أقام حقّه، ومسؤوليةٌ يُسأل عنها؛ فأدِّ حقّ القرآنِ لتنال شرفه وتسلم من مسؤوليته."}},{"n":45,"reflection":{"text":"«واسأل من أرسلنا من قبلك من رسلنا أجعلنا من دون الرحمن آلهة يعبدون»، واسأل أخبارَ من أرسلنا قبلك من الرسل: أجعلنا من دونِ الرحمنِ آلهةً تُعبَد؟ ففي هذا تقريرُ أنّ دعوةَ الرسلِ كلِّهم التوحيد؛ فاعلم أنّ جميعَ الرسلِ دعوا إلى توحيدِ الله لا إلى الشرك، فالتوحيدُ دينُ الرسلِ جميعًا، فاتّبع ما اتّفق عليه الرسلُ من التوحيد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بأنّ دعوةَ الرسلِ كلِّهم التوحيد، واتّباعُ ما اتّفقوا عليه."},"action":{"text":"تأمّل تقريرَ وحدةِ دعوةِ الرسل: واسأل يا محمدُ أخبارَ من أرسلنا من قبلك من رسلنا، وانظر في شرائعهم ودعوتهم: أجعلنا من دونِ الرحمنِ آلهةً تُعبَد؟ لم يفعلوا؛ بل دعوا كلُّهم إلى توحيدِ الله وحده «واسأل من أرسلنا من قبلك من رسلنا أجعلنا من دون الرحمن آلهة يعبدون»؛ ففي هذا تقريرُ أنّ دعوةَ الرسلِ كلِّهم واحدة: التوحيدُ ونبذُ الشرك؛ فما بعث الله رسولًا إلا بالتوحيد؛ ولقد بعثنا في كلِّ أمّةٍ رسولًا أن اعبدوا الله واجتنبوا الطاغوت؛ وما أرسلنا من قبلك من رسولٍ إلا نوحي إليه أنه لا إله إلا أنا فاعبدون؛ فاعلم أنّ جميعَ الرسلِ من نوحٍ إلى محمدٍ دعوا إلى توحيدِ الله وإخلاصِ العبادةِ له، لا إلى الشرك؛ فالتوحيدُ دينُ الرسلِ جميعًا وأصلُ دعوتهم؛ فاتّبع ما اتّفق عليه الرسلُ كلُّهم من التوحيدِ ونبذِ الشرك؛ فمن اتّبع التوحيدَ فقد اتّبع دينَ الرسلِ جميعًا؛ ومن أشرك فقد خالفهم كلَّهم؛ فحقّق التوحيدَ الذي هو دينُ الرسل؛ فهو الحقُّ الذي اتّفقوا عليه؛ فاتّبعه، ولا تلتفت إلى شبهاتِ المشركين."}}]},{"title":"موسى وفرعونُ واستهزاؤه واغترارُه بملكه، واستخفافُه قومَه، وإغراقُه","range":[46,56],"theme":"إرسالُ موسى بالآياتِ إلى فرعونَ وملئه فاستهزؤوا بها وأُخِذوا بالعذابِ ليرجعوا، ومراوغتُهم بطلبِ الدعاءِ بكشفِ العذابِ ثم نكثِهم، واغترارُ فرعونَ بملكِ مصرَ واحتقارُه موسى بمقاييسِ الدنيا واقتراحُه الأساورَ والملائكة، واستخفافُه قومَه الفاسقين فأطاعوه، فلمّا أغضبوا الله أغرقهم أجمعين وجعلهم سلفًا ومثلًا للآخرين","verses":[{"n":46,"reflection":{"text":"«ولقد أرسلنا موسى بآياتنا إلى فرعون وملئه فقال إني رسول رب العالمين»، ولقد أرسلنا موسى بآياتنا إلى فرعونَ وأشرافِ قومه، فقال: إني رسولُ ربِّ العالمين؛ ففي هذا بيانُ إرسالِ موسى بالتوحيدِ إلى الطغاة؛ فاعتبر بدعوةِ موسى للطغاةِ بالتوحيدِ والشجاعةِ في إبلاغه، فالداعيةُ يبلّغ الحقَّ للطغاةِ بشجاعة، فبلّغ الحقَّ ولو للأقوياء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الشجاعةُ في تبليغِ الحقِّ للطغاة، والاعتبارُ بدعوةِ موسى."},"action":{"text":"تأمّل إرسالَ موسى إلى فرعون: ولقد أرسلنا موسى بآياتنا وحججنا الباهرةِ إلى فرعونَ الطاغيةِ وملئه وأشرافِ قومه؛ فقال لهم موسى بشجاعةٍ وثبات: إني رسولُ ربِّ العالمين إليكم «ولقد أرسلنا موسى بآياتنا إلى فرعون وملئه فقال إني رسول رب العالمين»؛ ففي هذا بيانُ إرسالِ موسى بالتوحيدِ والآياتِ إلى فرعونَ الطاغيةِ وملئه، وشجاعتِه في إبلاغِ الحق؛ فواجه موسى أعتى الطغاةِ بكلمةِ الحق؛ فاعتبر بدعوةِ موسى للطغاةِ بالتوحيد، وشجاعتِه في إبلاغِ الحقِّ لهم؛ فالداعيةُ الصادقُ يبلّغ الحقَّ للطغاةِ والأقوياءِ بشجاعةٍ وثبات، لا يخاف في الله لومةَ لائم؛ اذهبا إلى فرعونَ إنه طغى فقولا له قولًا ليّنًا؛ فبلّغ الحقَّ ولو للأقوياءِ والطغاة؛ ولا يمنعك خوفهم من قولِ الحق؛ فأفضلُ الجهادِ كلمةُ حقٍّ عند سلطانٍ جائر؛ فاقتدِ بموسى في الشجاعةِ في إبلاغِ الحقِّ للطغاة؛ ثم فوّض أمرك إلى الله؛ فمن بلّغ الحقَّ بشجاعةٍ وتوكّل على الله كفاه الله؛ فبلّغ الحقَّ، ولا تخف إلا الله."}},{"n":47,"reflection":{"text":"«فلما جاءهم بآياتنا إذا هم منها يضحكون»: فلمّا جاءهم موسى بآياتنا إذا هم منها يضحكون استهزاءً؛ ففي هذا استهزاءُ الطغاةِ بآياتِ الله؛ فاحذر الاستهزاءَ بآياتِ الله، فالاستهزاءُ بالآياتِ من طبعِ المكذّبين، فعظّم آياتِ الله ولا تستهزئ بها، فالاستهزاءُ بالحقِّ عاقبتُه وخيمة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الاستهزاءِ بآياتِ الله، وتعظيمُها."},"action":{"text":"تأمّل استهزاءَ فرعونَ وملئه بآياتِ الله: فلمّا جاءهم موسى بآياتنا الواضحاتِ الدالّةِ على صدقه، إذا هم منها يضحكون ويستهزئون، بدلًا من أن يؤمنوا بها «فلما جاءهم بآياتنا إذا هم منها يضحكون»؛ ففي هذا بيانُ استهزاءِ الطغاةِ بآياتِ الله؛ فلمّا رأوا الآياتِ العظيمةَ قابلوها بالضحكِ والاستهزاءِ لا بالإيمانِ والتصديق؛ فاحذر الاستهزاءَ بآياتِ الله وشعائرِه ودينه؛ فالاستهزاءُ بالآياتِ والحقِّ من طبعِ المكذّبين المعاندين؛ وإذا رأوا آيةً يستسخرون؛ فعظّم آياتِ الله، القرآنيةَ والكونية، ولا تستهزئ بها؛ ولا تسخر من شيءٍ من دينِ الله وشعائره؛ فالاستهزاءُ بالحقِّ وآياتِ الله عاقبتُه وخيمة؛ قل أبالله وآياته ورسوله كنتم تستهزئون لا تعتذروا قد كفرتم بعد إيمانكم؛ فالاستهزاءُ بآياتِ الله كفر؛ فعظّم آياتِ الله وشعائره؛ ومن يعظّم شعائرَ الله فإنها من تقوى القلوب؛ فمن عظّم آياتِ الله انتفع بها، ومن استهزأ بها هلك؛ فاجعل قلبك معظّمًا لآياتِ الله، لا مستهزئًا بها."}},{"n":48,"reflection":{"text":"«وما نريهم من آية إلا هي أكبر من أختها وأخذناهم بالعذاب لعلهم يرجعون»، وما نريهم من آيةٍ إلا هي أعظمُ من الأخرى، وأخذناهم بالعذابِ (كالطوفانِ والجراد) لعلّهم يرجعون؛ ففي هذا تتابعُ آياتِ الله وعقوباتِه للرجوع؛ فاعلم أنّ الله يبتلي بالآياتِ والعقوباتِ ليرجع العبدُ إليه، فإذا نزلت بك عقوبةٌ فارجع إلى الله، فالعقوباتُ داعيةٌ للرجوعِ والتوبة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجوعُ إلى الله عند العقوبات، وإدراكُ حكمتِها في الرجوع."},"action":{"text":"تأمّل تتابعَ آياتِ الله وعقوباتِه على فرعونَ وقومه: وما نريهم من آيةٍ من الآياتِ التسعِ إلا هي أكبرُ وأعظمُ من أختها التي قبلها؛ وأخذناهم بالعذابِ، كالطوفانِ والجرادِ والقمّلِ والضفادعِ والدم، لعلّهم يرجعون عن كفرهم وطغيانهم «وما نريهم من آية إلا هي أكبر من أختها وأخذناهم بالعذاب لعلهم يرجعون»؛ ففي هذا بيانُ تتابعِ آياتِ الله وعقوباتِه على المكذّبين، وأنّ حكمتها الرجوعُ إلى الله؛ فأرسل الله عليهم الآياتِ والعقوباتِ المتتابعةَ ليرجعوا؛ فاعلم أنّ الله يبتلي عباده بالآياتِ والعقوباتِ ليرجعوا إليه ويتوبوا؛ ولنذيقنّهم من العذابِ الأدنى دون العذابِ الأكبرِ لعلّهم يرجعون؛ فإذا نزلت بك عقوبةٌ أو بلاءٌ فارجع إلى الله بالتوبةِ والإنابة؛ ولا تُصِرّ على المعصيةِ فتُبتَلى بأعظمَ منها؛ فالعقوباتُ والبلايا داعيةٌ للرجوعِ إلى الله والتوبةِ إليه؛ فمن رجع إلى الله عند العقوبةِ رحمه، ومن أصرّ عوقب بأشدّ؛ فاجعل من العقوباتِ والبلايا داعيًا للرجوعِ إلى الله؛ فبادر بالتوبةِ والرجوعِ عند نزولِ البلاء؛ فالحكمةُ من العقوباتِ الرجوعُ إلى الله."}},{"n":49,"reflection":{"text":"«وقالوا يا أيه الساحر ادع لنا ربك بما عهد عندك إننا لمهتدون»، وقالوا: يا أيها الساحرُ ادعُ لنا ربّك بما عهد عندك (من كشفِ العذابِ إن آمنّا)، إننا لمهتدون؛ ففي هذا مراوغةُ المكذّبين عند العذاب؛ فاحذر الوعودَ الكاذبةَ عند الشدّة، فالمكذّبون يعدون بالإيمانِ عند العذابِ ثم ينكثون، فاصدق مع الله في الرخاءِ والشدّة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصدقُ مع الله في الرخاءِ والشدّة، والحذرُ من الوعودِ الكاذبة."},"action":{"text":"تأمّل مراوغةَ فرعونَ وقومه عند العذاب: وقالوا لموسى لمّا نزل بهم العذاب: يا أيها الساحرُ، يخاطبونه بذلك تعظيمًا لعلمه في زعمهم، أو استهزاءً، ادعُ لنا ربّك بما عهد عندك من كشفِ العذابِ إن آمنّا، إننا لمهتدون مؤمنون إن كشفته «وقالوا يا أيه الساحر ادع لنا ربك بما عهد عندك إننا لمهتدون»؛ ففي هذا بيانُ مراوغةِ المكذّبين ووعودهم الكاذبةِ عند نزولِ العذاب؛ فوعدوا بالإيمانِ والاهتداءِ إن كُشِف العذابُ عنهم؛ ولكنهم كاذبون؛ فاحذر الوعودَ الكاذبةَ عند الشدّةِ والعذاب؛ فإنّ المكذّبين يعدون بالإيمانِ والتوبةِ عند نزولِ البلاء، ثم ينكثون ويعودون إذا كُشِف عنهم؛ فلمّا كشفنا عنهم العذابَ إذا هم ينكثون؛ فاصدق مع الله في الرخاءِ والشدّة؛ ولا تكن ممّن يعد الله بالتوبةِ عند الشدّةِ ثم ينكث عند الرخاء؛ فالوفاءُ في العبوديةِ في الحالين؛ فمن صدق مع الله في وعده وفى، ومن كذب نكث؛ فاجعل صدقك مع الله دائمًا، لا وعودًا كاذبةً عند الشدّةِ تُنكَث عند الرخاء؛ فالصادقُ يفي بعهده مع الله في السرّاءِ والضرّاء."}},{"n":50,"reflection":{"text":"«فلما كشفنا عنهم العذاب إذا هم ينكثون»: فلمّا كشفنا عنهم العذابَ إذا هم ينقضون عهدهم ويعودون إلى الكفر؛ ففي هذا نكثُ المكذّبين وعودهم؛ فاحذر نقضَ العهدِ مع الله بعد الفرج، فمن وعد الله بالتوبةِ عند الشدّةِ فليفِ بعد الفرج، فالنكثُ بعد الفرجِ من صفاتِ المكذّبين، فأوفِ بعهدك مع الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الوفاءُ بالعهدِ مع الله بعد الفرج، والحذرُ من النكث."},"action":{"text":"تأمّل نكثَ فرعونَ وقومه: فلمّا كشفنا عنهم العذابَ استجابةً لطلبهم، إذا هم ينكثون وينقضون عهدهم الذي عاهدوا عليه، ويعودون إلى كفرهم وطغيانهم «فلما كشفنا عنهم العذاب إذا هم ينكثون»؛ ففي هذا بيانُ نكثِ المكذّبين لعهودهم بعد كشفِ العذاب؛ فلمّا كُشِف عنهم العذابُ نكثوا ولم يفوا بوعدهم بالإيمان؛ فاحذر نقضَ العهدِ مع الله بعد الفرجِ والنجاة؛ فمن وعد الله بالتوبةِ والطاعةِ عند الشدّةِ والبلاء، فليفِ بعهده بعد الفرجِ والنجاة؛ فالنكثُ بعد الفرجِ من صفاتِ المكذّبين والمنافقين؛ ومنهم من عاهد الله لئن آتانا من فضله لنصّدّقنّ ولنكوننّ من الصالحين فلمّا آتاهم من فضله بخلوا به وتولّوا؛ فأعقبهم نفاقًا في قلوبهم؛ فأوفِ بعهدك مع الله؛ فإذا نجّاك الله من شدّةٍ فاشكره وأوفِ بما وعدت؛ ولا تنكث عهدك بعد الفرج؛ فمن وفى بعهدِ الله أتمّ الله عليه نعمته، ومن نكث عاقبه الله؛ فاجعل الوفاءَ بالعهدِ مع الله دأبك؛ فبادر بالوفاءِ بما عاهدت الله عليه؛ فالوفاءُ بالعهدِ من صفاتِ المؤمنين، والنكثُ من صفاتِ المكذّبين."}},{"n":51,"reflection":{"text":"«ونادى فرعون في قومه قال يا قوم أليس لي ملك مصر وهذه الأنهار تجري من تحتي أفلا تبصرون»، ونادى فرعونُ في قومه: يا قومِ أليس لي ملكُ مصرَ وهذه الأنهارُ تجري من تحتي؟ أفلا تبصرون عظمتي؟ ففي هذا اغترارُ فرعونَ بملكه وطغيانه؛ فاحذر الاغترارَ بالملكِ والمالِ والطغيان، فإنه سببُ الهلاك، فلا تغترّ بما آتاك الله، بل اشكره وتواضع، فالاغترارُ بالنعمةِ يورث الطغيان.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الاغترارِ بالملكِ والمال، والتواضعُ وشكرُ النعمة."},"action":{"text":"تأمّل اغترارَ فرعونَ بملكه: ونادى فرعونُ في قومه مفتخرًا متكبّرًا: يا قومِ أليس لي ملكُ مصرَ وسلطانها، وهذه الأنهارُ، أنهارُ النيلِ، تجري من تحتِ قصري وبين يديّ؟ أفلا تبصرون عظمتي وملكي، وضعفَ موسى وفقره؟ «ونادى فرعون في قومه قال يا قوم أليس لي ملك مصر وهذه الأنهار تجري من تحتي أفلا تبصرون»؛ ففي هذا بيانُ اغترارِ فرعونَ بملكه وسلطانه وطغيانه؛ فاغترّ بملكه ومالِه حتى تكبّر وطغى واستخفّ بالحقّ؛ فاحذر الاغترارَ بالملكِ والمالِ والجاهِ والسلطان؛ فإنه سببُ الطغيانِ والهلاك؛ كلا إنّ الإنسانَ ليطغى أن رآه استغنى؛ فلا تغترّ بما آتاك الله من نعمةٍ فتطغى وتتكبّر؛ بل اشكر الله على نعمه، وتواضع له؛ واعلم أنّ النعمَ من الله، وأنها زائلة؛ فمن اغترّ بالنعمةِ وطغى بها أهلكه الله؛ ومن شكرها وتواضع بها زاده الله؛ فاجعل نعمَ الله داعيةً للشكرِ والتواضع، لا للطغيانِ والكبر؛ فالاغترارُ بالنعمةِ يورث الطغيانَ والهلاك؛ فتواضع، واشكر، ولا تغترّ."}},{"n":52,"reflection":{"text":"«أم أنا خير من هذا الذي هو مهين ولا يكاد يبين»: أم أنا خيرٌ من موسى الذي هو حقيرٌ ضعيفٌ ولا يكاد يفصح لعقدةٍ في لسانه؟ ففي هذا احتقارُ فرعونَ لموسى بمقاييسِ الدنيا؛ فاحذر احتقارَ أهلِ الحقِّ لفقرهم أو ضعفهم، فالعبرةُ بالحقِّ لا بالمظهر، فلا تزن الناسَ بمقاييسِ الدنيا، فكم من محتقَرٍ خيرٌ عند الله من عظيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ احتقارِ أهلِ الحقّ، ووزنُ الناسِ بالحقِّ لا بالمظهر."},"action":{"text":"تأمّل احتقارَ فرعونَ لموسى: أم أنا خيرٌ من هذا، موسى، الذي هو مهينٌ حقيرٌ ضعيفٌ في زعمه، ولا يكاد يبينُ ويفصح في كلامه لما كان في لسانه من عقدة؟ فاحتقر موسى لفقره وضعفِه الظاهرِ وعقدةِ لسانه «أم أنا خير من هذا الذي هو مهين ولا يكاد يبين»؛ ففي هذا احتقارُ فرعونَ لموسى بمقاييسِ الدنيا: الفقرِ والضعفِ والمظهر؛ فوزن موسى بميزانِ الدنيا لا بميزانِ الحقّ؛ فاحذر احتقارَ أهلِ الحقِّ والدينِ لفقرهم أو ضعفهم أو مظهرهم؛ فالعبرةُ بالحقِّ والتقوى، لا بالمالِ والجاهِ والمظهر؛ فلا تزن الناسَ بمقاييسِ الدنيا؛ فكم من محتقَرٍ عند الناسِ خيرٌ عند الله من عظيمٍ في أعينهم؛ ربّ أشعثَ أغبرَ مدفوعٍ بالأبوابِ لو أقسم على الله لأبرّه؛ فلا تحتقر أحدًا لفقره أو ضعفه أو مظهره؛ فقد يكون أكرمَ عند الله منك؛ فالميزانُ التقوى؛ إنّ أكرمكم عند الله أتقاكم؛ فوزن الناسَ بميزانِ الحقِّ والتقوى؛ فمن وزنهم بالدنيا ضلّ كفرعون، ومن وزنهم بالتقوى اهتدى؛ فلا تحتقر أهلَ الحق، ولا تعظّم أهلَ الدنيا لدنياهم."}},{"n":53,"reflection":{"text":"«فلولا ألقي عليه أسورة من ذهب أو جاء معه الملائكة مقترنين»: فهلّا أُلقِي على موسى أساورُ من ذهبٍ (علامةَ الملك) أو جاء معه الملائكةُ متتابعين يشهدون له؟ ففي هذا اقتراحُ فرعونَ آياتٍ بمقاييسِ الدنيا؛ فاعلم أنّ صدقَ الرسولِ لا يُعرَف بالزينةِ ولا بالمظاهر، بل بالآياتِ والبراهين، فلا تطلب على الحقِّ دلائلَ دنيويّة، فالحقُّ يُعرَف ببرهانه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ الحقِّ ببرهانه، لا بالمظاهرِ والزينةِ الدنيوية."},"action":{"text":"تأمّل اقتراحَ فرعونَ للآياتِ بمقاييسِ الدنيا: فهلّا أُلقِي على موسى، إن كان صادقًا رسولًا كريمًا على ربه، أساورُ وحليٌّ من ذهبٍ علامةً على الملكِ والسيادة؟ أو جاء معه الملائكةُ متتابعين مقترنين يشهدون له بالرسالةِ ويعاونونه؟ فطلب دلائلَ دنيويّةً على صدقِ موسى «فلولا ألقي عليه أسورة من ذهب أو جاء معه الملائكة مقترنين»؛ ففي هذا اقتراحُ فرعونَ آياتٍ بمقاييسِ الدنيا من الحليِّ والزينةِ والأتباع؛ فظنّ أنّ صدقَ الرسولِ يُعرَف بالزينةِ الدنيويّةِ والمظاهر؛ فاعلم أنّ صدقَ الرسولِ لا يُعرَف بالزينةِ والحليِّ والمظاهرِ الدنيوية؛ بل يُعرَف بالآياتِ والبراهينِ الدالّةِ على صدقه؛ وقد جاء موسى بالآياتِ العظيمة؛ فلا تطلب على الحقِّ دلائلَ دنيويّةً من مالٍ أو جاهٍ أو زينة؛ فالحقُّ يُعرَف ببرهانه ودليله، لا بمظهرِ صاحبه؛ فكم من صاحبِ حقٍّ فقيرٍ ضعيفِ المظهر؛ وكم من صاحبِ باطلٍ غنيٍّ مزيّن؛ فلا تزن الحقَّ بالمظاهرِ الدنيوية؛ بل زِنه ببرهانه ودليله؛ فمن طلب على الحقِّ دلائلَ دنيويّةً ضلّ، ومن عرفه ببرهانه اهتدى؛ فاعرف الحقَّ ببرهانه، لا بزينةِ صاحبه ومظهره."}},{"n":54,"reflection":{"text":"«فاستخف قومه فأطاعوه إنهم كانوا قوما فاسقين»: فاستخفّ فرعونُ عقولَ قومه فأطاعوه في الباطل، إنهم كانوا قومًا فاسقين؛ ففي هذا خطرُ اتّباعِ الطغاةِ في الباطل؛ فاحذر أن تُستَخَفَّ عقلك فتتّبع الباطل، فأعمل عقلك ولا تتّبع أحدًا في الباطل، فاتّباعُ الطغاةِ في الباطلِ فسوقٌ وضلال، فلا تكن ممّن يُستَخَفّ فيطيع الباطل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إعمالُ العقلِ وعدمُ اتّباعِ الطغاةِ في الباطل."},"action":{"text":"تأمّل كيف استخفّ فرعونُ قومه: فاستخفّ فرعونُ عقولَ قومه وحملهم على الطيشِ والخفّة، فأطاعوه فيما دعاهم إليه من الباطلِ والكفرِ وتكذيبِ موسى؛ إنهم كانوا قومًا فاسقين خارجين عن طاعةِ الله، فلذلك أطاعوا فرعونَ في الباطل «فاستخف قومه فأطاعوه إنهم كانوا قوما فاسقين»؛ ففي هذا بيانُ خطرِ اتّباعِ الطغاةِ في الباطل، وأنّ الفسوقَ يحمل على طاعتهم؛ فاستخفّ فرعونُ عقولهم فاتّبعوه في الباطل؛ ولم يعملوا عقولهم في تمييزِ الحقِّ من الباطل؛ فاحذر أن تُستَخَفَّ عقلك فتتّبع الباطلَ والطغاةَ فيه؛ فأعمل عقلك في تمييزِ الحقِّ من الباطل؛ ولا تتّبع أحدًا في الباطلِ ولو كان ذا سلطانٍ وجاه؛ فلا طاعةَ لمخلوقٍ في معصيةِ الخالق؛ فاتّباعُ الطغاةِ والمضلّين في الباطلِ فسوقٌ وضلالٌ وهلاك؛ ولاحظ أنّ فسوقهم وخروجهم عن طاعةِ الله هو الذي حملهم على طاعةِ فرعونَ في الباطل؛ فمن فسق عن أمرِ الله سهُل انقياده للباطل؛ فالزم طاعةَ الله؛ وأعمل عقلك؛ ولا تتّبع الطغاةَ والمضلّين في باطلهم؛ فمن أعمل عقله واتّبع الحقَّ نجا، ومن استُخِفّ فأطاع الباطلَ هلك."}},{"n":55,"reflection":{"text":"«فلما آسفونا انتقمنا منهم فأغرقناهم أجمعين»: فلمّا أغضبونا بكفرهم وطغيانهم انتقمنا منهم فأغرقناهم أجمعين؛ ففي هذا عاقبةُ الطغيانِ والإغضابِ لله؛ فاحذر ما يُغضِب الله من الكفرِ والطغيانِ والمعاصي، فإنه سببُ العذاب، فاتّق الله ولا تُغضِبه، فمن أغضب الله بطغيانه انتقم الله منه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ ممّا يُغضِب الله من الطغيانِ والمعاصي."},"action":{"text":"تأمّل عاقبةَ فرعونَ وقومه: فلمّا آسفونا، أي أغضبونا بإصرارهم على الكفرِ والطغيانِ والتكذيب، انتقمنا منهم، فأغرقناهم أجمعين في البحر؛ فرعونَ وجنودَه كلَّهم «فلما آسفونا انتقمنا منهم فأغرقناهم أجمعين»؛ ففي هذا بيانُ عاقبةِ الطغيانِ والإصرارِ على ما يُغضِب الله؛ فلمّا أغضبوا الله بكفرهم وطغيانهم أهلكهم الله جميعًا؛ فاحذر ما يُغضِب الله من الكفرِ والطغيانِ والمعاصي والإصرارِ عليها؛ فإنّ إغضابَ الله سببُ العذابِ والهلاك؛ فاتّق الله، ولا تُغضِبه بمعصيتك وطغيانك؛ فمن أغضب الله بإصراره على المعاصيِ والطغيانِ انتقم الله منه وأهلكه؛ فالمعاصيُ والطغيانُ تُغضِب الله؛ فاجتنبها؛ واطلب رضا الله بطاعته؛ فمن اتّقى الله ورضي عنه نجا، ومن أغضبه بطغيانه هلك؛ فاحذر أسبابَ غضبِ الله؛ والزم أسبابَ رضاه؛ فرضا الله في طاعته، وغضبه في معصيته؛ فبادر بالطاعةِ والتوبة، واجتنب ما يُغضِب الله؛ فمن أغضب الله فقد عرّض نفسه لانتقامه؛ فاطلب رضا الله، واحذر غضبه."}},{"n":56,"reflection":{"text":"«فجعلناهم سلفا ومثلا للآخرين»: فجعلناهم سلفًا متقدّمين في الهلاك، وعبرةً ومثلًا للآخرين يعتبرون بهم؛ ففي هذا أنّ الهالكين عبرةٌ للباقين؛ فاعتبر بمن هلك من الطغاةِ والمكذّبين، فقد جعلهم الله عبرةً لك، فاتّعظ بهم ولا تسلك سبيلهم، فالهالكون عبرةٌ لمن اعتبر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بالهالكين من الطغاة، والاتّعاظُ بهم."},"action":{"text":"تأمّل ختامَ قصّةِ فرعون: فجعلناهم سلفًا، متقدّمين في الكفرِ والهلاكِ يتبعهم أشباههم، ومثلًا وعبرةً للآخرين يعتبرون بهم ويتّعظون بمصيرهم «فجعلناهم سلفا ومثلا للآخرين»؛ ففي هذا بيانُ أنّ الهالكين من الطغاةِ والمكذّبين عبرةٌ ومثلٌ للباقين؛ فجعل الله فرعونَ وقومه عبرةً لمن بعدهم؛ فاعتبر بمن هلك من الطغاةِ والمكذّبين قبلك؛ فقد جعلهم الله عبرةً ومثلًا لك لتتّعظ؛ فسِر في الأرضِ وانظر كيف كان عاقبةُ المكذّبين والطغاة؛ واتّعظ بمصارعهم؛ ولا تسلك سبيلهم في الكفرِ والطغيانِ والتكذيب؛ فمن اعتبر بالهالكين سلم، ومن سلك سبيلهم هلك مثلهم؛ فاجعل من قصصِ الطغاةِ الهالكين عبرةً تحملك على الإيمانِ والتقوى وترْكِ الطغيان؛ فلقد كان في قصصهم عبرةٌ لأولي الألباب؛ فالهالكون عبرةٌ لمن اعتبر، ومثلٌ لمن اتّعظ؛ فكن ممّن يعتبر بهم ويتّعظ بمصيرهم؛ فبالاعتبارِ بالهالكين تنجو من مصيرهم؛ فاتّعظ، ولا تكن مثلَ الطغاةِ الهالكين."}}]},{"title":"الجدلُ في عيسى، وأنه عبدٌ أنعم الله عليه، وأنه علامةٌ للساعة، والتحذيرُ من الشيطان","range":[57,62],"theme":"ضربُ المشركين عيسى مثلًا للجدلِ وفرحُهم به، وتقريرُ أنه عبدٌ أنعم الله عليه وجعله مثلًا لبني إسرائيلَ لا إلهًا، وأنّ الله قادرٌ على أن يجعل ملائكةً يخلفون، وأنّ عيسى علامةٌ للساعةِ فلا يُشَكّ فيها ويُتّبَع الصراطُ المستقيم، والتحذيرُ من الشيطانِ الذي يصدّ عنه","verses":[{"n":57,"reflection":{"text":"«ولما ضرب ابن مريم مثلا إذا قومك منه يصدون»، ولمّا ضُرِب عيسى ابنُ مريمَ مثلًا (في المجادلة) إذا قومك منه يضجّون ويصيحون فرحًا بالجدل؛ ففي هذا بيانُ جدالِ المشركين بالباطل؛ فاحذر الجدالَ بالباطلِ والفرحَ به، فالجدالُ بالباطلِ من صفاتِ الخصمين، فاطلب الحقَّ لا الغلبةَ في الجدل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الجدالِ بالباطلِ والفرحِ به، وطلبُ الحقِّ لا الغلبة."},"action":{"text":"تأمّل جدالَ المشركين بالباطل: ولمّا ضُرِب عيسى ابنُ مريمَ مثلًا، حين احتجّوا بأنّ عيسى يُعبَد فكيف يُنكَر عليهم عبادةُ الملائكة؟، إذا قومك يا محمدُ منه يصدّون ويضجّون ويرتفعون بالصياحِ فرحًا بجدلهم وظنّهم أنهم غلبوا «ولما ضرب ابن مريم مثلا إذا قومك منه يصدون»؛ ففي هذا بيانُ جدالِ المشركين بالباطل، وفرحهم به؛ فجادلوا بالباطلِ ظنًّا أنهم أفحموا؛ فاحذر الجدالَ بالباطلِ والفرحَ به وطلبَ الغلبةِ فيه؛ فالجدالُ بالباطلِ من صفاتِ الخصمين المعاندين؛ ما ضربوه لك إلا جدلًا بل هم قومٌ خصمون؛ فلا تجادل بالباطلِ لتغلب؛ ولا تفرح بالجدلِ وإفحامِ الخصمِ بالباطل؛ بل اطلب الحقَّ لا الغلبة؛ فالمقصودُ إظهارُ الحقِّ لا الانتصارُ للنفس؛ فمن جادل لإظهارِ الحقِّ محمود، ومن جادل بالباطلِ لطلبِ الغلبةِ مذموم؛ فاجعل غايتك من الحوارِ الوصولَ إلى الحق، لا الغلبةَ والانتصارَ للنفس؛ فالجدالُ بالباطلِ والفرحُ به من صفاتِ المعاندين."}},{"n":58,"reflection":{"text":"«وقالوا أآلهتنا خير أم هو ما ضربوه لك إلا جدلا بل هم قوم خصمون»، وقالوا: أآلهتنا خيرٌ أم عيسى (الذي يُعبَد)؟ ما ضربوا هذا المثلَ إلا جدلًا، بل هم قومٌ خصمون؛ ففي هذا كشفُ باطلِ جدلهم؛ فاحذر الجدالَ الذي غايتُه الخصومةُ لا الحقّ، فالخصومةُ بالباطلِ مذمومة، فاطلب الحقَّ بالإنصافِ لا بالخصومة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الحقِّ بالإنصاف، والحذرُ من الخصومةِ بالباطل."},"action":{"text":"تأمّل كشفَ باطلِ جدلهم: وقالوا محتجّين بالباطل: أآلهتنا خيرٌ أم عيسى؟ فإن كان عيسى يُعبَد ولم يُنكَر، فآلهتنا أولى؛ ما ضربوا لك هذا المثلَ إلا جدلًا وطلبًا للخصومة، لا طلبًا للحق؛ بل هم قومٌ خصمون شديدو الخصومةِ بالباطل «وقالوا أآلهتنا خير أم هو ما ضربوه لك إلا جدلا بل هم قوم خصمون»؛ ففي هذا كشفُ باطلِ جدلهم؛ فجدالهم لم يكن لطلبِ الحقّ، بل للخصومةِ والمغالبةِ بالباطل؛ فقياسهم فاسد: فعيسى عبدٌ صالحٌ لم يرضَ أن يُعبَد، وعبادتُه باطلةٌ كعبادةِ الأصنام؛ فاحذر الجدالَ الذي غايتُه الخصومةُ والمغالبةُ لا الوصولُ إلى الحق؛ فالخصومةُ بالباطلِ مذمومة؛ إنّ أبغضَ الرجالِ إلى الله الألدُّ الخصم؛ فلا تكن خصمًا مجادلًا بالباطل؛ بل اطلب الحقَّ بالإنصافِ والدليل؛ فمن طلب الحقَّ بإنصافٍ اهتدى، ومن خاصم بالباطلِ لطلبِ الغلبةِ ضلّ؛ فاجعل غايتك الحقَّ لا الخصومة؛ وجادل بالتي هي أحسنُ لإظهارِ الحق، لا للمغالبةِ والخصومة."},"qadiyya":{"title":"قضيّةُ شبهةٍ تُقرَّر إلى منتهاها ثمّ تُنقض من وجهين","question":"قال الله: ﴿وَقَالُوا أَآلِهَتُنَا خَيْرٌ أَمْ هُوَ ۚ مَا ضَرَبُوهُ لَكَ إِلَّا جَدَلًا ۚ بَلْ هُمْ قَوْمٌ خَصِمُونَ﴾.\nوسياقُ الآية أنّ عبادةَ ابن مريم نُهي عنها كما نُهي عن عبادة الأصنام، فصاح القومُ وزعموا أنّهم غلبوا.\nوموضعُ الإشكال أنّ **التسوية في النهي تُوهم التسويةَ في المنزلة**، وعيسى نبيٌّ مقرّب.\nفالقضيّة: **ما وجهُ حجّتهم التي فرحوا بها؟** ثمّ: **لِمَ بلغ الإمامُ بها منتهاها قبل أن يردّها؟** ثمّ: **بأيّ شيءٍ انتقضت؟**","background":"ولا يستقيم النظرُ حتى يُفرّق بين الحكم وبين الوصف الذي عُلّق به؛ فلا يصحّ أن يُستدلّ باختلاف المنزلة على اختلاف الحكم، حتى يُنظر في ذلك الوصف: أيعمّ الصورتين أم يخصّ إحداهما؟\nوالمشركون لم ينازعوا في فضل عيسى، بل جعلوا فضلَه مقدّمةً في حجّتهم؛ فهي حجّةٌ **مبناها على ما يُسلّمه الخصم**، وهو أشدُّ ما تُقرَّر به الشبهةُ على قائلها.\nوقاعدتُهم أنّ الحجّة إذا تناقضت بطلت، وهي في نفسها قاعدةٌ صحيحة.","what_happened":"بدأ الإمامُ ببيان المثل المضروب فقال: «أي: نهي عن عبادته، وجعلت عبادته بمنزلة عبادة الأصنام والأنداد».\nثمّ وصف حالَهم عند سماعه: «ويزعمون أنهم قد غلبوا في حجتهم، وأفلجوا».\nثمّ فسّر سؤالهم في هذه الآية: «يعني: عيسى، حيث نهي عن عبادة الجميع، وشورك بينهم بالوعيد على من عبدهم».\n⭐ ثمّ تولّى **بناءَ حجّتهم بألسنتهم**: «ووجه حجتهم الظالمة، أنهم قالوا: قد تقرر عندنا وعندك يا محمد، أن عيسى من عباد الله المقربين، الذين لهم العاقبة الحسنة، فلم سويت بينه وبينها في النهي عن عبادة الجميع؟ فلولا أن حجتك باطلة لم تتناقض».\nوضمّ إليها احتجاجَهم بلفظ ﴿إِنَّكُمْ وَمَا تَعْبُدُونَ مِنْ دُونِ اللَّهِ حَصَبُ جَهَنَّمَ﴾ فقال عنهم: «وهذا اللفظ بزعمهم، يعم الأصنام، وعيسى، فهل هذا إلا تناقض؟»\nثمّ ختم التقرير: «وتناقض الحجة دليل على بطلانها، هذا أنهى ما يقررون به هذه الشبهة».\n⭐ ثمّ حكم عليها ونقضها في نفَسٍ واحد: «من أضعف الشبه وأبطلها، فإن تسوية الله بين النهي عن عبادة المسيح، وبين النهي عن عبادة الأصنام، لأن العبادة حق لله تعالى، لا يستحقها أحد من الخلق، لا الملائكة المقربون، ولا الأنبياء المرسلون، ولا من سواهم من الخلق، فأي شبهة في تسوية النهي عن عبادة عيسى وغيره؟»\nثمّ قال في الموضع الذي يليه: «وليس تفضيل عيسى عليه السلام، وكونه مقربا عند ربه ما يدل على الفرق بينه وبينها في هذا الموضع».\nوأمّا لفظُ الآية الأخرى فأفرد له جوابًا: «فالجواب عنها من ثلاثة أوجه»؛ أنّ ﴿مَا﴾ «اسم لما لا يعقل، لا يدخل فيه المسيح ونحوه»، و«أن الخطاب للمشركين، الذين بمكة وما حولها، وهم إنما يعبدون أصناما وأوثانا ولا يعبدون المسيح»، وأنّ الآية التي بعدها فيها: «فلا شك أن عيسى وغيره من الأنبياء والأولياء، داخلون في هذه الآية».","the_verdict":"فالحاصلُ أنّ الشبهة قُرّرت على منتهى ما يقرّرونها به، ثمّ نُقضت من جهة الحكم ومن جهة اللفظ.\nفأمّا وجهُ حجّتهم فمبناه أنّ **الحكم يتبع المنزلة**؛ فإن اتّحد الحكمُ مع اختلاف المنزلة فذلك تناقض، والمتناقضُ باطل.\n⭐ وأمّا بلوغُه بها منتهاها فقد صرّح به: «أنهى ما يقررون به هذه الشبهة»؛ ولم يعترض على قاعدتهم أنّ تناقض الحجّة دليلُ بطلانها، بل صار النزاعُ في دعوى وقوع التناقض. **وإنّما يُوثق بالنقض إذا سلم البناءُ ممّا يُعترض به.**\nوأمّا الذي انتقضت به فأمران:\nالأوّل: تحريرُ العلّة التي عُلّق بها النهي، وهي أنّ «العبادة حق لله تعالى، لا يستحقها أحد من الخلق»؛ فالحكمُ دائرٌ على استحقاق العبادة، لا على قدر المعبود. وإذا كان المدارُ على الاستحقاق شمل أرفعَ الخلق كما شمل أدناه؛ فلم تنفع رفعةُ عيسى في إخراجه من النهي.\n⭐ والثاني: منعُ دخول عيسى في لفظ ﴿وَمَا تَعْبُدُونَ مِنْ دُونِ اللَّهِ﴾، وفيه أفرد ثلاثة أوجه، منها «أن الخطاب للمشركين، الذين بمكة وما حولها».\nفالأوّلُ دفع دعوى التناقض في الحكم، والثاني دفعها في اللفظ؛ **فالتسويةُ في الحكم لا تقتضي تسويةً في المنزلة**.\nوموضعُ الغلط عند من لم ينتبه أن يقرأ نفيَ الفرق مطلقًا؛ وقد قيّده الإمامُ بقوله: «في هذا الموضع»، فنفى الفرقَ في موضع النهي وحده.\nفمن أسقط القيدَ ظنّ الفضلَ منفيًّا، ومن جعل الفضلَ حجّةً في الحكم وقع فيما وقعوا فيه.","for_you":"فأمّا الذي تخرج به فثلاثة:\nالأوّل: قرّر قولَ مخالفك حتى يرضاه هو. فقبل أن تكتب ردَّك، اعرض تقريرَك على من يقول به؛ فإن استدرك عليك شيئًا فلم تبلغ به منتهاه.\nوالثاني: سلّم من قواعده ما هو صحيح، و**انقل النزاعَ إلى موضعه**. فاكتب في سطرين: القاعدةُ التي نتّفق عليها، والدعوى التي أنازع فيها. فإن لم تفصلهما فأنت تخاصم لا تناظر.\nوالثالث: إذا اشترك شيئان في حكمٍ فاسأل عن علّته قبل أن تنكر. فاكتب العلّة في سطر، ثمّ انظر: أتعمّ الصورتين أم تخصّ إحداهما؟","grade":"ma'thur","source":"تفسيرُ السعديّ للمثل المضروب («أي: نهي عن عبادته»)، ووصفُه حالَ القوم («ويزعمون أنهم قد غلبوا»)، وبناؤُه حجّتَهم بألسنتهم («ووجه حجتهم الظالمة»)، وختمُه تقريرَها («وتناقض الحجة دليل على بطلانها»)، وحكمُه عليها ونقضُه إيّاها («من أضعف الشبه وأبطلها، فإن تسوية الله»)، وقولُه في الموضع التالي («وليس تفضيل عيسى عليه السلام»)، وأوجهُه الثلاثة في جواب اللفظ الآخر («فالجواب عنها من ثلاثة أوجه»): كلُّها بنصّها في تفسير السعديّ (٤٣:٥٧ إلى ٤٣:٥٩).","honesty":"وممّا يجب أن يُقال:\nتفريقُنا في التمهيد بين الحكم والوصف الذي عُلّق به تمهيدٌ منّا لتقريب كلامه، لا نصٌّ له، وإن كان مبنيًّا على تعليله النهيَ بأنّ العبادة حقٌّ لله. ومثلُه تصحيحُنا قاعدةَ أنّ المتناقض باطل.\nوقولُنا إنّ مبنى حجّتهم أنّ الحكم يتبع المنزلة، وإنّها مبنيّةٌ على مقدّمةٍ يُسلّمها الخصم، فاستنباطٌ منّا من صورة الحجّة كما نقلها.\nوقولُنا إنّه لم يعترض على قاعدة التناقض وصفٌ منّا لصنيعه؛ إذ ساقها في حكاية تقريرهم، فلا صرّح بتسليمها ولا بردّها.\nوترتيبُنا النقضَ على أمرين، جهةِ الحكم وجهةِ اللفظ، ترتيبٌ منّا على كلامه في الموضعين. وتسميتُنا الوصفَ الذي عُلّق به النهي علّةً اصطلاحٌ منّا، ولفظُه هو التعليل باللام.\nوقولُنا إنّ النقض لا يُوثق به إلا بعد سلامة البناء، وتشخيصُنا غلطَ من أسقط القيد، والاختباراتُ التي في آخر القضيّة: كلُّه من وضعنا.\nوأمّا استخراجُنا من قيده «في هذا الموضع» أنّه نفى الفرقَ في النهي دون نفي الفضل، فاستنباطٌ منّا من القيد؛ ومن رأى أنّا وسّعنا فليردّه."}},{"n":59,"reflection":{"text":"«إن هو إلا عبد أنعمنا عليه وجعلناه مثلا لبني إسرائيل»: ما عيسى إلا عبدٌ أنعمنا عليه بالنبوّة، وجعلناه آيةً وعبرةً لبني إسرائيل؛ ففي هذا تقريرُ عبوديةِ عيسى ونفيُ الألوهيةِ عنه؛ فاعلم أنّ عيسى عبدٌ لله كسائرِ الأنبياء، فلا تغلُ فيه ولا في غيره، فالغلوُّ في الصالحين شرك، فأنزل الأنبياءَ منزلتهم عبيدًا لله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تقريرُ عبوديةِ عيسى، ونبذُ الغلوِّ في الصالحين."},"action":{"text":"تأمّل تقريرَ عبوديةِ عيسى: ما عيسى ابنُ مريمَ إلا عبدٌ من عبادِ الله، أنعمنا عليه بالنبوّةِ والرسالةِ والآيات، وجعلناه آيةً وعبرةً ومثلًا لبني إسرائيلَ يستدلّون به على قدرةِ الله حيث خلقه من غيرِ أب «إن هو إلا عبد أنعمنا عليه وجعلناه مثلا لبني إسرائيل»؛ ففي هذا تقريرُ عبوديةِ عيسى، ونفيُ الألوهيةِ والبنوّةِ عنه؛ فعيسى عبدٌ لله، ليس إلهًا ولا ابنَ إله؛ فاعلم أنّ عيسى عبدٌ لله كسائرِ الأنبياء، أنعم الله عليه بالنبوّة؛ لن يستنكف المسيحُ أن يكون عبدًا لله؛ فلا تغلُ في عيسى ولا في غيره من الأنبياءِ والصالحين؛ فالغلوُّ في الصالحين ورفعهم فوق منزلتهم شركٌ وضلال؛ لا تطروني كما أطرت النصارى عيسى ابنَ مريم، فإنما أنا عبدٌ فقولوا عبدُ الله ورسوله؛ فأنزل الأنبياءَ والصالحين منزلتهم: عبيدًا لله مكرَّمين، لا آلهةً معبودين؛ فمن غلا في نبيٍّ أو صالحٍ فعبده أو دعاه فقد أشرك؛ فوحّد الله، وأنزل الأنبياءَ منزلة العبودية؛ فهم عبادٌ مكرَّمون، لا يُعبَدون مع الله."}},{"n":60,"reflection":{"text":"«ولو نشاء لجعلنا منكم ملائكة في الأرض يخلفون»، ولو نشاء لجعلنا بدلًا منكم ملائكةً في الأرضِ يخلفون؛ ففي هذا بيانُ قدرةِ الله وأنّ الملائكةَ عبادٌ له؛ فاعلم أنّ الملائكةَ عبادٌ لله يخلقهم كما يشاء، فلا تعبدهم، بل اعبد خالقهم، فالملائكةُ مخلوقون عبادٌ لله، فوحّد خالقهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ خالقِ الملائكة، وإدراكُ أنهم عبادٌ له."},"action":{"text":"تأمّل بيانَ قدرةِ الله: ولو نشاء لأهلكناكم وجعلنا بدلًا منكم ملائكةً في الأرضِ يخلف بعضهم بعضًا، أو يخلفونكم فيها؛ فالله قادرٌ على ذلك «ولو نشاء لجعلنا منكم ملائكة في الأرض يخلفون»؛ ففي هذا بيانُ كمالِ قدرةِ الله، وأنّ الملائكةَ خلقٌ من خلقه يتصرّف فيهم كيف يشاء؛ فالله قادرٌ على أن يخلق من يشاء ويستخلف من يشاء؛ فاعلم أنّ الملائكةَ، الذين زعم المشركون أنهم بناتُ الله وعبدوهم، عبادٌ لله مخلوقون، يخلقهم ويتصرّف فيهم كما يشاء؛ فكيف يُعبَدون وهم عبيدٌ مخلوقون؟ فلا تعبد الملائكةَ ولا غيرهم من المخلوقات؛ بل اعبد خالقهم وخالقك؛ فالملائكةُ عبادٌ مكرَّمون، لا يعصون الله ما أمرهم، ولا يستحقّون العبادة؛ فوحّد الله خالقَ الملائكةِ وخالقَ كلِّ شيء؛ وأخلص له العبادة؛ ولا تصرف شيئًا منها لملَكٍ ولا نبيٍّ ولا وليٍّ ولا صنم؛ فالعبادةُ حقٌّ للخالقِ وحده؛ فمن عبد الملائكةَ أو غيرها من المخلوقاتِ فقد أشرك؛ فوحّد خالقَ الملائكةِ والخلقِ أجمعين."}},{"n":61,"reflection":{"text":"«وإنه لعلم للساعة فلا تمترن بها واتبعون هذا صراط مستقيم»، وإنّ عيسى (بنزولِه آخرَ الزمان) لعلامةٌ للساعة، فلا تشكّوا فيها واتّبعوني، هذا صراطٌ مستقيم؛ ففي هذا أنّ عيسى علامةٌ للساعةِ والأمرُ باتّباعِ الحق؛ فأيقن بالساعةِ ولا تشكّ فيها، واتّبع الصراطَ المستقيم، فاليقينُ بالساعةِ واتّباعُ الحقِّ سبيلُ النجاة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالساعة، واتّباعُ الصراطِ المستقيم."},"action":{"text":"تأمّل بيانَ أنّ عيسى علامةٌ للساعة: وإنّ عيسى، بنزولِه في آخرِ الزمانِ قبل القيامة، لعلمٌ وعلامةٌ من علاماتِ الساعةِ الكبرى، تدلّ على قربها؛ فلا تشكّوا في الساعةِ ولا تمترنّ فيها؛ واتّبعوني فيما جئتكم به من الحق؛ هذا صراطٌ مستقيمٌ موصلٌ إلى الله «وإنه لعلم للساعة فلا تمترن بها واتبعون هذا صراط مستقيم»؛ ففي هذا بيانُ أنّ نزولَ عيسى من علاماتِ الساعة، والأمرُ باليقينِ بها واتّباعِ الحق؛ فنزولُ عيسى آخرَ الزمانِ من أشراطِ الساعةِ الكبرى؛ فأيقن بالساعةِ ولا تشكّ فيها؛ إنّ الساعةَ آتيةٌ لا ريبَ فيها؛ واتّبع الصراطَ المستقيمَ الذي دعا إليه الأنبياء؛ فاليقينُ بالساعةِ واتّباعُ الحقِّ والصراطِ المستقيمِ سبيلُ النجاة؛ فمن أيقن بالساعةِ استعدّ لها؛ ومن اتّبع الصراطَ المستقيمَ اهتدى؛ فاجعل يقينك بالساعةِ حافزًا للعمل؛ واتّبع الحقَّ والصراطَ المستقيم؛ فلا تشكّ في الساعة، ولا تحد عن الصراطِ المستقيم؛ فبهما تُنال النجاة."}},{"n":62,"reflection":{"text":"«ولا يصدنكم الشيطان إنه لكم عدو مبين»، ولا يصرفنّكم الشيطانُ عن الصراطِ المستقيم، إنه لكم عدوٌّ ظاهرُ العداوة؛ ففي هذا التحذيرُ من الشيطانِ الذي يصدّ عن الحق؛ فاحذر الشيطانَ الذي يصدّك عن الصراطِ المستقيم، فهو عدوٌّ مبين، فاتّخذه عدوًّا واستعذ بالله منه، فالشيطانُ يصدّ عن الحق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الشيطانِ الصادِّ عن الحق، واتّخاذُه عدوًّا."},"action":{"text":"تأمّل التحذيرَ من الشيطان: ولا يصدّنّكم ولا يصرفنّكم الشيطانُ عن الصراطِ المستقيمِ واتّباعِ الحق؛ إنه لكم عدوٌّ مبينٌ ظاهرُ العداوة «ولا يصدنكم الشيطان إنه لكم عدو مبين»؛ ففي هذا التحذيرُ من الشيطانِ الذي يصدّ عن الحقِّ والصراطِ المستقيم؛ فالشيطانُ يسعى لصدِّ الناسِ عن الحقِّ والهدى؛ فاحذر الشيطانَ الذي يصدّك عن الصراطِ المستقيمِ واتّباعِ الحق؛ فهو عدوٌّ مبينٌ ظاهرُ العداوة؛ إنّ الشيطانَ لكم عدوٌّ فاتّخذوه عدوًّا؛ فاتّخذه عدوًّا كما هو لك عدوّ؛ ولا تطعه، ولا تتّبع خطواته؛ ولا تدع يا شيطان يصدّك عن الحقِّ والطاعة؛ فاستعذ بالله من الشيطانِ الرجيم؛ وحصّن نفسك بالأذكارِ والطاعات؛ فمن استعاذ بالله أعاذه؛ فالشيطانُ يصدّ عن الحق، ويزيّن الباطل، ويثبّط عن الطاعة؛ فجاهده بطاعةِ الله ومخالفةِ هواه؛ فلا تجعله يصدّك عن صراطِ الله المستقيم؛ فمن أطاع الشيطانَ ضلّ، ومن خالفه اهتدى؛ فاحذره، وخالفه، واستعذ بالله منه."}}]},{"title":"عيسى يدعو إلى التوحيدِ والتقوى، واختلافُ الأحزاب، والأخلّاءُ أعداءٌ إلا المتّقين","range":[63,67],"theme":"مجيءُ عيسى بالبيّناتِ ودعوتُه إلى تقوى الله وطاعتِه وعبادةِ الله وحده صراطًا مستقيمًا، واختلافُ الأحزابِ فيه بالغلوِّ والتفريطِ ووعيدُ الظالمين، وأنّ المكذّبين لا ينتظرون إلا الساعةَ بغتة، وأنّ الأخلّاءَ يومئذٍ بعضهم لبعضٍ عدوٌّ إلا المتّقين","verses":[{"n":63,"reflection":{"text":"«ولما جاء عيسى بالبينات قال قد جئتكم بالحكمة ولأبين لكم بعض الذي تختلفون فيه فاتقوا الله وأطيعون»، ولمّا جاء عيسى بالبيّناتِ قال: جئتكم بالحكمة ولأبيّن لكم بعضَ ما تختلفون فيه، فاتّقوا الله وأطيعون؛ ففي هذا دعوةُ عيسى إلى التقوى والطاعة؛ فاتّق الله وأطع رسوله، فدعوةُ الرسلِ التقوى والطاعة، فاجعل التقوى والطاعةَ منهجك اقتداءً بدعوةِ الرسل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التقوى وطاعةُ الرسول، فذلك دعوةُ الرسلِ جميعًا."},"action":{"text":"تأمّل دعوةَ عيسى: ولمّا جاء عيسى بالبيّناتِ والمعجزاتِ الدالّةِ على صدقه، قال لقومه: قد جئتكم بالحكمة، النبوّةِ والشريعةِ والعلمِ النافع، ولأبيّن لكم بعضَ الذي تختلفون فيه من أمرِ الدين؛ فاتّقوا الله بامتثالِ أمره واجتنابِ نهيه، وأطيعوني فيما أدعوكم إليه «ولما جاء عيسى بالبينات قال قد جئتكم بالحكمة ولأبين لكم بعض الذي تختلفون فيه فاتقوا الله وأطيعون»؛ ففي هذا دعوةُ عيسى إلى تقوى الله وطاعةِ الرسول؛ فكانت دعوته كدعوةِ سائرِ الرسل: التقوى والطاعة؛ فاتّق الله بامتثالِ أوامره واجتنابِ نواهيه؛ وأطع رسولَه فيما جاء به؛ فدعوةُ الرسلِ جميعًا التقوى والطاعة؛ اتّقوا الله وأطيعون؛ فاجعل التقوى وطاعةَ الرسولِ منهجك في حياتك؛ فبالتقوى تتّقي عذابَ الله؛ وبطاعةِ الرسولِ تهتدي إلى الحق؛ فمن اتّقى الله وأطاع رسوله فقد اهتدى؛ ومن أعرض عن التقوى والطاعةِ ضلّ؛ فاقتدِ بدعوةِ الرسلِ في التقوى والطاعة؛ فهي أصلُ دعوتهم وخلاصةُ رسالتهم."}},{"n":64,"reflection":{"text":"«إن الله هو ربي وربكم فاعبدوه هذا صراط مستقيم»: إنّ الله هو ربّي وربّكم فاعبدوه وحده، هذا صراطٌ مستقيم؛ ففي هذا تقريرُ عيسى للتوحيدِ وأنه عبدٌ لله؛ فاعبد الله ربّك وحده، فهو ربُّ الجميع، فالتوحيدُ صراطٌ مستقيم، فأخلص العبادةَ لله، فمن عبد الله وحده فهو على صراطٍ مستقيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ الله وإفرادُه بالعبادة، فهو الصراطُ المستقيم."},"action":{"text":"تأمّل تقريرَ عيسى للتوحيد: قال عيسى لقومه: إنّ الله هو ربّي وربّكم جميعًا، لا ربَّ سواه؛ فاعبدوه وحده لا شريكَ له؛ هذا التوحيدُ وإفرادُ العبادةِ لله صراطٌ مستقيمٌ موصلٌ إلى الله «إن الله هو ربي وربكم فاعبدوه هذا صراط مستقيم»؛ ففي هذا تقريرُ عيسى للتوحيد، وإعلانُه أنه عبدٌ لله لا إله؛ فأعلن عيسى أنّ الله ربّه وربُّ الناسِ جميعًا، وأمرهم بعبادته وحده؛ فردّ بذلك على من غلا فيه وجعله إلهًا أو ابنَ إله؛ فاعبد الله ربّك وربَّ الناسِ أجمعين وحده؛ فهو ربُّ الجميع، خالقهم ورازقهم ومدبّرهم؛ فالتوحيدُ وإفرادُ العبادةِ لله صراطٌ مستقيم؛ فأخلص العبادةَ لله وحده؛ ولا تشرك به شيئًا؛ ولا تغلُ في نبيٍّ ولا صالح؛ فمن عبد الله وحده فهو على صراطٍ مستقيم؛ ومن أشرك به أو غلا في مخلوقٍ ضلّ؛ فاجعل التوحيدَ صراطك المستقيم؛ فاعبد الله وحده، وأخلص له الدين؛ فبالتوحيدِ تسلك الصراطَ المستقيم."}},{"n":65,"reflection":{"text":"«فاختلف الأحزاب من بينهم فويل للذين ظلموا من عذاب يوم أليم»: فاختلف الفرقُ من بعدِ عيسى فيه (فمنهم من غلا ومنهم من كفر)، فويلٌ للظالمين من عذابِ يومٍ أليم؛ ففي هذا ذمُّ الاختلافِ في عيسى ووعيدُ الظالمين؛ فاحذر الغلوَّ والتفريطَ في الحق، والزم الوسطَ الذي جاء به الوحي، فالاختلافُ في الحقِّ ظلمٌ يوجب العذاب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ الوسطِ في الحق، والحذرُ من الغلوِّ والتفريطِ الموجبِ للعذاب."},"action":{"text":"تأمّل اختلافَ الأحزابِ في عيسى: فاختلف الأحزابُ والفرقُ من بعدِ عيسى فيه من بينهم؛ فمنهم من غلا فيه فجعله إلهًا أو ابنَ إله، ومنهم من فرّط فيه فكذّبه واتّهم أمّه؛ والحقُّ أنه عبدُ الله ورسوله؛ فويلٌ وعذابٌ للذين ظلموا بالغلوِّ أو التفريطِ من عذابِ يومٍ أليم «فاختلف الأحزاب من بينهم فويل للذين ظلموا من عذاب يوم أليم»؛ ففي هذا ذمُّ الاختلافِ في عيسى بالغلوِّ أو التفريط، ووعيدُ الظالمين بالعذاب؛ فاختلف الناسُ في عيسى: فريقٌ غلا، وفريقٌ فرّط، والحقُّ الوسط؛ فاحذر الغلوَّ والتفريطَ في الحق؛ والزم الوسطَ العدلَ الذي جاء به الوحي؛ فخيرُ الأمورِ أوساطها؛ فلا تغلُ في نبيٍّ أو صالحٍ فتعبده، ولا تفرّط فيه فتكذّبه؛ بل أنزله منزلته التي أنزله الله إياها؛ فالغلوُّ والتفريطُ كلاهما ظلمٌ وضلال؛ فويلٌ للظالمين الغالين والمفرّطين من عذابِ يومٍ أليم؛ فالزم الوسطَ والعدلَ في الحقِّ اتّباعًا للوحي؛ فمن لزم الوسطَ نجا، ومن غلا أو فرّط ظلم واستحقّ العذاب؛ فكن وسطًا عدلًا في اتّباعِ الحق."}},{"n":66,"reflection":{"text":"«هل ينظرون إلا الساعة أن تأتيهم بغتة وهم لا يشعرون»: هل ينتظر المكذّبون إلا الساعةَ أن تأتيهم فجأةً وهم غافلون؟ ففي هذا التحذيرُ من مباغتةِ الساعة؛ فاستعدّ للساعةِ فإنها تأتي بغتة، فلا تكن من الغافلين الذين تفجؤهم الساعة، بل اعمل لها عملَ المستعدّين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للساعةِ التي تأتي بغتة، وتركُ الغفلة."},"action":{"text":"تأمّل التحذيرَ من مباغتةِ الساعة: هل ينتظر هؤلاء المكذّبون المعرضون إلا الساعةَ، القيامةَ، أن تأتيهم بغتةً وفجأةً، وهم غافلون لا يشعرون بمجيئها ولا يستعدّون لها؟ «هل ينظرون إلا الساعة أن تأتيهم بغتة وهم لا يشعرون»؛ ففي هذا التحذيرُ من مباغتةِ الساعةِ للغافلين؛ فالساعةُ تأتي بغتةً على غفلةٍ من الناس؛ فاستعدّ للساعةِ بالإيمانِ والعملِ الصالحِ والتوبة؛ فإنها تأتي بغتةً وأنت لا تشعر؛ لا تأتيكم إلا بغتة؛ فما ينظرون إلا صيحةً واحدةً تأخذهم وهم يخصّمون؛ فلا تكن من الغافلين الذين تفجؤهم الساعةُ وهم على معصيةٍ أو غفلة؛ بل كن من المستعدّين المتيقّظين؛ فاعمل للساعةِ عملَ من ينتظرها في كلِّ لحظة؛ فالكيّسُ من دان نفسه وعمل لما بعد الموت؛ فبادر بالعملِ الصالحِ والتوبةِ قبل أن تفجأك الساعةُ أو الموت؛ فمن استعدّ للساعةِ لم تضرّه مباغتتها، ومن غفل عنها فُوجِئ بها على غفلة؛ فاجعل الاستعدادَ للساعةِ همّك؛ فإنها آتيةٌ بغتة."}},{"n":67,"reflection":{"text":"«الأخلاء يومئذ بعضهم لبعض عدو إلا المتقين»: الأخلّاءُ على المعصيةِ يومَ القيامةِ بعضهم لبعضٍ عدوّ، إلا المتّقين فخلّتهم باقية؛ ففي هذا أنّ الخلّةَ على غيرِ تقوى تنقلب عداوة؛ فاجعل خلّتك ومحبّتك في الله وعلى التقوى، فالخلّةُ على المعصيةِ تنقلب عداوةً يومَ القيامة، والخلّةُ في الله باقية، فأحبّ في الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"جعلُ الخلّةِ والمحبّةِ في الله وعلى التقوى، فهي الباقية."},"action":{"text":"تأمّل حالَ الأخلّاءِ يومَ القيامة: الأخلّاءُ والأصدقاءُ الذين تخالّوا وتحابّوا على المعصيةِ والباطلِ في الدنيا، يومَ القيامةِ بعضهم لبعضٍ عدوٌّ، يتلاعنون ويتبرّأ بعضهم من بعض؛ إلا المتّقين الذين تخالّوا وتحابّوا في الله وعلى التقوى، فخلّتهم باقيةٌ دائمةٌ تنفعهم «الأخلاء يومئذ بعضهم لبعض عدو إلا المتقين»؛ ففي هذا بيانُ أنّ الخلّةَ والمحبّةَ على غيرِ تقوى تنقلب عداوةً يومَ القيامة، وأنّ الخلّةَ في الله باقية؛ فكلُّ خلّةٍ ومحبّةٍ لم تكن لله وفي الله فمصيرها العداوةُ يومَ القيامة؛ فاجعل خلّتك ومحبّتك وصداقتك في الله وعلى التقوى والطاعة؛ فالخلّةُ على المعصيةِ والباطلِ تنقلب عداوةً وندامةً يومَ القيامة؛ والخلّةُ في الله وعلى التقوى باقيةٌ نافعة؛ يا ليتني لم أتّخذ فلانًا خليلا؛ فأحبّ في الله، وصاحب الأتقياء؛ واحذر مصاحبةَ أهلِ المعصيةِ والباطل؛ فالمتحابّون في الله على منابرَ من نورٍ يومَ القيامة؛ فمن أحبّ في الله وتخالّ عليه نفعته خلّته، ومن أحبّ على المعصيةِ ضرّته؛ فاجعل حبّك وبغضك وخلّتك لله؛ فالحبُّ في الله من أوثقِ عرى الإيمان."}}]},{"title":"بشرى المتّقين بالأمنِ ونعيمِ الجنّةِ الدائم","range":[68,73],"theme":"نداءُ المتّقين بألا خوفَ عليهم ولا حزن، وأنهم الذين آمنوا بآياتِ الله وكانوا مسلمين، وأمرُهم بدخولِ الجنّةِ هم وأزواجهم يُحبَرون، ووصفُ نعيمِها من الصحافِ الذهبيةِ وما تشتهيه الأنفسُ وتلذّ الأعينُ والخلودِ والفواكهِ الكثيرة، وأنها أُورِثوها بأعمالهم","verses":[{"n":68,"reflection":{"text":"«يا عباد لا خوف عليكم اليوم ولا أنتم تحزنون»: يا عبادي المتّقين لا خوفٌ عليكم اليومَ مما تقدمون عليه، ولا أنتم تحزنون على ما تركتم؛ ففي هذا بشرى المتّقين بالأمنِ يومَ القيامة؛ فاعمل عملَ المتّقين لتنال هذه البشرى: الأمنَ من الخوفِ وذهابَ الحزن، فالمتّقون آمنون يومَ القيامة، فاطلب هذا الأمنَ بالتقوى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الأمنِ يومَ القيامةِ بالتقوى، فالمتّقون لا خوفٌ عليهم."},"action":{"text":"تأمّل بشرى المتّقين: يُقال للمتّقين يومَ القيامة: يا عبادي لا خوفٌ عليكم اليومَ مما تقدمون عليه من أهوال، ولا أنتم تحزنون على ما خلّفتم وراءكم من دنيا؛ فأمّنهم الله من الخوفِ والحزن «يا عباد لا خوف عليكم اليوم ولا أنتم تحزنون»؛ ففي هذا بشرى المتّقين بالأمنِ التامِّ يومَ القيامة؛ فينادى المتّقون بهذا النداءِ الكريم؛ فهم آمنون من الخوف، مطمئنّون لا يحزنون؛ ألا إنّ أولياءَ الله لا خوفٌ عليهم ولا هم يحزنون؛ فاعمل عملَ المتّقين لتنال هذه البشرى العظيمة: الأمنَ من الخوفِ وذهابَ الحزن يومَ القيامة؛ فالمتّقون آمنون يومَ الفزعِ الأكبر؛ لا يحزنهم الفزعُ الأكبرُ وتتلقّاهم الملائكة؛ فاطلب هذا الأمنَ والطمأنينةَ بالتقوى؛ فالتقوى سبيلُ الأمنِ يومَ القيامة؛ فاتّق الله بامتثالِ أمره واجتنابِ نهيه؛ لتكون من عبادِ الله المتّقين الذين لا خوفٌ عليهم ولا هم يحزنون؛ فمن اتّقى الله أمّنه يومَ الفزع، وأذهب عنه الحزن؛ فاجعل التقوى زادك لتنال الأمنَ والطمأنينةَ يومَ القيامة."}},{"n":69,"reflection":{"text":"«الذين آمنوا بآياتنا وكانوا مسلمين»: هؤلاء العبادُ المتّقون هم الذين آمنوا بآياتِنا وكانوا مسلمين منقادين لله؛ ففي هذا بيانُ صفةِ الناجين: الإيمانُ والإسلام؛ فآمن بآياتِ الله وكن مسلمًا منقادًا لله، فالنجاةُ بالإيمانِ والانقيادِ لله، فحقّق الإيمانَ والإسلامَ لتكون من الناجين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحقيقُ الإيمانِ والإسلامِ (الانقياد)، فهما صفةُ الناجين."},"action":{"text":"تأمّل صفةَ العبادِ المتّقين الناجين: هم الذين آمنوا بآياتِنا، القرآنيةِ والكونية، تصديقًا وإذعانًا، وكانوا مسلمين منقادين لله بالطاعةِ والاستسلام «الذين آمنوا بآياتنا وكانوا مسلمين»؛ ففي هذا بيانُ صفةِ الناجين يومَ القيامة: الإيمانُ بآياتِ الله، والإسلامُ والانقيادُ له؛ فالمتّقون الذين لا خوفٌ عليهم ولا يحزنون هم الذين جمعوا بين الإيمانِ والإسلام؛ فآمنوا بآياتِ الله، وانقادوا له بالطاعةِ والاستسلام؛ فآمن بآياتِ الله كلِّها؛ وكن مسلمًا منقادًا لله بقلبك وجوارحك؛ فالنجاةُ بالإيمانِ الصادقِ والانقيادِ التامِّ لله؛ فالإيمانُ تصديقٌ بالقلب، والإسلامُ انقيادٌ بالجوارح؛ فاجمع بينهما؛ فمن آمن وأسلم وانقاد لله نجا؛ ومن كذّب أو استكبر هلك؛ فحقّق الإيمانَ بآياتِ الله، والإسلامَ والانقيادَ له؛ فبهما تكون من العبادِ المتّقين الناجين؛ فاجعل قلبك مؤمنًا مصدّقًا، وجوارحك منقادةً مستسلمةً لله؛ فبالإيمانِ والإسلامِ تُنال النجاةُ والبشرى."}},{"n":70,"reflection":{"text":"«ادخلوا الجنة أنتم وأزواجكم تحبرون»: يُقال لهم: ادخلوا الجنّةَ أنتم وأزواجكم مسرورين منعَّمين؛ ففي هذا بشرى المؤمنين بدخولِ الجنّةِ والسرور؛ فاعمل لتدخل الجنّةَ مع أزواجك مسرورًا، فقرّةُ العينِ اجتماعُ المؤمنين وأزواجهم في الجنّةِ في سرور، فاعمل عملَ أهلِ الجنّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لدخولِ الجنّةِ مع الأزواجِ في سرورٍ ونعيم."},"action":{"text":"تأمّل بشرى المؤمنين بدخولِ الجنّة: يُقال للمتّقين المؤمنين المسلمين: ادخلوا الجنّةَ أنتم وأزواجكم المؤمناتُ، أو قرناؤكم في الإيمان، تُحبَرون، أي تُسَرّون وتُنعَّمون وتُكرَمون غايةَ الإكرام «ادخلوا الجنة أنتم وأزواجكم تحبرون»؛ ففي هذا بشرى المؤمنين بدخولِ الجنّةِ مع أزواجهم في سرورٍ ونعيم؛ فيدخلون الجنّةَ مسرورين منعَّمين مع أزواجهم؛ فمن تمامِ نعيمِ الجنّةِ اجتماعُ المؤمنِ بأهله وأحبّائه المؤمنين فيها؛ جنّاتُ عدنٍ يدخلونها ومن صلح من آبائهم وأزواجهم وذرّيّاتهم؛ فاعمل لتدخل الجنّةَ مع أزواجك وأهلك المؤمنين مسرورًا منعَّمًا؛ فقرّةُ العينِ اجتماعُ المؤمنين وأزواجهم في الجنّةِ في سرورٍ دائم؛ فاحرص على صلاحك وصلاحِ أهلك لتُجمَعوا في الجنّة؛ فاعمل عملَ أهلِ الجنّةِ من الإيمانِ والتقوى والطاعة؛ وربِّ أهلك على ذلك؛ فمن آمن وعمل صالحًا وأصلح أهله دخل الجنّةَ معهم مسرورًا؛ فاطلب هذا النعيمَ العظيمَ بالعملِ الصالحِ لك ولأهلك."}},{"n":71,"reflection":{"text":"«يطاف عليهم بصحاف من ذهب وأكواب وفيها ما تشتهيه الأنفس وتلذ الأعين وأنتم فيها خالدون»: يُطاف عليهم بأطباقٍ من ذهبٍ وأكوابٍ، وفيها ما تشتهيه الأنفسُ وتلذّ الأعين، وأنتم فيها خالدون؛ ففي هذا وصفُ نعيمِ الجنّةِ الكامل؛ فاعمل لهذا النعيمِ الدائم الذي فيه ما تشتهي وتلذّ، فنعيمُ الجنّةِ كاملٌ دائم، فاطلبه بالعملِ الصالح.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ للنعيمِ الكاملِ الدائمِ في الجنّة، فيه ما تشتهي وتلذّ."},"action":{"text":"تأمّل وصفَ نعيمِ الجنّةِ الكامل: يُطاف على أهلِ الجنّةِ بصحافٍ، أطباقٍ، من ذهبٍ فيها الطعام، وأكوابٍ فيها الشراب؛ وفي الجنّةِ ما تشتهيه الأنفسُ من اللذّاتِ، وما تلذّ الأعينُ من المناظرِ والزينة؛ وأنتم فيها خالدون لا تخرجون ولا تموتون «يطاف عليهم بصحاف من ذهب وأكواب وفيها ما تشتهيه الأنفس وتلذ الأعين وأنتم فيها خالدون»؛ ففي هذا وصفُ نعيمِ الجنّةِ الكاملِ الدائم؛ فأهلها يُخدَمون بآنيةِ الذهب؛ ولهم فيها كلُّ ما تشتهيه أنفسهم وتلذّ أعينهم؛ وهم فيها خالدون؛ فاعمل لهذا النعيمِ الكاملِ الدائمِ الذي فيه ما تشتهي النفوسُ وتلذّ الأعين؛ فنعيمُ الجنّةِ كاملٌ لا نقصَ فيه، دائمٌ لا انقطاعَ له؛ لهم فيها ما يشاؤون خالدين؛ فاطلب هذا النعيمَ بالإيمانِ والعملِ الصالح؛ فمن عمل عملَ أهلِ الجنّةِ نالها؛ فارفع همّتك إلى هذا النعيمِ العظيم؛ واعمل له عملَ المشتاقين؛ فما عند الله خيرٌ وأبقى؛ فاعمل للنعيمِ الدائمِ الكامل، لا للمتاعِ الزائلِ الناقص؛ فمن اشتاق إلى الجنّةِ سارع في الخيرات."}},{"n":72,"reflection":{"text":"«وتلك الجنة التي أورثتموها بما كنتم تعملون»، وتلك الجنّةُ التي أُورِثتموها بسببِ أعمالكم الصالحة؛ ففي هذا أنّ الجنّةَ تُنال بالعملِ الصالح؛ فاعمل صالحًا لترث الجنّة، فالجنّةُ جزاءُ العملِ الصالحِ برحمةِ الله، فاجتهد في العملِ الصالحِ لترث الجنّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ الصالحُ لوراثةِ الجنّة، فهي جزاؤه برحمةِ الله."},"action":{"text":"تأمّل بيانَ سببِ نيلِ الجنّة: وتلك الجنّةُ العظيمةُ التي أُورِثتموها وأُعطيتموها بسببِ ما كنتم تعملون من الأعمالِ الصالحةِ في الدنيا «وتلك الجنة التي أورثتموها بما كنتم تعملون»؛ ففي هذا بيانُ أنّ الجنّةَ تُنال بالعملِ الصالحِ برحمةِ الله؛ فالجنّةُ جزاءُ الأعمالِ الصالحةِ، تُورَث بها كما يُورَث المالُ بالسبب؛ ونودوا أن تلكم الجنّةُ أورثتموها بما كنتم تعملون؛ فاعمل صالحًا لترث الجنّة؛ فالعملُ الصالحُ سببُ دخولِ الجنّةِ برحمةِ الله؛ فلا تدخل الجنّةَ بمجرّدِ العملِ إلا برحمةِ الله، لكنّ العملَ سببٌ؛ ادخلوا الجنّةَ بما كنتم تعملون؛ فاجتهد في العملِ الصالحِ لترث الجنّة؛ فمن عمل صالحًا مع الإيمانِ ورثها؛ ومن فرّط حُرِمها؛ فاجعل العملَ الصالحَ سبيلك إلى الجنّة؛ واعمل عملَ أهلها من الإيمانِ والتقوى والطاعة؛ فالجنّةُ سلعةُ الله الغالية؛ لا تُنال إلا بالعملِ الصالحِ ورحمةِ الله؛ فبادر بالأعمالِ الصالحةِ لترث جنّاتِ النعيم؛ فمن عمل لها نالها بإذنِ الله."}},{"n":73,"reflection":{"text":"«لكم فيها فاكهة كثيرة منها تأكلون»: لكم في الجنّةِ فاكهةٌ كثيرةٌ متنوّعةٌ منها تأكلون؛ ففي هذا تمامُ نعيمِ الجنّة؛ فاعمل لهذا النعيمِ من الفواكهِ الكثيرة، فنعيمُ الجنّةِ متنوّعٌ دائم، فاطلبه بالعملِ الصالح، فالجنّةُ فيها ما لا عينٌ رأت ولا أذنٌ سمعت.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ المتنوّع، فاطلبه بالعملِ الصالح."},"action":{"text":"تأمّل تمامَ نعيمِ الجنّة: لكم أيها المؤمنون في الجنّةِ فاكهةٌ كثيرةٌ متنوّعةٌ من كلِّ صنف، منها تأكلون ما تشتهون بلا نفادٍ ولا انقطاع «لكم فيها فاكهة كثيرة منها تأكلون»؛ ففي هذا تمامُ نعيمِ الجنّةِ من الفواكهِ الكثيرةِ المتنوّعة؛ وفاكهةٍ كثيرةٍ لا مقطوعةٍ ولا ممنوعة؛ فأهلها يأكلون من فواكهها المتنوّعةِ ما يشتهون؛ فاعمل لهذا النعيمِ المتنوّعِ الدائم؛ فنعيمُ الجنّةِ متنوّعٌ لا يملّه أهله، دائمٌ لا ينقطع؛ فاطلبه بالإيمانِ والعملِ الصالح؛ فالجنّةُ فيها ما لا عينٌ رأت ولا أذنٌ سمعت ولا خطر على قلبِ بشر؛ فما وصفه الله من نعيمها أدنى مما أعدّه لعباده؛ فارفع همّتك إلى نعيمِ الجنّة؛ واعمل له عملَ المشتاقين إليها؛ فمن عمل عملَ أهلِ الجنّةِ نال نعيمها؛ فبادر بالعملِ الصالحِ لتنال هذا النعيمَ المتنوّعَ الدائم؛ فالعملُ الصالحُ سبيلُ نعيمِ الجنّة؛ فاجتهد فيه لتفوز بجنّاتِ النعيم."}}]},{"title":"عذابُ المجرمين وخلودهم ويأسُهم، وأنّ الله جاءهم بالحقِّ فكرهوه، وأنّ كيدَ الله أعظم","range":[74,80],"theme":"خلودُ المجرمين في عذابِ جهنمَ الذي لا يُفتَّر وهم فيه آيسون، وأنّ الله لم يظلمهم بل ظلموا أنفسهم، ونداؤهم مالكًا ليقضيَ عليهم فيُخبَرون أنهم ماكثون، وأنّ الله جاءهم بالحقِّ ولكن أكثرهم للحقِّ كارهون، وأنّ كيدَ الله أعظمُ من كيدهم وأنه يسمع سرّهم ونجواهم ورسله يكتبون","verses":[{"n":74,"reflection":{"text":"«إن المجرمين في عذاب جهنم خالدون»: إنّ المجرمين (الكافرين) في عذابِ جهنمَ خالدون؛ ففي هذا بيانُ خلودِ المجرمين في النار؛ فاحذر الإجرامَ والكفرَ الذي عاقبتُه الخلودُ في النار، فاعمل لتنجو من عذابِ جهنم، فالمجرمون خالدون في العذاب، فاجتنب أسبابه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الإجرامِ الموجبِ للخلودِ في النار، والعملُ للنجاة."},"action":{"text":"تأمّل عاقبةَ المجرمين، مقابلَ نعيمِ المؤمنين: إنّ المجرمين، الكافرين المصرّين على الكفرِ والإجرام، في عذابِ جهنمَ خالدون ماكثون أبدًا لا يخرجون منها «إن المجرمين في عذاب جهنم خالدون»؛ ففي هذا بيانُ خلودِ المجرمين الكافرين في عذابِ النار؛ فبعد أن وصف نعيمَ أهلِ الجنّةِ الدائم، ذكر عذابَ أهلِ النارِ الدائم؛ ليختار العبدُ لنفسه؛ فاحذر الإجرامَ والكفرَ والإصرارَ على المعاصي الذي عاقبتُه الخلودُ في النار؛ فالمجرمون المصرّون على الكفرِ خالدون في العذاب؛ فاعمل لتنجو من عذابِ جهنمَ الدائم؛ باجتنابِ أسبابه من الكفرِ والإجرامِ والمعاصي؛ والزم أسبابَ النجاةِ من الإيمانِ والتقوى والطاعة؛ فمن آمن واتّقى نجا من النار، ومن كفر وأجرم خلد فيها؛ فاختر لنفسك أيَّ الدارين تريد: جنّةَ النعيمِ الدائم، أم عذابَ جهنمَ الخالد؟ فاعمل عملَ أهلِ الجنّة؛ واجتنب عملَ أهلِ النار؛ فالنجاةُ في الإيمانِ والتقوى، والهلاكُ في الكفرِ والإجرام؛ فبادر بالإيمانِ والعملِ الصالحِ لتنجو من عذابِ النارِ الخالد."}},{"n":75,"reflection":{"text":"«لا يفتر عنهم وهم فيه مبلسون»: لا يُخفَّف عنهم العذابُ، وهم فيه آيسون من الرحمة؛ ففي هذا شدّةُ عذابِ النارِ ودوامه؛ فاحذر عذابَ النارِ الذي لا يُخفَّف ولا رجاءَ معه، فاعمل لتنجو منه، فعذابُ النارِ دائمٌ لا فتورَ فيه، فبادر بالطاعةِ قبل فواتِ الأوان.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عذابِ النارِ الدائمِ الذي لا يُخفَّف، والمبادرةُ بالطاعة."},"action":{"text":"تأمّل شدّةَ عذابِ النارِ ودوامه: لا يُفتَّر ولا يُخفَّف عن المجرمين العذابُ ساعةً واحدة؛ وهم فيه مبلسون آيسون من الرحمةِ والخروج، قد انقطع رجاؤهم «لا يفتر عنهم وهم فيه مبلسون»؛ ففي هذا بيانُ شدّةِ عذابِ النارِ ودوامه، ويأسِ أهلها من الرحمة؛ فعذابهم دائمٌ لا يُخفَّف، وهم آيسون من كلِّ خير؛ كلّما خبت زدناهم سعيرًا؛ لا يُقضى عليهم فيموتوا ولا يُخفَّف عنهم من عذابها؛ فاحذر عذابَ النارِ الذي لا يُخفَّف ولا فتورَ فيه ولا رجاءَ معه؛ فاعمل لتنجو منه؛ فتصوّرُ عذابِ النارِ الدائمِ الذي لا يُخفَّف يبعث على التوبةِ والعمل؛ فمن تذكّر هذا العذابَ هان عليه تركُ المعاصي؛ فبادر بالطاعةِ والتوبةِ قبل فواتِ الأوان؛ فاعمل في زمنِ المهلةِ لتنجو من عذابِ النارِ الذي لا فتورَ فيه؛ فالسعيدُ من عمل لينجو، والشقيُّ من فرّط فوقع في العذابِ الدائم؛ فاجعل خوفَ هذا العذابِ حافزًا لك على الطاعةِ والتوبة؛ فبادر بالإيمانِ والعملِ الصالحِ لتنجو من عذابٍ لا يُخفَّف ولا ينقطع."}},{"n":76,"reflection":{"text":"«وما ظلمناهم ولكن كانوا هم الظالمين»، وما ظلمناهم بعذابهم، ولكن كانوا هم الظالمين لأنفسهم بالكفرِ والمعاصي؛ ففي هذا تقريرُ عدلِ الله ونفيُ الظلمِ عنه؛ فاعلم أنّ الله عدلٌ لا يظلم، وأنّ العبدَ هو الذي يظلم نفسه بالمعاصي، فاتّق الله ولا تظلم نفسك، فما ظلمهم الله ولكن ظلموا أنفسهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ عدلِ الله، وأنّ العبدَ يظلم نفسه بالمعاصي."},"action":{"text":"تأمّل تقريرَ عدلِ الله: وما ظلمنا هؤلاء المجرمين بعذابهم في النار، ولكن كانوا هم الظالمين لأنفسهم بالكفرِ والشركِ والمعاصيِ والإصرارِ عليها؛ فبظلمهم أنفسهم استحقّوا العذاب «وما ظلمناهم ولكن كانوا هم الظالمين»؛ ففي هذا تقريرُ عدلِ الله ونفيُ الظلمِ عنه؛ فالله لا يظلم أحدًا مثقالَ ذرّة؛ وإنما العبادُ هم الذين يظلمون أنفسهم بالكفرِ والمعاصي فيستحقّون العذاب؛ فاعلم أنّ الله عدلٌ لا يظلم؛ إنّ الله لا يظلم الناسَ شيئًا ولكنّ الناسَ أنفسهم يظلمون؛ وما ظلمناهم ولكن كانوا أنفسهم يظلمون؛ فما عُذّب من عُذّب إلا بظلمِ نفسه بالكفرِ والمعاصي؛ فاتّق الله، ولا تظلم نفسك بالمعاصيِ والذنوبِ فتستحقّ العذاب؛ فالمعصيةُ ظلمٌ للنفس؛ ومن يفعل ذلك فقد ظلم نفسه؛ فاعمل صالحًا، ولا تظلم نفسك بالكفرِ والمعاصي؛ فمن ظلم نفسه بالمعاصيِ عُذّب بعدلِ الله؛ ومن اتّقى الله ولم يظلم نفسه نجا؛ فأحسن إلى نفسك بالطاعة، ولا تظلمها بالمعصية؛ فالله عدلٌ لا يظلم، والعبدُ هو الذي يظلم نفسه."}},{"n":77,"reflection":{"text":"«ونادوا يا مالك ليقض علينا ربك قال إنكم ماكثون»، ونادى أهلُ النارِ خازنها: يا مالكُ ليمِتنا ربّك لنستريح، قال: إنكم ماكثون في العذابِ لا تخرجون؛ ففي هذا شدّةُ عذابِ النارِ حتى يتمنّون الموت؛ فاحذر عذابًا يتمنّى أهله الموتَ فلا يُجابون، فاعمل لتنجو منه، فعذابُ النارِ لا خلاصَ منه، فبادر بالطاعة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عذابٍ يتمنّى أهله الموت، والمبادرةُ بالعملِ للنجاة."},"action":{"text":"تأمّل شدّةَ عذابِ النار: ونادى أهلُ النارِ مالكًا خازنَ النار: يا مالكُ ليقضِ علينا ربّك، أي ليمِتنا فنستريح من العذاب؛ فأجابهم بعد ألفِ عام: إنكم ماكثون في العذابِ خالدون لا تخرجون ولا تموتون «ونادوا يا مالك ليقض علينا ربك قال إنكم ماكثون»؛ ففي هذا بيانُ شدّةِ عذابِ النارِ حتى يتمنّى أهله الموتَ ولا يُجابون؛ فبلغ بهم العذابُ أن تمنّوا الموتَ ليستريحوا؛ لا يُقضى عليهم فيموتوا ولا يُخفَّف عنهم من عذابها؛ وينادون يا مالكُ ليقضِ علينا ربّك؛ فاحذر عذابًا يتمنّى أهله الموتَ فلا يُجابون؛ فاعمل لتنجو من هذا العذابِ الذي لا خلاصَ منه؛ فتصوّرُ هذا العذابِ يبعث على التوبةِ والعمل؛ فبادر بالإيمانِ والطاعةِ والتوبةِ قبل فواتِ الأوان؛ فمن عمل في الدنيا نجا، ومن فرّط صار إلى عذابٍ يتمنّى معه الموتَ فلا يجده؛ فاجعل من هذا المشهدِ حافزًا للعملِ والتوبة؛ فالسعيدُ من عمل لينجو من هذا العذاب."}},{"n":78,"reflection":{"text":"«لقد جئناكم بالحق ولكن أكثركم للحق كارهون»: لقد جئناكم بالحقِّ على ألسنِ الرسل، ولكن أكثركم للحقِّ كارهون؛ ففي هذا بيانُ أنّ سببَ هلاكهم كراهةُ الحق؛ فاحذر كراهةَ الحقّ، فإنها سببُ الهلاك، فأحبّ الحقَّ واقبله، فمن كره الحقَّ هلك، ومن أحبّه واتّبعه نجا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"محبّةُ الحقِّ وقبولُه، والحذرُ من كراهته الموجبةِ للهلاك."},"action":{"text":"تأمّل بيانَ سببِ هلاكِ المجرمين: يُقال لهم أو يقول الله: لقد جئناكم بالحقِّ الواضحِ على ألسنِ الرسلِ وفي الكتب، ولكن أكثركم للحقِّ كارهون، فلذلك أعرضتم عنه وهلكتم «لقد جئناكم بالحق ولكن أكثركم للحق كارهون»؛ ففي هذا بيانُ أنّ سببَ هلاكِ المجرمين كراهتهم للحقّ؛ فما هلكوا لعدمِ مجيءِ الحق، بل لكراهتهم له وإعراضهم عنه؛ فاحذر كراهةَ الحقِّ وبغضه؛ فإنّ كراهةَ الحقِّ سببُ الهلاكِ والعذاب؛ ذلك بأنهم كرهوا ما أنزل الله فأحبط أعمالهم؛ فأحبّ الحقَّ واقبله وإن خالف هواك؛ فالمؤمنُ يحبّ الحقَّ ويتّبعه ولو كان مرًّا؛ والكافرُ يكره الحقَّ ويعرض عنه؛ فراقب قلبك: هل تحبّ الحقَّ أم تكرهه؟ فإن وجدت في نفسك كراهةً للحقِّ فعالجها؛ واحمل نفسك على محبّةِ الحقِّ وقبوله؛ فمن أحبّ الحقَّ واتّبعه نجا؛ ومن كرهه وأعرض عنه هلك؛ فاجعل قلبك محبًّا للحقّ، قابلًا له، متّبعًا له؛ فمحبّةُ الحقِّ وقبولُه من علاماتِ الإيمانِ والنجاة."}},{"n":79,"reflection":{"text":"«أم أبرموا أمرا فإنا مبرمون»: بل أأحكم المشركون أمرًا وكيدًا للنبيّ، فإنا محكمون أمرًا وكيدًا لهم؟ ففي هذا أنّ كيدَ الله أعظمُ من كيدِ المكذّبين؛ فاعلم أنّ كيدَ الله فوق كلِّ كيد، فلا تخف كيدَ الكائدين، فمن كاده الله لا يفلت، فالجأ إلى الله وثق بأنه يبطل كيدَ الكائدين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بأنّ كيدَ الله فوق كلِّ كيد، وعدمُ الخوفِ من الكائدين."},"action":{"text":"تأمّل بيانَ أنّ كيدَ الله أعظم: أم أبرم المشركون وأحكموا أمرًا وكيدًا لإبطالِ الحقِّ وإهلاكِ النبيّ؟ فإنا مبرمون ومحكمون أمرًا وكيدًا لهم أعظمَ من كيدهم «أم أبرموا أمرا فإنا مبرمون»؛ ففي هذا بيانُ أنّ كيدَ الله أعظمُ وأقوى من كيدِ المكذّبين؛ فمهما دبّروا وكادوا، فإنّ الله يدبّر ويكيد لهم أعظمَ من كيدهم؛ ويمكرون ويمكر الله والله خيرُ الماكرين؛ فاعلم أنّ كيدَ الله فوق كلِّ كيد؛ فلا يفوته كائد، ولا يفلت من كيده ماكر؛ فلا تخف كيدَ الكائدين ومكرَ الماكرين ما دمت على الحق؛ فمن كاده الله وأراد إهلاكه لا يفلت؛ ولا يحيق المكرُ السيّئُ إلا بأهله؛ فالجأ إلى الله، وثق بأنه يبطل كيدَ الكائدين ويردّه في نحورهم؛ فالله يتولّى الصالحين؛ فمن توكّل على الله كفاه كيدَ أعدائه؛ فاثبت على الحق، ولا تخف كيدَ المكذّبين؛ فإنّ كيدَ الله لهم أعظمُ من كيدهم؛ فالعاقبةُ للحقِّ وأهله، والخيبةُ لأهلِ الكيدِ والمكر."}},{"n":80,"reflection":{"text":"«أم يحسبون أنا لا نسمع سرهم ونجواهم بلى ورسلنا لديهم يكتبون»: أيحسبون أنّا لا نسمع سرّهم ونجواهم؟ بلى نسمع، ورسلنا (الملائكة) لديهم يكتبون؛ ففي هذا بيانُ إحاطةِ علمِ الله وكتابةِ الملائكة؛ فراقب الله في سرّك ونجواك، فإنّ الله يسمع كلَّ شيء، والملائكةُ تكتب، فاحفظ سرّك ونجواك من المعصية، فالله سميعٌ والملائكةُ كاتبون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"مراقبةُ الله في السرِّ والنجوى، فهو سميعٌ والملائكةُ كاتبون."},"action":{"text":"تأمّل بيانَ إحاطةِ علمِ الله وسمعه: أم يحسب هؤلاء المشركون أنّا لا نسمع سرّهم، ما يُسِرّونه في أنفسهم، ونجواهم، ما يتناجون به سرًّا؟ بلى نسمع ذلك كلَّه، ورسلنا من الملائكةِ الحفظةِ لديهم يكتبون كلَّ ما يقولون ويفعلون «أم يحسبون أنا لا نسمع سرهم ونجواهم بلى ورسلنا لديهم يكتبون»؛ ففي هذا بيانُ إحاطةِ علمِ الله وسمعه بالسرِّ والنجوى، وكتابةِ الملائكةِ لأعمالِ العباد؛ فالله يسمع كلَّ سرٍّ ونجوى، لا يخفى عليه شيء؛ والملائكةُ تكتب كلَّ قولٍ وعمل؛ فراقب الله في سرّك وعلانيتك، ونجواك وجهرك؛ فإنّ الله يسمع كلَّ ما تُسِرّ وتُعلِن؛ ما يكون من نجوى ثلاثةٍ إلا هو رابعهم؛ ألا حين يستغشون ثيابهم يعلم ما يسرّون وما يعلنون؛ واعلم أنّ الملائكةَ الحفظةَ يكتبون كلَّ أقوالك وأعمالك؛ ما يلفظ من قولٍ إلا لديه رقيبٌ عتيد؛ وإنّ عليكم لحافظين كرامًا كاتبين؛ فراقب الله في سرّك ونجواك؛ واحفظ لسانك وقلبك من المعصية؛ فالله سميعٌ يسمع، والملائكةُ كاتبون يكتبون؛ فمن راقب الله في سرّه استقام؛ فاجعل سرّك ونجواك في طاعةِ الله."}}]},{"title":"تنزيهُ الله عن الولد، والأمرُ بالإعراضِ عن الخائضين، وختامُ التوحيدِ والصفح","range":[81,89],"theme":"تنزيهُ الله عن الولدِ وأنه محال، وتسبيحُ ربِّ السماواتِ والأرضِ والعرشِ عمّا يصفون، والأمرُ بتركهم يخوضون حتى يلاقوا يومهم، وأنه الإلهُ في السماءِ والأرضِ الحكيمُ العليمُ الذي له الملكُ وعنده علمُ الساعة، وأنّ الشفاعةَ لمن شهد بالحق، وإقرارُهم بأنّ الله خلقهم، وشكوى النبيِّ حالَهم إلى الله، والأمرُ بالصفحِ عنهم وأنهم سوف يعلمون","verses":[{"n":81,"reflection":{"text":"«قل إن كان للرحمن ولد فأنا أول العابدين»: قل: لو كان للرحمنِ ولدٌ (على الفرضِ المحال) لكنت أوّلَ العابدين لله المنزّهِ عن ذلك (أو أوّلَ الآنفين المنكرين)؛ ففي هذا تنزيهُ الله عن الولدِ بأبلغِ عبارة؛ فنزّه الله عن الولد، فهو محالٌ في حقّه، فوحّد الله ونزّهه عن كلِّ ما لا يليق به، فالولدُ محالٌ على الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله عن الولد، وإدراكُ استحالته في حقّه."},"action":{"text":"تأمّل تنزيهَ الله عن الولد: قل يا محمدُ: إن كان للرحمنِ ولدٌ، على سبيلِ الفرضِ المحال، فأنا أوّلُ العابدين لله على ذلك، أي أوّلُ من يعبده وحده وينزّهه؛ وقيل: فأنا أوّلُ الآنفين المنكرين لذلك؛ فالمعنى نفيُ الولدِ وتنزيهُ الله عنه «قل إن كان للرحمن ولد فأنا أول العابدين»؛ ففي هذا تنزيهُ الله عن الولدِ بأبلغِ عبارةٍ وأقوى حجّة؛ فالولدُ محالٌ في حقِّ الله؛ فلو كان، وهو محال، لكان النبيُّ أوّلَ من يعبده وينزّهه؛ فنزّه الله عن الولدِ والصاحبةِ والشريك؛ فهو الأحدُ الصمدُ الذي لم يلد ولم يولد؛ لم يتّخذ صاحبةً ولا ولدًا؛ فالولدُ محالٌ على الله؛ لأنه يستلزم الحاجةَ والمشابهةَ والمجانسة، والله الغنيُّ المنزّهُ عن ذلك؛ فوحّد الله، ونزّهه عن كلِّ ما لا يليق بجلاله؛ فعظّمه، ونزّهه، وأخلص له العبادة؛ فمن عرف عظمةَ الله نزّهه عن الولدِ وكلِّ نقص؛ فاجعل قلبك موحّدًا منزّهًا لله."},"qadiyya":{"title":"قضيّةُ الاحتجاج بالتزام الفرض","question":"قال الله: ﴿قُلْ إِنْ كَانَ لِلرَّحْمَٰنِ وَلَدٌ فَأَنَا أَوَّلُ الْعَابِدِينَ﴾.\nفظاهرُ اللفظ **تعليقُ عبادةٍ على شرط**، والمتكلّمُ هو الذي بُعث بنفي الولد.\nفالقضيّة: كيف صار هذا اللفظُ حجّةً على المشركين وهو في صورة التسليم لهم؟ ثمّ: لماذا عُلّقت المسألةُ بالنبيّ دون سائر الخلق؟ ثمّ: على أيّ شيءٍ يقوم لزومُها، وعند من تعظُم؟","background":"ولا يتبيّن وجهُ هذا حتى يُفرّق بين أمرين:\nفتعليقُ الشيء على الشرط **لا يقتضي وقوعَه ولا إمكانَه**؛ فقد يُعلَّق على المحال ليُعلم من انتفاء اللازم انتفاءُ الملزوم.\nوالخصمُ يُلزَم من جهة ما لو سلّمناه له؛ **فيُفرض قولُه ثابتًا، ثمّ يُنظر ماذا يترتّب عليه**.\nفإذا اجتمع هذان صار الفرضُ طريقًا إلى الإبطال، لا إقرارًا بالمفروض.\nوالحجّةُ ها هنا موجّهةٌ إلى من جعل لله ولدًا، ومستندُها معرفةُ المخاطَبين بحال المتكلّم.","what_happened":"بدأ السعديُّ ببيان المخاطَبين بهذا القول: «أي: قل يا أيها الرسول الكريم، للذين جعلوا لله ولدا»، ووصف الربَّ في مقابلة دعواهم: «وهو الواحد الأحد الفرد الصمد، الذي لم يتخذ صاحبة ولا ولدا».\nثمّ قدّر متعلَّق العبادة وعلّل التقدير في سياقٍ واحد: «لذلك الولد، لأنه جزء من والده».\n⭐ ثمّ أخبر عن حال النبيّ **بأمرين متقابلين**: «وأنا أول الخلق انقيادا للأمور المحبوبة لله، ولكني أول المنكرين لذلك، وأشدهم له نفيا»، ثمّ رتّب بالفاء: «فعلم بذلك بطلانه».\nثمّ وصف الاحتجاج وموضعَ ظهوره: «فهذا احتجاج عظيم عند من عرف أحوال الرسل».\nثمّ قرّر ما يُعرف من أحوالهم: «وأنه إذا علم أنهم أكمل الخلق، وأن كل خير فهم أول الناس سبقا إليه وتكميلا له، وكل شر فهم أول الناس تركا له وإنكارا له وبعدا منه».\nثمّ فرّع عليه: «فلو كان على هذا للرحمن ولد وهو الحق، لكان محمد بن عبد الله، أفضل الرسل أول من عبده، ولم يسبقه إليه المشركون».\n⭐ ثمّ ذكر وجهًا آخر بصيغة الاحتمال: «ويحتمل أن معنى الآية: لو كان للرحمن ولد، فأنا أول العابدين لله، ومن عبادتي لله، إثبات ما أثبته، ونفي ما نفاه»، وسمّى هذا الضرب: «فهذا من العبادة القولية الاعتقادية»، ثمّ رتّب عليه: «ويلزم من هذا، لو كان حقا، لكنت أول مثبت له، فعلم بذلك بطلان دعوى المشركين وفسادها، عقلا ونقلا».","the_verdict":"فالحاصل أنّ الآية سيقت مساقَ الشرط، **والمقصودُ بها إبطالُ المشروط**.\nفالحجّة تجري هكذا: لو ثبت الولدُ لزم أن يُعبد، لأنّ الولد جزءٌ من والده كما علّل الإمام، ولكان أكملُ الخلق أوّلَ من يعبده، وأكملُ الخلق أشدُّ الناس نفيًا له، فلم يثبت.\n⭐ وموضعُ الدقّة أنّ الدليل على انتفاء اللازم ليس خبرًا غائبًا يُطلب من بعيد، بل هو حالُ المتكلّم بين سامعيه. وقد جمع الإمامُ الطرفين في نصٍّ واحد: أوّليّةَ الانقياد، وأوّليّةَ الإنكار.\nوأمّا تعليقُ المسألة بالنبيّ دون سائر الخلق فلأنّ الفرض لا يُثمر إلّا إذا وقع فيمن هو أكملُ الناس انقيادًا. **فتخلّفُ من يتخلّف عن الحقّ لا يدلّ على شيء، وإنّما يدلّ تخلّفُ من لا يتخلّف.**\nوأمّا موضعُ ظهورها فقد قيّده الإمامُ بقوله: «عند من عرف أحوال الرسل». فهو وصفٌ لمن تعظُم الحجّةُ عنده، والمشركون كانوا أعرفَ الناس بحال المتكلّم بينهم؛ فلم يكن هذا القيدُ إخراجًا لهم بل إدخالًا.\n⭐ وأمّا الغلطُ عند من لم ينتبه فأن يُقرأ اللفظُ تنازلًا أو مجاملة، فيصير ما هو إبطالٌ إقرارًا.\nوممّا يُلحظ في صنيع الإمام أنّه ختم الوجهين بنتيجةٍ واحدة، فقال في الأوّل: «فعلم بذلك بطلانه»، وقال في الثاني: «فعلم بذلك بطلان دعوى المشركين». فاختلاف الطريقين لم يُخرج المآل عن واحد.","for_you":"فأمّا الذي تخرج به فثلاثة:\n**الأوّل: إذا عُرضت عليك دعوى تُنسب إلى الدين، فاسأل: من أولى الناس بها لو كانت حقًّا؟** ثمّ انظر في حال أعلم الناس بذلك الباب. فإن كان أعرفُهم به أبعدَهم عنه فذلك موضعُ نظر. امتحن هذا في دعوى بعينها سمعتَها هذا الشهر، واكتب جوابك في سطر.\nوالثاني، على الوجه الذي ذكره الإمامُ احتمالًا: أن تجعل من عبادتك القوليّة وقوفَك عند النصّ في وصف الله، فتثبت ما أثبته وتنفي ما نفاه. والامتحان: إذا سُئلت عن أمرٍ لم يبلغك فيه نصّ فقل لا أعلم، ولا تُجب بالظنّ.\nوالثالث: إذا نازعك أحدٌ فلا تبدأ بردّ أصل دعواه؛ بل اكتبها كما يقولها، ثمّ اكتب تحتها: فلو صحّت للزم كذا. ثمّ انظر أيلزم عليها ما لا يقوله هو. وهذا يُختبر بورقة، لا بشعور.","grade":"ma'thur","source":"تفسيرُ السعديّ لبيان المخاطَبين («أي: قل يا أيها الرسول الكريم»)، ووصفُه الربَّ في مقابلة دعواهم («وهو الواحد الأحد الفرد الصمد»)، وتقديرُه متعلَّقَ العبادة مع تعليله («لذلك الولد، لأنه جزء من والده»)، وإخبارُه عن حال النبيّ («وأنا أول الخلق انقيادا للأمور المحبوبة لله»)، ووصفُه الاحتجاجَ وموضعَ ظهوره («فهذا احتجاج عظيم عند من عرف أحوال الرسل»)، وتقريرُه أحوالَ الرسل («وأنه إذا علم أنهم أكمل الخلق»)، وتفريعُه عليه («فلو كان على هذا للرحمن ولد وهو الحق»)، والوجهُ الآخر بصيغة الاحتمال («ويحتمل أن معنى الآية»): كلُّها بنصّها في تفسير السعديّ (٤٣:٨١).","honesty":"وممّا يجب أن يُقال:\nتفريقُنا في التمهيد بين التعليق على الشرط وبين إمكان الوقوع، وقولُنا إنّ الخصم يُلزَم من جهة ما يسلّمه، تمهيدٌ منّا لتقريب وجه الحجّة، وليس نصًّا للسعديّ.\nوصوغُنا الحجّةَ في نظم مقدّمتين ونتيجة ترتيبٌ منّا على كلامه المجموع، وهو عنده مبثوثٌ في سياقٍ متّصل لا في هذا القالب.\nوقولُنا إنّ الدليل على انتفاء اللازم حالُ المتكلّم بين سامعيه صياغةٌ منّا لا لفظٌ له.\nوقولُنا إنّ الفرض لا يُثمر إلّا فيمن هو أكملُ الناس انقيادًا، وإنّ تخلّف من يتخلّف لا يدلّ، استنباطٌ منّا من قوله «أفضل الرسل أول من عبده».\nوقولُنا إنّ قيده «عند من عرف أحوال الرسل» مسلكُ ظهورٍ لا شرطُ لزوم، وإنّ المشركين داخلون فيه لمعرفتهم بحاله، استنباطٌ منّا على لفظه، ولم ينصّ هو على ذلك.\nوالوجهُ الثاني ذكره بصيغة الاحتمال، وقد بنينا عليه الوصيّة الثانية، فمن ردّه سقطت الوصيّة دون الحجّة. وهو عنده خبرٌ عن عبادة النبيّ نفسِه، فجعلُنا إيّاه عملًا للقارئ توسيعٌ منّا.\nوملاحظتُنا اتّحادَ النتيجة في الوجهين ملاحظةٌ منّا على لفظه.\nوذكرُنا للغلط ونسبتُه إلى من لم ينتبه، حكمٌ منّا لا نقلٌ عنه.\nوالوصايا الثلاث في آخر القضيّة وأمثلتُها منّا، لا وصيّةَ فيها للإمام ولا مثال.\nومن رأى أنّا وسّعنا فليردّه."}},{"n":82,"reflection":{"text":"«سبحان رب السماوات والأرض رب العرش عما يصفون»: تنزيهًا لربِّ السماواتِ والأرضِ وربِّ العرشِ عمّا يصفونه به من الولدِ والشريك؛ ففي هذا تنزيهُ الله عمّا لا يليق به؛ فسبّح الله ونزّهه عن كلِّ ما لا يليق به، فمن كان ربَّ السماواتِ والأرضِ والعرشِ منزّهٌ عن كلِّ نقص، فأكثر من تسبيحِ الله وتنزيهه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تسبيحُ الله وتنزيهُه عن كلِّ ما لا يليق به."},"action":{"text":"تأمّل تنزيهَ الله وتسبيحه: تنزيهًا وتقديسًا لربِّ السماواتِ والأرض، ربِّ العرشِ العظيمِ الذي استوى عليه، عمّا يصفه به المشركون من الولدِ والشريكِ والنقص «سبحان رب السماوات والأرض رب العرش عما يصفون»؛ ففي هذا تنزيهُ الله عمّا لا يليق به من الولدِ والشريكِ وكلِّ نقص؛ فربُّ السماواتِ والأرضِ والعرشِ منزّهٌ عن كلِّ ما نسبه إليه المشركون؛ فسبّح الله ونزّهه عن كلِّ ما لا يليق بجلالِه وكماله؛ وأكثر من تسبيحه وتنزيهه؛ فمن كان ربَّ السماواتِ والأرضِ والعرشِ العظيم، منزّهٌ عن كلِّ نقصٍ وعيبٍ وولدٍ وشريك؛ فسبحانه وتعالى عمّا يشركون؛ سبحانه وتعالى عمّا يقولون علوًّا كبيرًا؛ فاجعل التسبيحَ والتنزيهَ لله دأبك؛ فأكثر من قولِ: سبحان الله، سبحان ربّي العظيم؛ فبالتسبيحِ تنزّه الله عن كلِّ نقص، وتعظّمه حقَّ تعظيمه؛ فاعمر لسانك وقلبك بتسبيحِ الله وتنزيهه؛ فمن سبّح الله ونزّهه فقد عظّمه؛ فسبّح ربك ونزّهه عن كلِّ ما لا يليق به."}},{"n":83,"reflection":{"text":"«فذرهم يخوضوا ويلعبوا حتى يلاقوا يومهم الذي يوعدون»: فدعهم يخوضوا في باطلهم ويلعبوا حتى يلاقوا يومهم الذي يُوعَدون به؛ ففي هذا الأمرُ بالإعراضِ عن الخائضين وتهديدهم؛ فأعرض عن أهلِ الباطلِ والخوضِ واللعب، ولا تشغل بهم، فمصيرهم إلى يومٍ يُوعَدون به، فاشتغل بالحقِّ ودع الخائضين لمصيرهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإعراضُ عن أهلِ الخوضِ واللعب، والاشتغالُ بالحق."},"action":{"text":"تأمّل الأمرَ بالإعراضِ عن الخائضين: فذرهم يا محمدُ يخوضوا في باطلهم ولعبهم وغفلتهم، واتركهم؛ حتى يلاقوا يومهم الذي يُوعَدون به من العذابِ والحساب؛ فسيلقون جزاءهم «فذرهم يخوضوا ويلعبوا حتى يلاقوا يومهم الذي يوعدون»؛ ففي هذا الأمرُ بالإعراضِ عن الخائضين في الباطل، وتهديدهم بيومِ الوعيد؛ فدعهم في خوضهم ولعبهم وغفلتهم؛ فمصيرهم إلى العذابِ يومَ القيامة؛ فأعرض عن أهلِ الباطلِ والخوضِ واللعبِ والغفلة؛ ولا تشغل نفسك بهم وبجدالهم؛ ولا يحزنك إعراضهم؛ فمصيرهم إلى يومٍ يُوعَدون به من العذاب؛ فاشتغل أنت بالحقِّ والطاعةِ والدعوة؛ ودع الخائضين لمصيرهم؛ وإذا رأيت الذين يخوضون في آياتنا فأعرض عنهم حتى يخوضوا في حديثٍ غيره؛ فلا تجالس أهلَ الباطلِ في خوضهم؛ ولا تشاركهم في لعبهم وغفلتهم؛ بل أعرض عنهم، واشتغل بما ينفعك؛ فمن أعرض عن أهلِ الباطلِ واشتغل بالحقِّ سلم؛ فاجعل همّك الحقَّ والطاعة، ودع الخائضين لمصيرهم الموعود."}},{"n":84,"reflection":{"text":"«وهو الذي في السماء إله وفي الأرض إله وهو الحكيم العليم»، وهو الذي في السماءِ إلهٌ يُعبَد وفي الأرضِ إلهٌ يُعبَد، وهو الحكيمُ العليم؛ ففي هذا تقريرُ ألوهيةِ الله في السماءِ والأرض؛ فاعبد الله الذي هو إلهُ السماواتِ والأرض، فهو المعبودُ في كلِّ مكان، فأخلص له العبادةَ حيثما كنت، فالإلهُ الحقُّ إلهُ السماءِ والأرض.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"عبادةُ الله إلهِ السماءِ والأرض، وإخلاصُ العبادةِ له حيثما كنت."},"action":{"text":"تأمّل تقريرَ ألوهيةِ الله: وهو الله الذي في السماءِ إلهٌ معبودٌ بحق، وفي الأرضِ إلهٌ معبودٌ بحق؛ فهو المعبودُ في السماواتِ والأرض، لا معبودَ بحقٍّ سواه؛ وهو الحكيمُ في أفعاله وشرعه، العليمُ بكلِّ شيء «وهو الذي في السماء إله وفي الأرض إله وهو الحكيم العليم»؛ ففي هذا تقريرُ ألوهيةِ الله في السماءِ والأرض، وأنه المعبودُ بحقٍّ في كلِّ مكان؛ فالله إلهٌ واحدٌ معبودٌ في السماواتِ والأرض؛ يعبده أهلُ السماءِ من الملائكة، ويعبده أهلُ الأرضِ من المؤمنين؛ فاعبد الله الذي هو إلهُ السماواتِ والأرض؛ فهو المعبودُ بحقٍّ في كلِّ مكانٍ وزمان؛ فأخلص له العبادةَ حيثما كنت؛ ولا تعبد معه سواه؛ فالإلهُ الحقُّ هو إلهُ السماءِ والأرض؛ فلا معبودَ بحقٍّ إلا هو؛ فوحّده في ألوهيّته وعبادته؛ فمن عبد الله وحده في السماءِ والأرضِ فقد وحّده؛ ومن عبد معه غيره فقد أشرك؛ فأخلص العبادةَ لله إلهِ السماواتِ والأرض؛ فهو الحكيمُ العليمُ الذي يستحقّ العبادةَ وحده."}},{"n":85,"reflection":{"text":"«وتبارك الذي له ملك السماوات والأرض وما بينهما وعنده علم الساعة وإليه ترجعون»، وتعالى وكثر خيرُ الذي له ملكُ السماواتِ والأرضِ وما بينهما، وعنده علمُ الساعة، وإليه ترجعون؛ ففي هذا تعظيمُ الله وملكِه وعلمِه؛ فعظّم الله مالكَ كلِّ شيء، العالمَ بالساعة، الذي إليه المرجع، فاستعدّ للرجوعِ إليه، فمن كان له الملكُ وعلمُ الساعةِ يستحقّ التعظيمَ والعبادة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ الله مالكِ كلِّ شيء، والاستعدادُ للرجوعِ إليه."},"action":{"text":"تأمّل تعظيمَ الله وملكه وعلمه: وتبارك وتعالى وكثر خيرُه وعظُم شأنه، الذي له ملكُ السماواتِ والأرضِ وما بينهما، خلقًا وملكًا وتدبيرًا؛ وعنده وحده علمُ الساعةِ لا يعلم وقتها سواه؛ وإليه ترجعون جميعًا يومَ القيامةِ فيجازيكم «وتبارك الذي له ملك السماوات والأرض وما بينهما وعنده علم الساعة وإليه ترجعون»؛ ففي هذا تعظيمُ الله، وبيانُ ملكِه الشامل، واختصاصِه بعلمِ الساعة، وأنّ المرجعَ إليه؛ فله ملكُ كلِّ شيء؛ وعنده علمُ الساعةِ الذي استأثر به؛ وإليه مرجعُ الخلقِ أجمعين؛ فعظّم الله مالكَ كلِّ شيء، العالمَ بالساعةِ وحده، الذي إليه المرجعُ والمصير؛ فمن كان له ملكُ السماواتِ والأرض، وعنده علمُ الساعة، وإليه المرجع، يستحقّ التعظيمَ والعبادةَ والإجلال؛ فوحّده، وعظّمه، وأخلص له العبادة؛ واستعدّ للرجوعِ إليه بالإيمانِ والعملِ الصالح؛ فإليه مرجعك ومصيرك؛ فمن أيقن أنّ مرجعه إلى الله استعدّ للقائه؛ فاجعل تعظيمك لله مالكِ الملكِ العالمِ بالساعة؛ واستعدّ لمرجعك إليه؛ فتبارك الله ربُّ العالمين."}},{"n":86,"reflection":{"text":"«ولا يملك الذين يدعون من دونه الشفاعة إلا من شهد بالحق وهم يعلمون»، ولا يملك الذين يدعونهم من دونِ الله (الأصنامُ والمعبودات) الشفاعةَ، إلا من شهد بالحقِّ (بالتوحيد) وهم يعلمون؛ ففي هذا إبطالُ شفاعةِ المعبوداتِ الباطلة؛ فاعلم أنّ الشفاعةَ لا تكون إلا لأهلِ التوحيد، فلا تتعلّق بمن لا يشفع، بل حقّق التوحيدَ لتنال الشفاعة، فالشفاعةُ لأهلِ التوحيد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحقيقُ التوحيدِ لنيلِ الشفاعة، ونبذُ التعلّقِ بما لا يشفع."},"action":{"text":"تأمّل إبطالَ شفاعةِ المعبوداتِ الباطلة: ولا يملك الذين يدعونهم المشركون من دونِ الله من الأصنامِ والأوثانِ الشفاعةَ ولا يقدرون عليها؛ إلا من شهد بالحقِّ، بكلمةِ التوحيدِ لا إله إلا الله، وهم يعلمون معناها ويعملون بمقتضاها، كعيسى وعزيرٍ والملائكة، فهؤلاء قد يأذن الله لهم بالشفاعة «ولا يملك الذين يدعون من دونه الشفاعة إلا من شهد بالحق وهم يعلمون»؛ ففي هذا إبطالُ شفاعةِ المعبوداتِ الباطلة، وأنّ الشفاعةَ لا تكون إلا بشرطين: إذنِ الله، وأن تكون للموحّدين؛ فاعلم أنّ الأصنامَ والمعبوداتِ الباطلةَ لا تملك الشفاعةَ ولا تنفع عابديها؛ وأنّ الشفاعةَ لا تكون إلا لأهلِ التوحيدِ ومن شهد بالحقِّ عالمًا به عاملًا بمقتضاه؛ فلا تتعلّق بمن لا يشفع من الأصنامِ والأمواتِ والمخلوقات؛ ولا ترجُ شفاعةَ من لا يملكها؛ بل حقّق التوحيدَ لتنال الشفاعةَ التي يأذن الله بها؛ فأسعدُ الناسِ بشفاعةِ النبيِّ ﷺ من قال لا إله إلا الله خالصًا من قلبه؛ فالشفاعةُ لأهلِ التوحيدِ الذين شهدوا بالحقِّ عالمين عاملين؛ فحقّق التوحيدَ والإخلاص؛ فبهما تكون أهلًا لشفاعةِ من يأذن الله له."}},{"n":87,"reflection":{"text":"«ولئن سألتهم من خلقهم ليقولن الله فأنى يؤفكون»، ولئن سألت المشركين من خلقهم ليقولنّ: الله، فكيف يُصرَفون عن عبادته؟ ففي هذا إقرارهم بالخالقِ وإلزامهم بالتوحيد؛ فاعلم أنّ من أقرّ بأنّ الله خالقه يلزمه أن يعبده وحده، فوحّد خالقك، ولا تُصرَف عن عبادته إلى غيره، فالخالقُ هو المستحقُّ للعبادة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ الخالق، وعدمُ الانصرافِ عن عبادته إلى غيره."},"action":{"text":"تأمّل إقرارَ المشركين بالخالق: ولئن سألت المشركين من خلقهم ليقولنّ مقرّين: خلقنا الله؛ فإذا كانوا مقرّين بأنّ الله خالقهم، فكيف يُصرَفون ويُقلَبون عن عبادته إلى عبادةِ غيره؟ «ولئن سألتهم من خلقهم ليقولن الله فأنى يؤفكون»؛ ففي هذا إقرارُ المشركين بأنّ الله خالقهم، وإلزامهم بتوحيدِ العبادةِ الذي أنكروه؛ فهم يقرّون بأنّ الله خالقهم ورازقهم، ثم يشركون به في العبادة؛ فاعلم أنّ من أقرّ بأنّ الله خالقه يلزمه أن يعبده وحده؛ فالإقرارُ بالربوبيةِ يستلزم توحيدَ الألوهيةِ والعبادة؛ فوحّد خالقك في العبادةِ كما تفرّد بخلقك؛ ولا تُصرَف عن عبادةِ خالقك إلى عبادةِ غيره؛ فكيف تعبد من لم يخلقك، وتترك خالقك؟ فالخالقُ هو المستحقُّ للعبادةِ وحده؛ فأفرده بالعبادةِ كما تفرّد بالخلق؛ فمن أقرّ بأنّ الله الخالقُ ثم أشرك في عبادته فقد ناقض نفسه؛ فاعبد خالقك وحده، وأخلص له الدين؛ ولا تشرك به شيئًا؛ فالتوحيدُ حقُّ الخالقِ على المخلوق."}},{"n":88,"reflection":{"text":"«وقيله يا رب إن هؤلاء قوم لا يؤمنون»، وشكوى النبيِّ إلى ربه: يا ربِّ إنّ هؤلاء قومٌ لا يؤمنون؛ ففي هذا شكوى النبيِّ حالَ قومه إلى الله؛ فاشكُ حالك إلى الله وحده عند الشدّة، فالنبيُّ شكا حالَ قومه إلى الله، فاجعل شكواك إلى الله، فهو كاشفُ الهمّ ومجيبُ الدعاء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الشكوى إلى الله وحده عند الشدّة، وبثُّ الحالِ إليه."},"action":{"text":"تأمّل شكوى النبيِّ إلى ربه: والله يعلم قولَ نبيِّه وشكواه: يا ربِّ إنّ هؤلاء قومٌ لا يؤمنون بك ولا يستجيبون لدعوتي «وقيله يا رب إن هؤلاء قوم لا يؤمنون»؛ ففي هذا شكوى النبيِّ ﷺ حالَ قومه المعرضين إلى الله؛ فلمّا أعرضوا عن الحقِّ ولم يؤمنوا، شكا حالهم إلى الله؛ فاشكُ حالك وهمّك وحزنك إلى الله وحده عند الشدّةِ والكرب؛ فالنبيُّ ﷺ شكا حالَ قومه إلى الله؛ إنما أشكو بثّي وحزني إلى الله؛ فاجعل شكواك وبثّك إلى الله وحده، لا إلى الخلق؛ فهو كاشفُ الهمِّ والكرب، مجيبُ الدعاء؛ فبثّ حاجتك وشكواك إليه؛ ولا تشكُ الله إلى خلقه؛ بل اشكُ إلى الله؛ فمن لجأ إلى الله بشكواه كشف الله همّه؛ فاجعل الله ملجأك عند الشدائد؛ فاشكُ إليه، وادعه، وتوكّل عليه؛ فهو نعم المولى ونعم النصير؛ فمن شكا حاله إلى الله كفاه وأعانه."}},{"n":89,"reflection":{"text":"«فاصفح عنهم وقل سلام فسوف يعلمون»: فاصفح عنهم وأعرض، وقل: سلامٌ (متاركةً)، فسوف يعلمون عاقبةَ أمرهم؛ ففي هذا الأمرُ بالصفحِ والإعراضِ عن المعرضين؛ فاصفح عمّن أعرض عن الحقّ، وقابل جهلهم بالحلم، فالصفحُ عن الجاهلين من خلقِ الأنبياء، فاصفح واحلم، فسوف يعلم المعرضون عاقبتهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصفحُ والإعراضُ عن المعرضين، ومقابلةُ جهلهم بالحلم."},"action":{"text":"تأمّل ختامَ السورةِ بالأمرِ بالصفح: فاصفح عنهم يا محمدُ وأعرض عن أذاهم، وقل لهم: سلامٌ، أي متاركةً وتوديعًا، لا سلامَ تحيّةٍ ومحبّة؛ فسوف يعلمون عاقبةَ إعراضهم وتكذيبهم حين ينزل بهم العذاب «فاصفح عنهم وقل سلام فسوف يعلمون»؛ ففي هذا الأمرُ بالصفحِ والإعراضِ عن المعرضين المكذّبين، وتهديدهم؛ فاصفح عمّن أعرض عن الحقِّ وآذاك؛ وقابل جهلهم وأذاهم بالحلمِ والصفح؛ خذ العفوَ وأمر بالعرفِ وأعرض عن الجاهلين؛ فالصفحُ عن الجاهلين والإعراضُ عنهم من خلقِ الأنبياءِ وأتباعهم؛ فاصفح واحلم، ولا تقابل الإساءةَ بالإساءة؛ فادفع بالتي هي أحسن؛ ثم كِل أمرهم إلى الله؛ فسوف يعلمون عاقبةَ إعراضهم وتكذيبهم؛ فالصفحُ والحلمُ من عزمِ الأمور؛ فمن صفح وحلم نال أجرَ الله وعزّته؛ فاجعل الصفحَ والحلمَ خلقك مع الجاهلين والمعرضين؛ ثم انتظر عاقبةَ الله فيهم؛ فبهذا الأمرِ بالصفحِ تُختَم السورة، لتحمل القلبَ على الحلمِ والصفحِ والتوكّلِ على الله؛ فسوف يعلمون."}}]}],"coverage":{"covered":89,"total":89}};
